{"name": "bash", "arguments": {"command": "cat > /workspace/src/duration.go << 'GOEOF'
package main

import (
	"fmt"
	"unicode"
)

// parseDuration parses a humantime-compatible duration string.
// It returns the duration in nanoseconds and an error matching humantime's error messages.
func parseDuration(s string) (uint64, error) {
	// Trim leading/trailing whitespace like humantime does
	orig := s
	// humantime trims the string
	trimmed := trimWhitespace(s)
	if len(trimmed) == 0 {
		return 0, fmt.Errorf("value was empty")
	}

	s = trimmed
	var total uint64
	pos := 0

	for pos < len(s) {
		// Skip whitespace
		for pos < len(s) && s[pos] == ' ' {
			pos++
		}
		if pos >= len(s) {
			break
		}

		// Parse number
		numStart := pos
		for pos < len(s) && s[pos] >= '0' && s[pos] <= '9' {
			pos++
		}
		if pos == numStart {
			// Not a digit
			return 0, fmt.Errorf("expected number at %d", numStart)
		}

		numStr := s[numStart:pos]
		num, err := parseUint64(numStr)
		if err != nil {
			return 0, fmt.Errorf("expected number at %d", numStart)
		}

		// Skip whitespace between number and unit
		for pos < len(s) && s[pos] == ' ' {
			pos++
		}

		// Parse unit
		unitStart := pos
		for pos < len(s) && s[pos] != ' ' && s[pos] >= '0' {
			// Units are alphabetic, but we need to handle the case where
			// the next thing is a digit (concatenated durations like "1m30s")
			if s[pos] >= '0' && s[pos] <= '9' {
				break
			}
			pos++
		}

		// Actually, humantime parses unit as a sequence of non-digit, non-space chars
		// Let me re-parse the unit
		pos = unitStart
		for pos < len(s) && !isDigit(s[pos]) && s[pos] != ' ' {
			pos++
		}
		unitStr := s[unitStart:pos]

		if len(unitStr) == 0 {
			// No unit found
			return 0, fmt.Errorf("time unit needed, for example %ssec or %sms", numStr, numStr)
		}

		// Convert unit to nanoseconds
		unitNanos, ok := unitToNanos(unitStr)
		if !ok {
			return 0, fmt.Errorf("unknown time unit %q, supported units: ns, us, ms, sec, min, hours, days, weeks, months, years (and few variations)", unitStr)
		}

		// Check for overflow
		val, err := mulOverflow(num, unitNanos)
		if err != nil {
			// humantime wraps on overflow
			val = num * unitNanos // wrap around
		}
		total, _ = addOverflow(total, val)

		// Check for invalid character
		// After parsing number+unit, if the next char is not a digit, space, or end,
		// it's an invalid character
		if pos < len(s) && s[pos] != ' ' && !isDigit(s[pos]) {
			return 0, fmt.Errorf("invalid character at %d", pos)
		}
	}

	_ = orig
	return total, nil
}

func trimWhitespace(s string) string {
	start := 0
	end := len(s)
	for start < end && s[start] == ' ' {
		start++
	}
	for end > start && s[end-1] == ' ' {
		end--
	}
	return s[start:end]
}

func isDigit(b byte) bool {
	return b >= '0' && b <= '9'
}

func isAlpha(b byte) bool {
	return unicode.IsLetter(rune(b))
}

func parseUint64(s string) (uint64, error) {
	var val uint64
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, fmt.Errorf("not a digit")
		}
		val = val*10 + uint64(c-'0')
	}
	return val, nil
}

func mulOverflow(a, b uint64) (uint64, error) {
	return a * b, nil
}

func addOverflow(a, b uint64) (uint64, error) {
	return a + b, nil
}

// unitToNanos converts a time unit string to nanoseconds.
// Returns false if the unit is not recognized.
func unitToNanos(unit string) (uint64, bool) {
	switch unit {
	case "ns", "nsec":
		return 1, true
	case "us", "usec":
		return 1000, true
	case "ms", "msec":
		return 1000000, true
	case "s", "sec", "secs", "second", "seconds":
		return 1000000000, true
	case "m", "min", "mins", "minute", "minutes":
		return 60000000000, true
	case "h", "hr", "hrs", "hour", "hours":
		return 3600000000000, true
	case "d", "day", "days":
		return 86400000000000, true
	case "w", "week", "weeks":
		return 604800000000000, true
	case "M", "month", "months":
		return 2630016000000000, true
	case "y", "year", "years":
		return 31557600000000000, true
	default:
		return 0, false
	}
}
GOEOF
echo "Created duration.go""}}

{"name": "bash", "arguments": {"command": "cat > /workspace/src/duration.go << 'GOEOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// parseDuration parses a humantime-compatible duration string.
// Returns duration in nanoseconds and an error matching humantime's error messages.
func parseDuration(input string) (uint64, error) {
	// Trim leading/trailing whitespace
	s := strings.TrimSpace(input)
	if len(s) == 0 {
		return 0, fmt.Errorf("value was empty")
	}

	var total uint64
	pos := 0
	firstPair := true

	for {
		// Check for invalid character (after first pair, before whitespace skip)
		if !firstPair && pos < len(s) && s[pos] != ' ' && !isDigit(s[pos]) {
			return 0, fmt.Errorf("invalid character at %d", pos)
		}

		// Skip whitespace
		for pos < len(s) && s[pos] == ' ' {
			pos++
		}

		if pos >= len(s) {
			break
		}

		// Parse number (accumulate digits, skipping whitespace between digits)
		numStart := pos
		var numStr strings.Builder
		for pos < len(s) {
			if isDigit(s[pos]) {
				numStr.WriteByte(s[pos])
				pos++
			} else if s[pos] == ' ' {
				pos++
			} else {
				break
			}
		}

		if numStr.Len() == 0 {
			return 0, fmt.Errorf("expected number at %d", numStart)
		}

		// Skip whitespace between number and unit
		for pos < len(s) && s[pos] == ' ' {
			pos++
		}

		// Parse unit (ASCII alphabetic characters)
		unitStart := pos
		for pos < len(s) && isAlpha(s[pos]) {
			pos++
		}
		unitStr := s[unitStart:pos]

		if len(unitStr) == 0 {
			if pos < len(s) {
				return 0, fmt.Errorf("invalid character at %d", pos)
			}
			return 0, fmt.Errorf("time unit needed, for example %ssec or %sms", numStr.String(), numStr.String())
		}

		unitNanos, ok := unitToNanos(unitStr)
		if !ok {
			return 0, fmt.Errorf("unknown time unit %q, supported units: ns, us, ms, sec, min, hours, days, weeks, months, years (and few variations)", unitStr)
		}

		num, err := strconv.ParseUint(numStr.String(), 10, 64)
		if err != nil {
			// Overflow - wrap like humantime
			num = parseUintWrap(numStr.String())
		}

		total = total + num*unitNanos // wraps on overflow
		firstPair = false
	}

	return total, nil
}

func parseUintWrap(s string) uint64 {
	var val uint64
	for _, c := range s {
		val = val*10 + uint64(c-'0')
	}
	return val
}

func isDigit(b byte) bool {
	return b >= '0' && b <= '9'
}

func isAlpha(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}

// unitToNanos converts a time unit string to nanoseconds.
func unitToNanos(unit string) (uint64, bool) {
	switch unit {
	case "ns", "nsec":
		return 1, true
	case "us", "usec":
		return 1000, true
	case "ms", "msec":
		return 1000000, true
	case "s", "sec", "secs", "second", "seconds":
		return 1000000000, true
	case "m", "min", "mins", "minute", "minutes":
		return 60000000000, true
	case "h", "hr", "hrs", "hour", "hours":
		return 3600000000000, true
	case "d", "day", "days":
		return 86400000000000, true
	case "w", "week", "weeks":
		return 604800000000000, true
	case "M", "month", "months":
		return 2630016000000000, true
	case "y", "year", "years":
		return 31557600000000000, true
	default:
		return 0, false
	}
}
