{"name": "bash", "arguments": {"command": "cat > /workspace/src/cli.go << 'GOEOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const versionString = "bkt 0.8.2"

const helpText = `CLI and Rust library for caching subprocess invocations

Usage: %s [OPTIONS] --ttl <DURATION> -- <COMMAND>...

Arguments:
  <COMMAND>...  The command to run

Options:
      --ttl <DURATION>    Duration the cached result will be valid for [env: BKT_TTL=] [aliases:
                          --time-to-live]
      --stale <DURATION>  Duration after which the result will be asynchronously refreshed
      --warm              Asynchronously execute and cache the given command, even if it's already
                          cached
      --force             Execute and cache the given command, even if it's already cached
      --cwd               Includes the current working directory in the cache key, so that the same
                          command run in different directories caches separately [aliases:
                          --use-working-dir]
      --env <NAME>        Includes the given environment variable in the cache key, so that the same
                          command run with different values for the given variables caches
                          separately [aliases: --use-environment]
      --modtime <FILE>    Includes the last modification time of the given file(s) in the cache key,
                          so that the same command run with different modtimes for the given files
                          caches separately [aliases: --use-file-modtime]
      --discard-failures  Don't cache invocations that fail (non-zero exit code). USE CAUTION when
                          passing this flag, as unexpected failures can lead to a spike in
                          invocations which can exacerbate ongoing issues, effectively a DDoS
      --scope <NAME>      If set, all cached data will be scoped to this value, preventing
                          collisions with commands cached with different scopes [env: BKT_SCOPE=]
      --cache-dir <DIR>   The directory under which to persist cached invocations; defaults to the
                          system's temp directory. Setting this to a directory backed by RAM or an
                          SSD, such as a tmpfs partition, will significantly reduce caching overhead
                          [env: BKT_CACHE_DIR=]
  -h, --help              Print help
  -V, --version           Print version`

type cliArgs struct {
	ttl             string
	ttlSet          bool
	stale           string
	staleSet        bool
	warm            bool
	force           bool
	cwd             bool
	env             []string
	modtime         []string
	discardFailures bool
	scope           string
	scopeSet        bool
	cacheDir        string
	cacheDirSet     bool
	command         []string
}

// parseCLI parses command-line arguments, mimicking clap's behavior.
func parseCLI() (*cliArgs, error) {
	args := os.Args[1:]
	binName := filepath.Base(os.Args[0])

	// Check for help/version first (clap priority)
	for _, arg := range args {
		if arg == "--" {
			break
		}
		if arg == "--help" || arg == "-h" {
			fmt.Printf(helpText+"\n", binName)
			os.Exit(0)
		}
		if arg == "--version" || arg == "-V" {
			fmt.Println(versionString)
			os.Exit(0)
		}
	}

	parsed := &cliArgs{}

	// Track order of provided args for usage messages
	var argOrder []string // e.g. "--stale", "--scope", etc.
	argProvided := map[string]bool{}

	// Helper to get env value
	getEnv := func(name string) (string, bool) {
		v := os.Getenv(name)
		return v, v != ""
	}

	// Resolve env vars for scope and cacheDir
	if v, ok := getEnv("BKT_SCOPE"); ok {
		parsed.scope = v
		parsed.scopeSet = true
		argProvided["--scope"] = true
		argProvidedEnv := true
		_ = argProvidedEnv
		argOrder = append(argOrder, "--scope")
	}
	if v, ok := getEnv("BKT_CACHE_DIR"); ok {
		parsed.cacheDir = v
		parsed.cacheDirSet = true
		argProvided["--cache-dir"] = true
		argOrder = append(argOrder, "--cache-dir")
	}
	if v, ok := getEnv("BKT_TTL"); ok {
		parsed.ttl = v
		parsed.ttlSet = true
	}

	// Parse arguments
	i := 0
	commandStarted := false
	for i < len(args) {
		arg := args[i]

		if commandStarted {
			parsed.command = append(parsed.command, arg)
			i++
			continue
		}

		if arg == "--" {
			commandStarted = true
			i++
			continue
		}

		// Check if it's a flag (starts with --)
		if strings.HasPrefix(arg, "--") {
			// Parse flag name and value
			flagName := arg
			flagValue := ""
			hasValue := false
			if idx := strings.Index(arg, "="); idx >= 0 {
				flagName = arg[:idx]
				flagValue = arg[idx+1:]
				hasValue = true
			}

			// Resolve aliases
			canonicalName := resolveAlias(flagName)
			if canonicalName == "" {
				// Unknown flag
				printError(binName, fmt.Sprintf("unexpected argument '%s' found", arg),
					[]string{fmt.Sprintf("tip: to pass '%s' as a value, use '-- %s'", arg, arg)},
					getUsageLine(binName, argOrder, argProvided, parsed, false))
				os.Exit(2)
			}

			// Check conflicts
			if canonicalName == "--warm" {
				if parsed.force {
					printConflictError(binName, "--warm", []string{"--force"}, argOrder, argProvided, parsed)
					os.Exit(2)
				}
				if parsed.staleSet {
					printConflictError(binName, "--warm", []string{"--stale <DURATION>"}, argOrder, argProvided, parsed)
					os.Exit(2)
				}
			}
			if canonicalName == "--force" && parsed.warm {
				printConflictError(binName, "--force", []string{"--warm"}, argOrder, argProvided, parsed)
				os.Exit(2)
			}
			if canonicalName == "--stale" && parsed.warm {
				printConflictError(binName, "--stale", []string{"--warm"}, argOrder, argProvided, parsed)
				os.Exit(2)
			}

			// Handle boolean flags
			if canonicalName == "--warm" || canonicalName == "--force" || canonicalName == "--cwd" || canonicalName == "--discard-failures" {
				if hasValue {
					// Boolean flags don't take values - but clap would error
					printError(binName, fmt.Sprintf("unexpected value '%s' for '%s'", flagValue, canonicalName),
						nil, getUsageLine(binName, argOrder, argProvided, parsed, false))
					os.Exit(2)
				}
				setBool(parsed, canonicalName, true)
				if !argProvided[canonicalName] {
					argOrder = append(argOrder, canonicalName)
					argProvided[canonicalName] = true
				}
				i++
				continue
			}

			// Handle value flags
			if canonicalName == "--ttl" || canonicalName == "--stale" || canonicalName == "--env" ||
				canonicalName == "--modtime" || canonicalName == "--scope" || canonicalName == "--cache-dir" {
				if !hasValue {
					// Need next arg as value
					if i+1 >= len(args) {
						// Missing value
						printError(binName, fmt.Sprintf("a value is required for '%s' but none was supplied", canonicalName),
							nil, getUsageLine(binName, argOrder, argProvided, parsed, false))
						os.Exit(2)
					}
					flagValue = args[i+1]
					i += 2
				} else {
					i++
				}

				// Validate and set the value
				err := setValue(parsed, canonicalName, flagValue)
				if err != nil {
					fmt.Fprintf(os.Stderr, "error: %s\n\nFor more information, try '--help'.\n", err.Error())
					os.Exit(2)
				}
				if !argProvided[canonicalName] || canonicalName == "--env" || canonicalName == "--modtime" {
					if canonicalName != "--env" && canonicalName != "--modtime" {
						argOrder = append(argOrder, canonicalName)
					}
					argProvided[canonicalName] = true
				}
				continue
			}
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// Short flags
			if arg == "-h" {
				fmt.Printf(helpText+"\n", binName)
				os.Exit(0)
			}
			if arg == "-V" {
				fmt.Println(versionString)
				os.Exit(0)
			}
			// Unknown short flag
			printError(binName, fmt.Sprintf("unexpected argument '%s' found", arg),
				[]string{fmt.Sprintf("tip: to pass '%s' as a value, use '-- %s'", arg, arg)},
				getUsageLine(binName, argOrder, argProvided, parsed, false))
			os.Exit(2)
		} else {
			// Not a flag - this would be a positional argument before --
			// clap treats this as unexpected
			printError(binName, fmt.Sprintf("unexpected argument '%s' found", arg),
				[]string{fmt.Sprintf("tip: to pass '%s' as a value, use '-- %s'", arg, arg)},
				getUsageLine(binName, argOrder, argProvided, parsed, false))
			os.Exit(2)
		}
	}

	// Check required args
	var missing []string
	if !parsed.ttlSet {
		missing = append(missing, "--ttl <DURATION>")
	}
	if len(parsed.command) == 0 {
		missing = append(missing, "<COMMAND>...")
	}

	if len(missing) > 0 {
		var sb strings.Builder
		sb.WriteString("the following required arguments were not provided:\n")
		for _, m := range missing {
			sb.WriteString("  " + m + "\n")
		}
		sb.WriteString("\n  tip: Prior to 0.8.0 --ttl was optional, and defaulted to 60 seconds. To preserve this behavior pass `--ttl=1m` or set `BKT_TTL=1m` in your environment.")
		printError(binName, sb.String(), nil, getUsageLine(binName, argOrder, argProvided, parsed, false))
		os.Exit(2)
	}

	return parsed, nil
}

func resolveAlias(name string) string {
	switch name {
	case "--ttl", "--time-to-live":
		return "--ttl"
	case "--stale":
		return "--stale"
	case "--warm":
		return "--warm"
	case "--force":
		return "--force"
	case "--cwd", "--use-working-dir":
		return "--cwd"
	case "--env", "--use-environment":
		return "--env"
	case "--modtime", "--use-file-modtime":
		return "--modtime"
	case "--discard-failures":
		return "--discard-failures"
	case "--scope":
		return "--scope"
	case "--cache-dir":
		return "--cache-dir"
	default:
		return ""
	}
}

func setBool(parsed *cliArgs, name string, val bool) {
	switch name {
	case "--warm":
		parsed.warm = val
	case "--force":
		parsed.force = val
	case "--cwd":
		parsed.cwd = val
	case "--discard-failures":
		parsed.discardFailures = val
	}
}

func setValue(parsed *cliArgs, name, value string) error {
	switch name {
	case "--ttl":
		// Validate duration
		_, err := parseDuration(value)
		if err != nil {
			return fmt.Errorf("invalid value '%s' for '--ttl <DURATION>': %s", value, err.Error())
		}
		parsed.ttl = value
		parsed.ttlSet = true
	case "--stale":
		_, err := parseDuration(value)
		if err != nil {
			return fmt.Errorf("invalid value '%s' for '--stale <DURATION>': %s", value, err.Error())
		}
		parsed.stale = value
		parsed.staleSet = true
	case "--env":
		parsed.env = append(parsed.env, value)
	case "--modtime":
		parsed.modtime = append(parsed.modtime, value)
	case "--scope":
		parsed.scope = value
		parsed.scopeSet = true
	case "--cache-dir":
		parsed.cacheDir = value
		parsed.cacheDirSet = true
	}
	return nil
}

// getUsageLine generates the usage line for error messages.
// It includes required args, provided args (in order), and optionally the full [OPTIONS] form.
func getUsageLine(binName string, argOrder []string, argProvided map[string]bool, parsed *cliArgs, fullForm bool) string {
	var parts []string
	parts = append(parts, binName)

	if fullForm {
		parts = append(parts, "[OPTIONS]")
	}

	// Always include --ttl (required)
	parts = append(parts, "--ttl <DURATION>")

	// Include provided args in order (excluding --ttl which is already included)
	for _, arg := range argOrder {
		if arg == "--ttl" {
			continue
		}
		parts = append(parts, formatArgForUsage(arg))
	}

	parts = append(parts, "--")
	parts = append(parts, "<COMMAND>...")

	return "Usage: " + strings.Join(parts, " ")
}

func formatArgForUsage(arg string) string {
	switch arg {
	case "--stale":
		return "--stale <DURATION>"
	case "--warm":
		return "--warm"
	case "--force":
		return "--force"
	case "--cwd":
		return "--cwd"
	case "--env":
		return "--env <NAME>"
	case "--modtime":
		return "--modtime <FILE>"
	case "--discard-failures":
		return "--discard-failures"
	case "--scope":
		return "--scope <NAME>"
	case "--cache-dir":
		return "--cache-dir <DIR>"
	default:
		return arg
	}
}

func printError(binName, message string, tips []string, usage string) {
	fmt.Fprintf(os.Stderr, "error: %s\n\n", message)
	if len(tips) > 0 {
		for _, t := range tips {
			fmt.Fprintf(os.Stderr, "  %s\n\n", t)
		}
	}
	fmt.Fprintf(os.Stderr, "%s\n\n", usage)
	fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
}

func printConflictError(binName string, arg1 string, conflicts []string, argOrder []string, argProvided map[string]bool, parsed *cliArgs) {
	if len(conflicts) == 1 {
		fmt.Fprintf(os.Stderr, "error: the argument '%s' cannot be used with '%s'\n\n", arg1, conflicts[0])
	} else {
		fmt.Fprintf(os.Stderr, "error: the argument '%s' cannot be used with:\n", arg1)
		for _, c := range conflicts {
			fmt.Fprintf(os.Stderr, "  %s\n", c)
		}
		fmt.Fprintln(os.Stderr)
	}

	// Usage line: include --ttl, the conflicting arg (arg1), but NOT the conflicted args
	// Build arg order excluding conflicted args
	conflictSet := map[string]bool{}
	for _, c := range conflicts {
		conflictSet[c] = true
	}

	var parts []string
	parts = append(parts, binName)
	parts = append(parts, "--ttl <DURATION>")

	// Include arg1 if it's in the order
	for _, arg := range argOrder {
		if arg == "--ttl" {
			continue
		}
		if conflictSet[formatArgForUsage(arg)] {
			continue
		}
		// Also check if this arg IS arg1
		if formatArgForUsage(arg) == arg1 {
			parts = append(parts, formatArgForUsage(arg))
			continue
		}
		parts = append(parts, formatArgForUsage(arg))
	}

	// Make sure arg1 is included (it might not be in argOrder if it was just set)
	// Actually, for --warm conflict, --warm IS in argOrder
	// For --force conflict with --warm, --force is the arg being set and --warm is the conflict
	// The usage shows the arg that was already present

	parts = append(parts, "--")
	parts = append(parts, "<COMMAND>...")

	fmt.Fprintf(os.Stderr, "Usage: %s\n\n", strings.Join(parts, " "))
	fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
}
GOEOF
echo "Created cli.go""}}

{"name": "bash", "arguments": {"command": "cat > /workspace/src/cache.go << 'GOEOF'
package main

import (
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"syscall"
	"time"
)

// CacheEntry represents a cached command execution.
type CacheEntry struct {
	Stdout   []byte
	Stderr   []byte
	ExitCode int
	ExecTime int64 // Unix timestamp when the command was executed
}

// cacheKeyData builds the data that will be hashed to form the cache key.
func cacheKeyData(parsed *cliArgs) []byte {
	// Use a hash writer approach - feed all components into a hasher
	h := sha256.New()

	// Command
	writeU64(h, uint64(len(parsed.command)))
	for _, cmd := range parsed.command {
		h.Write([]byte(cmd))
		writeU64(h, uint64(len(cmd)))
	}

	// CWD
	if parsed.cwd {
		cwd, err := os.Getwd()
		if err == nil {
			h.Write([]byte(cwd))
			writeU64(h, uint64(len(cwd)))
		}
	}

	// Env vars
	for _, envName := range parsed.env {
		h.Write([]byte(envName))
		writeU64(h, uint64(len(envName)))
		envVal := os.Getenv(envName)
		h.Write([]byte(envVal))
		writeU64(h, uint64(len(envVal)))
	}

	// Modtimes
	for _, file := range parsed.modtime {
		h.Write([]byte(file))
		writeU64(h, uint64(len(file)))
		info, err := os.Stat(file)
		if err == nil {
			modTime := info.ModTime().UnixNano()
			writeI64(h, modTime)
		}
	}

	return h.Sum(nil)
}

// cacheKeyHash returns the 16-hex-char uppercase hash for the cache key.
func cacheKeyHash(parsed *cliArgs) string {
	data := cacheKeyData(parsed)
	// Use first 8 bytes of SHA-256
	return fmt.Sprintf("%016X", binary.BigEndian.Uint64(data[:8]))
}

// cacheKeyFilename returns the filename for the keys directory.
// If scope is set, it's base64(scope).hash
func cacheKeyFilename(parsed *cliArgs) string {
	hash := cacheKeyHash(parsed)
	if parsed.scopeSet && parsed.scope != "" {
		encoded := base64.StdEncoding.EncodeToString([]byte(parsed.scope))
		return encoded + "." + hash
	}
	return hash
}

// getCacheDir returns the cache directory path.
func getCacheDir(parsed *cliArgs) string {
	var baseDir string
	if parsed.cacheDirSet && parsed.cacheDir != "" {
		baseDir = parsed.cacheDir
	} else if v := os.Getenv("BKT_TMPDIR"); v != "" {
		baseDir = v
	} else {
		baseDir = os.TempDir()
	}

	uid := os.Getuid()
	return filepath.Join(baseDir, fmt.Sprintf("bkt-0.8-cache-u%d", uid))
}

// getTTLSeconds returns the TTL in seconds (rounded up).
func getTTLSeconds(nanos uint64) uint64 {
	secs := nanos / 1000000000
	if nanos%1000000000 > 0 {
		secs++
	}
	if secs == 0 {
		secs = 1
	}
	return secs
}

// ensureCacheDir creates the cache directory structure.
func ensureCacheDir(cacheDir string) error {
	if err := os.MkdirAll(cacheDir, 0o700); err != nil {
		return err
	}
	keysDir := filepath.Join(cacheDir, "keys")
	if err := os.MkdirAll(keysDir, 0o700); err != nil {
		return err
	}
	dataDir := filepath.Join(cacheDir, "data")
	if err := os.MkdirAll(dataDir, 0o700); err != nil {
		return err
	}
	// Create last_cleanup if it doesn't exist
	lastCleanup := filepath.Join(cacheDir, "last_cleanup")
	if _, err := os.Stat(lastCleanup); os.IsNotExist(err) {
		f, err := os.OpenFile(lastCleanup, os.O_CREATE|os.O_WRONLY, 0o644)
		if err != nil {
			return err
		}
		f.Close()
	}
	return nil
}

// writeCacheEntry writes the cache entry to disk and creates the symlink.
func writeCacheEntry(cacheDir string, ttlSeconds uint64, keyFilename string, entry *CacheEntry) error {
	dataDir := filepath.Join(cacheDir, "data", strconv.FormatUint(ttlSeconds, 10))
	if err := os.MkdirAll(dataDir, 0o700); err != nil {
		return err
	}

	// Create temp file with random name
	tmpName := "data." + randomString(14)
	tmpPath := filepath.Join(dataDir, tmpName)

	f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_EXCL, 0o644)
	if err != nil {
		return err
	}

	// Write: exec_time (8 bytes), exit_code (4 bytes), stdout_len (8 bytes), stdout, stderr_len (8 bytes), stderr
	buf := make([]byte, 8+4+8)
	binary.LittleEndian.PutUint64(buf[0:8], uint64(entry.ExecTime))
	binary.LittleEndian.PutUint32(buf[8:12], uint32(entry.ExitCode))
	binary.LittleEndian.PutUint64(buf[12:20], uint64(len(entry.Stdout)))

	_, err = f.Write(buf)
	if err != nil {
		f.Close()
		os.Remove(tmpPath)
		return err
	}
	if len(entry.Stdout) > 0 {
		_, err = f.Write(entry.Stdout)
		if err != nil {
			f.Close()
			os.Remove(tmpPath)
			return err
		}
	}
	stderrLenBuf := make([]byte, 8)
	binary.LittleEndian.PutUint64(stderrLenBuf, uint64(len(entry.Stderr)))
	_, err = f.Write(stderrLenBuf)
	if err != nil {
		f.Close()
		os.Remove(tmpPath)
		return err
	}
	if len(entry.Stderr) > 0 {
		_, err = f.Write(entry.Stderr)
		if err != nil {
			f.Close()
			os.Remove(tmpPath)
			return err
		}
	}
	f.Close()

	// Create symlink: keys/{keyFilename} -> data/{ttl}/data.{random}
	keysDir := filepath.Join(cacheDir, "keys")
	symlinkPath := filepath.Join(keysDir, keyFilename)

	// Remove existing symlink if any
	os.Remove(symlinkPath)

	// Create relative symlink
	relPath := filepath.Join("..", "data", strconv.FormatUint(ttlSeconds, 10), tmpName)
	err = os.Symlink(relPath, symlinkPath)
	if err != nil {
		// Try absolute path
		absPath, _ := filepath.Abs(tmpPath)
		os.Symlink(absPath, symlinkPath)
	}

	return nil
}

// readCacheEntry reads a cache entry from the symlink.
// Returns the entry and the time it was cached, or error if not found/expired.
func readCacheEntry(cacheDir string, keyFilename string) (*CacheEntry, error) {
	keysDir := filepath.Join(cacheDir, "keys")
	symlinkPath := filepath.Join(keysDir, keyFilename)

	dataPath, err := os.Readlink(symlinkPath)
	if err != nil {
		return nil, err
	}

	// Resolve relative path
	if !filepath.IsAbs(dataPath) {
		dataPath = filepath.Join(keysDir, dataPath)
	}

	f, err := os.Open(dataPath)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	// Read header
	header := make([]byte, 8+4+8)
	_, err = io.ReadFull(f, header)
	if err != nil {
		return nil, err
	}

	entry := &CacheEntry{}
	entry.ExecTime = int64(binary.LittleEndian.Uint64(header[0:8]))
	entry.ExitCode = int(binary.LittleEndian.Uint32(header[8:12]))
	stdoutLen := binary.LittleEndian.Uint64(header[12:20])

	if stdoutLen > 0 {
		entry.Stdout = make([]byte, stdoutLen)
		_, err = io.ReadFull(f, entry.Stdout)
		if err != nil {
			return nil, err
		}
	}

	stderrLenBuf := make([]byte, 8)
	_, err = io.ReadFull(f, stderrLenBuf)
	if err != nil {
		return nil, err
	}
	stderrLen := binary.LittleEndian.Uint64(stderrLenBuf)

	if stderrLen > 0 {
		entry.Stderr = make([]byte, stderrLen)
		_, err = io.ReadFull(f, entry.Stderr)
		if err != nil {
			return nil, err
		}
	}

	return entry, nil
}

// getTTLDirFromSymlink reads the symlink and extracts the TTL directory name.
func getTTLDirFromSymlink(cacheDir, keyFilename string) (string, error) {
	keysDir := filepath.Join(cacheDir, "keys")
	symlinkPath := filepath.Join(keysDir, keyFilename)

	dataPath, err := os.Readlink(symlinkPath)
	if err != nil {
		return "", err
	}

	// The path is like ../data/{ttl}/data.{random} or absolute
	// Extract the TTL directory
	parts := strings.Split(dataPath, string(filepath.Separator))
	for i, p := range parts {
		if p == "data" && i+1 < len(parts) {
			return parts[i+1], nil
		}
	}
	return "", fmt.Errorf("could not find TTL directory in path")
}

// cleanupCache removes expired entries from the cache.
func cleanupCache(cacheDir string) {
	// Check last_cleanup timestamp
	lastCleanup := filepath.Join(cacheDir, "last_cleanup")
	info, err := os.Stat(lastCleanup)
	if err == nil {
		// Only cleanup every 30 minutes
		if time.Since(info.ModTime()) < 30*time.Minute {
			return
		}
	}

	// Update last_cleanup
	now := time.Now()
	os.Chtimes(lastCleanup, now, now)

	// Walk data directories and remove expired entries
	dataDir := filepath.Join(cacheDir, "data")
	entries, err := os.ReadDir(dataDir)
	if err != nil {
		return
	}

	now = time.Now()
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		ttlSec, err := strconv.ParseInt(entry.Name(), 10, 64)
		if err != nil {
			continue
		}

		subDir := filepath.Join(dataDir, entry.Name())
		files, err := os.ReadDir(subDir)
		if err != nil {
			continue
		}

		for _, file := range files {
			if file.IsDir() {
				continue
			}
			info, err := file.Info()
			if err != nil {
				continue
			}
			// Check if the file is older than TTL
			if now.Sub(info.ModTime()) > time.Duration(ttlSec)*time.Second {
				os.Remove(filepath.Join(subDir, file.Name()))
			}
		}
	}
}

func writeU64(w io.Writer, val uint64) {
	buf := make([]byte, 8)
	binary.LittleEndian.PutUint64(buf, val)
	w.Write(buf)
}

func writeI64(w io.Writer, val int64) {
	buf := make([]byte, 8)
	binary.LittleEndian.PutUint64(buf, uint64(val))
	w.Write(buf)
}

var _ = syscall.Getuid
