package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
	"syscall"
)

// executeCommand runs the command, streaming stdout/stderr while capturing them.
// Returns the captured stdout, stderr, and exit code.
func executeCommand(command []string) (stdout, stderr []byte, exitCode int, execErr error) {
	if len(command) == 0 {
		return nil, nil, 0, nil
	}

	cmd := exec.Command(command[0], command[1:]...)
	cmd.Env = os.Environ()

	// Create pipes for stdout and stderr
	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		return nil, nil, 127, fmt.Errorf("bkt: Subprocess execution failed: %v", err)
	}
	stderrPipe, err := cmd.StderrPipe()
	if err != nil {
		return nil, nil, 127, fmt.Errorf("bkt: Subprocess execution failed: %v", err)
	}

	var stdoutBuf, stderrBuf bytes.Buffer
	stdoutDone := make(chan struct{})
	stderrDone := make(chan struct{})

	// Copy stdout while capturing
	go func() {
		mw := io.MultiWriter(os.Stdout, &stdoutBuf)
		io.Copy(mw, stdoutPipe)
		close(stdoutDone)
	}()

	// Copy stderr while capturing
	go func() {
		mw := io.MultiWriter(os.Stderr, &stderrBuf)
		io.Copy(mw, stderrPipe)
		close(stderrDone)
	}()

	err = cmd.Start()
	if err != nil {
		// Handle command not found
		return nil, nil, 127, formatExecError(command[0], err)
	}

	<-stdoutDone
	<-stderrDone

	err = cmd.Wait()

	exitCode = 0
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			if status, ok := exitErr.Sys().(syscall.WaitStatus); ok {
				if status.Signaled() {
					exitCode = 126
				} else {
					exitCode = status.ExitStatus()
				}
			} else {
				exitCode = 1
			}
		} else {
			exitCode = 1
		}
	}

	return stdoutBuf.Bytes(), stderrBuf.Bytes(), exitCode, nil
}

func formatExecError(cmd string, err error) error {
	// Check if it's a "command not found" or "permission denied" error
	if pathErr, ok := err.(*exec.Error); ok {
		if pathErr.Err == exec.ErrNotFound || pathErr.Err.Error() == "command not found" {
			return fmt.Errorf("bkt: Subprocess execution failed: Failed to run command: %q: No such file or directory (os error 2)", cmd)
		}
	}

	// Check for PathError
	if pathErr, ok := err.(*os.PathError); ok {
		errno, ok := pathErr.Err.(syscall.Errno)
		if ok {
			if errno == syscall.ENOENT {
				return fmt.Errorf("bkt: Subprocess execution failed: Failed to run command: %q: No such file or directory (os error 2)", cmd)
			}
			if errno == syscall.EACCES {
				return fmt.Errorf("bkt: Subprocess execution failed: Failed to run command: %q: Permission denied (os error 13)", cmd)
			}
			return fmt.Errorf("bkt: Subprocess execution failed: Failed to run command: %q: %s (os error %d)", cmd, errno.Error(), int(errno))
		}
	}

	return fmt.Errorf("bkt: Subprocess execution failed: %v", err)
}
