// resolveTTLNanos parses the TTL string and returns nanoseconds.
func resolveTTLNanos(ttlStr string) uint64 {
	nanos, err := parseDuration(ttlStr)
	if err != nil {
		// Should have been validated earlier, but handle gracefully
		return 60000000000 // 1 minute default
	}
	return nanos
}

// spawnBackgroundRefresh spawns a child bkt process with --force to refresh the cache.
func spawnBackgroundRefresh(parsed *cliArgs) {
	// Build the argument list for the child process
	var args []string

	// Replace --warm with --force, keep all other flags
	args = append(args, "--force")

	if parsed.staleSet {
		args = append(args, "--stale", parsed.stale)
	}
	if parsed.cwd {
		args = append(args, "--cwd")
	}
	for _, e := range parsed.env {
		args = append(args, "--env", e)
	}
	for _, m := range parsed.modtime {
		args = append(args, "--modtime", m)
	}
	if parsed.discardFailures {
		args = append(args, "--discard-failures")
	}
	if parsed.scopeSet && parsed.scope != "" {
		args = append(args, "--scope", parsed.scope)
	}
	if parsed.cacheDirSet && parsed.cacheDir != "" {
		args = append(args, "--cache-dir", parsed.cacheDir)
	}
	args = append(args, "--ttl", parsed.ttl)
	args = append(args, "--")
	args = append(args, parsed.command...)

	// Get the path to this executable
	execPath, err := os.Executable()
	if err != nil {
		execPath = os.Args[0]
	}

	cmd := exec.Command(execPath, args...)
	cmd.Env = os.Environ()
	cmd.Stdin = nil
	cmd.Stdout = nil
	cmd.Stderr = nil
	// Detach the process
	cmd.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
	cmd.Start()
}

// formatDurationPanic replicates Rust's panic output format.
func panicMsg(file string, line int, col int, msg string) {
	pid := os.Getpid()
	// Rust panic format:
	// (blank line)
	// thread 'main' (PID) panicked at FILE:LINE:COL:
	// MESSAGE
	// note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace
	tid := pid
	_ = tid
	fmt.Fprintf(os.Stderr, "\nthread 'main' (%d) panicked at %s:%d:%d:\n%s\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n",
		pid, file, line, col, msg)
}

