package main

import (
	"fmt"
	"os"
	"time"
)

func main() {
	parsed := mustParseCLI()

	ttlNanos := resolveTTLNanos(parsed.ttl)
	ttlDuration := time.Duration(ttlNanos) * time.Nanosecond

	if ttlNanos == 0 {
		panicMsg("src/main.rs", 74, 5, "--ttl cannot be zero")
		os.Exit(101)
	}

	var staleDuration time.Duration
	if parsed.staleSet {
		staleNanos := resolveTTLNanos(parsed.stale)
		staleDuration = time.Duration(staleNanos) * time.Nanosecond
		if staleNanos >= ttlNanos {
			panicMsg("src/main.rs", 77, 9, "--stale must be less than --ttl")
			os.Exit(101)
		}
	}

	if parsed.warm {
		spawnBackgroundRefresh(parsed)
		os.Exit(0)
	}

	cacheDir := getCacheDir(parsed)
	ensureCacheDir(cacheDir)

	go cleanupCache(cacheDir)

	keyFilename := cacheKeyFilename(parsed)
	ttlSeconds := getTTLSeconds(ttlNanos)

	if parsed.force {
		executeAndCache(parsed, cacheDir, ttlSeconds, keyFilename, ttlDuration)
		return
	}

	entry, err := readCacheEntry(cacheDir, keyFilename)

	if err == nil && entry != nil {
		cachedTime := time.Unix(entry.ExecTime, 0)
		age := time.Since(cachedTime)

		if age < ttlDuration {
			outputEntry(entry)

			if parsed.staleSet && age >= staleDuration {
				spawnBackgroundRefresh(parsed)
			}
			return
		}
	}

	executeAndCache(parsed, cacheDir, ttlSeconds, keyFilename, ttlDuration)
}

func executeAndCache(parsed *cliArgs, cacheDir string, ttlSeconds uint64, keyFilename string, ttlDuration time.Duration) {
	stdout, stderr, exitCode, execErr := executeCommand(parsed.command)

	if execErr != nil {
		fmt.Fprintf(os.Stderr, "%s\n", execErr.Error())
		os.Exit(exitCode)
	}

	shouldCache := true
	if parsed.discardFailures && exitCode != 0 {
		shouldCache = false
	}

	if shouldCache {
		entry := &CacheEntry{
			Stdout:   stdout,
			Stderr:   stderr,
			ExitCode: exitCode,
			ExecTime: time.Now().Unix(),
		}
		writeCacheEntry(cacheDir, ttlSeconds, keyFilename, entry)
	}

	os.Exit(exitCode)
}

func outputEntry(entry *CacheEntry) {
	if len(entry.Stdout) > 0 {
		os.Stdout.Write(entry.Stdout)
	}
	if len(entry.Stderr) > 0 {
		os.Stderr.Write(entry.Stderr)
	}
	os.Exit(entry.ExitCode)
}

func mustParseCLI() *cliArgs {
	parsed, err := parseCLI()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n\nFor more information, try '--help'.\n", err)
		os.Exit(2)
	}
	return parsed
}
