			}
			fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n", arg)
			fmt.Fprintf(os.Stderr, "  tip: to pass '%s' as a value, use '-- %s'\n\n", arg, arg)
			fmt.Fprintf(os.Stderr, "Usage: %s [OPTIONS] --ttl <DURATION> -- <COMMAND>...\n\n", binName)
			fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
			os.Exit(2)
