					formatArgForUsage(a), formatArgForUsage(foundConflicts[0]))
			} else {
				fmt.Fprintf(os.Stderr, "error: the argument '%s' cannot be used with:\n", formatArgForUsage(a))
				for _, c := range foundConflicts {
					fmt.Fprintf(os.Stderr, "  %s\n", formatArgForUsage(c))
				}
				fmt.Fprintln(os.Stderr)
			}

			// Build usage line: include all args except the conflicting ones
			conflictSet := map[string]bool{}
			for _, c := range foundConflicts {
				conflictSet[c] = true
			}
			var parts []string
			parts = append(parts, binName)
			parts = append(parts, "--ttl <DURATION>")
			for _, a2 := range argOrder {
				if a2 == "--ttl" || conflictSet[a2] {
					continue
				}
				parts = append(parts, formatArgForUsage(a2))
			}
			parts = append(parts, "--")
			parts = append(parts, "<COMMAND>...")
			fmt.Fprintf(os.Stderr, "Usage: %s\n\n", strings.Join(parts, " "))
			fmt.Fprintf(os.Stderr, "For more information, try '--help'.\n")
			os.Exit(2)
		}
	}

	// Check required args
	var missing []string
	if !parsed.ttlSet {
		missing = append(missing, "--ttl <DURATION>")
	}
	if len(parsed.command) == 0 {
		missing = append(missing, "<COMMAND>...")
	}

	if len(missing) > 0 {
		var sb strings.Builder
		sb.WriteString("error: the following required arguments were not provided:\n")
