package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

// FlagKind enumerates flag value types.
type FlagKind int

const (
	KindBool FlagKind = iota
	KindString
	KindInt
	KindStrings
)

// FlagDef describes a single flag.
type FlagDef struct {
	Short    rune
	Long     string
	Kind     FlagKind
	HasShort bool
	// Pointer to the destination variable; set during parsing.
	BoolDest   *bool
	StrDest    *string
	IntDest    *int
	StrsDest   *[]string
	IsList     bool // comma-separated list flag (KindStrings via comma)
	Deprecated string // if non-empty, using this flag errors with this message
}

func (f *FlagDef) takesValue() bool { return f.Kind != KindBool }

// FlagSet holds the flags for a command (including globals).
type FlagSet struct {
	Flags []*FlagDef
}

func (fs *FlagSet) findByLong(name string) *FlagDef {
	for _, f := range fs.Flags {
		if f.Long == name {
			return f
		}
	}
	return nil
}
func (fs *FlagSet) findByShort(c rune) *FlagDef {
	for _, f := range fs.Flags {
		if f.HasShort && f.Short == c {
			return f
		}
	}
	return nil
}

// ParseError represents a kong-style parse error.
type ParseError struct{ Msg string }

func (e *ParseError) Error() string { return e.Msg }

// ParseResult holds parsed positionals and whether help was requested.
type ParseResult struct {
	Positionals []string
	Help        bool
}

// parse parses args (excluding the program name and command) according to fs.
func (fs *FlagSet) parse(args []string) (*ParseResult, error) {
	res := &ParseResult{}
	i := 0
	for i < len(args) {
		arg := args[i]
		i++
		if arg == "--" {
			res.Positionals = append(res.Positionals, args[i:]...)
			break
		}
		if strings.HasPrefix(arg, "--") {
			body := arg[2:]
			name := body
			var inlineVal string
			hasInline := false
			if eq := strings.IndexByte(body, '='); eq >= 0 {
				name = body[:eq]
				inlineVal = body[eq+1:]
				hasInline = true
			}
			if name == "help" {
				res.Help = true
				continue
			}
			f := fs.findByLong(name)
			if f == nil {
				return nil, &ParseError{Msg: suggestUnknown(fs, "--"+name, false)}
			}
			if f.Deprecated != "" {
				return nil, &ParseError{Msg: "incorrect criteria: " + f.Deprecated}
			}
			if f.Kind == KindBool {
				if hasInline {
					b, err := parseBool(inlineVal)
					if err != nil {
						return nil, &ParseError{Msg: fmt.Sprintf("--%s: expected boolean value but got %q", f.Long, inlineVal)}
					}
					*f.BoolDest = b
				} else {
					*f.BoolDest = true
				}
				continue
			}
			// value-taking flag
			var val string
			if hasInline {
				val = inlineVal
			} else {
				if i >= len(args) {
					return nil, &ParseError{Msg: fmt.Sprintf("--%s: expected %s value but got \"EOL\" (<EOL>)", f.Long, kindWord(f.Kind))}
				}
				val = args[i]
				i++
			}
			if err := fs.assign(f, val); err != nil {
				return nil, err
			}
			continue
		}
		if len(arg) > 1 && arg[0] == '-' {
			// short flags, possibly combined
			body := arg[1:]
			for j := 0; j < len(body); j++ {
				c := rune(body[j])
				if c == 'h' {
					// only treat as help if -h is actually the help flag (it is, globally)
					f := fs.findByShort('h')
					if f != nil {
						*f.BoolDest = true
						res.Help = true
						continue
					}
				}
				f := fs.findByShort(c)
				if f == nil {
					return nil, &ParseError{Msg: suggestUnknown(fs, "-"+string(c), true)}
				}
				if f.Deprecated != "" {
					return nil, &ParseError{Msg: "incorrect criteria: " + f.Deprecated}
				}
				if f.Kind == KindBool {
					*f.BoolDest = true
					continue
				}
				// value-taking: rest of body is the value, or next arg
				rest := body[j+1:]
				var val string
				if len(rest) > 0 {
					if rest[0] == '=' {
						rest = rest[1:]
					}
					val = rest
				} else {
					if i >= len(args) {
						return nil, &ParseError{Msg: fmt.Sprintf("--%s: expected %s value but got \"EOL\" (<EOL>)", f.Long, kindWord(f.Kind))}
					}
					val = args[i]
					i++
				}
				if err := fs.assign(f, val); err != nil {
					return nil, err
				}
				break
			}
			continue
		}
		// positional
		res.Positionals = append(res.Positionals, arg)
	}
	return res, nil
}

func (fs *FlagSet) assign(f *FlagDef, val string) error {
	switch f.Kind {
	case KindString:
		*f.StrDest = val
	case KindInt:
		n, err := strconv.ParseInt(val, 10, 64)
		if err != nil {
			return &ParseError{Msg: fmt.Sprintf("--%s: expected a valid 64 bit int but got %q", f.Long, val)}
		}
		*f.IntDest = int(n)
	case KindStrings:
		if f.IsList {
			parts := splitCSV(val)
			*f.StrsDest = append(*f.StrsDest, parts...)
		} else {
			*f.StrsDest = append(*f.StrsDest, val)
		}
	}
	return nil
}

func splitCSV(s string) []string {
	// zk splits comma-separated lists, trimming spaces.
	out := []string{}
	for _, p := range strings.Split(s, ",") {
		p = strings.TrimSpace(p)
		if p != "" {
			out = append(out, p)
		}
	}
	return out
}

func parseBool(s string) (bool, error) {
	switch strings.ToLower(s) {
	case "true", "1", "yes":
		return true, nil
	case "false", "0", "no":
		return false, nil
	}
	return false, fmt.Errorf("invalid bool")
}

func kindWord(k FlagKind) string {
	switch k {
	case KindString:
		return "string"
	case KindInt:
		return "int"
	case KindStrings:
		return "string"
	}
	return "value"
}

// suggestUnknown produces a kong-style "unknown flag" message with suggestions.
func suggestUnknown(fs *FlagSet, unknown string, isShort bool) string {
	var cands []string
	for _, f := range fs.Flags {
		if isShort && f.HasShort {
			c := "-" + string(f.Short)
			if levenshtein(unknown, c, true) <= 2 {
				cands = append(cands, c)
			}
		} else if !isShort && f.Long != "" {
			c := "--" + f.Long
			if levenshtein(unknown, c, true) <= 2 {
				cands = append(cands, c)
			}
		}
	}
	// Also always include -h and -W for short? kong includes them. They're in fs.Flags already.
	if len(cands) == 0 {
		return "unknown flag " + unknown
	}
	quoted := make([]string, len(cands))
	for i, c := range cands {
		quoted[i] = fmt.Sprintf("%q", c)
	}
	return fmt.Sprintf("unknown flag %s, did you mean one of %s?", unknown, strings.Join(quoted, ", "))
}

func levenshtein(a, b string, ci bool) int {
	if ci {
		a = strings.ToLower(a)
		b = strings.ToLower(b)
	}
	la, lb := len(a), len(b)
	d := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		d[j] = j
	}
	for i := 1; i <= la; i++ {
		prev := d[0]
		d[0] = i
		for j := 1; j <= lb; j++ {
			tmp := d[j]
			cost := 1
			if a[i-1] == b[j-1] {
				cost = 0
			}
			d[j] = min3(d[j]+1, d[j-1]+1, prev+cost)
			prev = tmp
		}
	}
	return d[lb]
}

func min3(a, b, c int) int {
	if b < a {
		a = b
	}
	if c < a {
		a = c
	}
	return a
}

