package main

import (
	"fmt"
	"os"
	"strings"
)

// Globals holds the global flags shared across commands.
type Globals struct {
	Help        bool
	NotebookDir string
	WorkingDir  string
	NoInput     bool
}

var globals Globals

func globalFlags() *FlagSet {
	return &FlagSet{Flags: []*FlagDef{
		{HasShort: true, Short: 'h', Long: "help", Kind: KindBool, BoolDest: &globals.Help},
		{Long: "notebook-dir", Kind: KindString, StrDest: &globals.NotebookDir},
		{HasShort: true, Short: 'W', Long: "working-dir", Kind: KindString, StrDest: &globals.WorkingDir},
		{Long: "no-input", Kind: KindBool, BoolDest: &globals.NoInput},
	}}
}

// scanForCommand walks args consuming global flags, returning the command name
// (first positional), the remaining args after it, and whether help was set.
func scanForCommand(args []string) (cmd string, rest []string, err error) {
	g := globalFlags()
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			// rest are positionals; first is command
			rest2 := args[i+1:]
			if len(rest2) == 0 {
				return "", nil, nil
			}
			return rest2[0], rest2[1:], nil
		}
		if strings.HasPrefix(arg, "--") {
			body := arg[2:]
			name := body
			inline := false
			var val string
			if eq := strings.IndexByte(body, '='); eq >= 0 {
				name = body[:eq]
				val = body[eq+1:]
				inline = true
			}
			if name == "help" {
				globals.Help = true
				i++
				continue
			}
			f := g.findByLong(name)
			if f == nil {
				return "", nil, &ParseError{Msg: suggestUnknown(g, "--"+name, false)}
			}
			if f.Kind == KindBool {
				if inline {
					b, e := parseBool(val)
					if e != nil {
						return "", nil, &ParseError{Msg: fmt.Sprintf("--%s: expected boolean value but got %q", f.Long, val)}
					}
					*f.BoolDest = b
				} else {
					*f.BoolDest = true
				}
				i++
				continue
			}
			if !inline {
				if i+1 >= len(args) {
					return "", nil, &ParseError{Msg: fmt.Sprintf("--%s: expected %s value but got \"EOL\" (<EOL>)", f.Long, kindWord(f.Kind))}
				}
				val = args[i+1]
				i += 2
			} else {
				i++
			}
			*f.StrDest = val
			continue
		}
		if len(arg) > 1 && arg[0] == '-' {
			body := arg[1:]
			consumed, val, e := scanShortGlobals(body, args, &i)
			if e != nil {
				return "", nil, e
			}
			_ = consumed
			_ = val
			continue
		}
		// positional => command
		return arg, args[i+1:], nil
	}
	return "", nil, nil
}

// scanShortGlobals handles a cluster of short flags at the root level.
func scanShortGlobals(body string, args []string, i *int) (bool, string, error) {
	g := globalFlags()
	j := 0
	for j < len(body) {
		c := rune(body[j])
		if c == 'h' {
			globals.Help = true
			j++
			continue
		}
		f := g.findByShort(c)
		if f == nil {
			return false, "", &ParseError{Msg: suggestUnknown(g, "-"+string(c), true)}
		}
		if f.Kind == KindBool {
			*f.BoolDest = true
			j++
			continue
		}
		rest := body[j+1:]
		var val string
		if len(rest) > 0 {
			if rest[0] == '=' {
				rest = rest[1:]
			}
			val = rest
		} else {
			if *i+1 >= len(args) {
				return false, "", &ParseError{Msg: fmt.Sprintf("--%s: expected %s value but got \"EOL\" (<EOL>)", f.Long, kindWord(f.Kind))}
			}
			val = args[*i+1]
			*i++
		}
		*f.StrDest = val
		*i++
		return true, val, nil
	}
	*i++
	return false, "", nil
}

func main() {
	exitCode := run(os.Args[1:])
	os.Exit(exitCode)
}

func run(args []string) int {
	cmd, rest, err := scanForCommand(args)
	if err != nil {
		fmt.Fprintln(os.Stderr, "zk: error: "+err.Error())
		return 1
	}
	if cmd == "" {
		// No command given.
		if globals.Help {
			fmt.Print(helpRoot)
			return 0
		}
		fmt.Print(helpRoot)
		return 0
	}
	// Apply working directory.
	if globals.WorkingDir != "" {
		if e := os.Chdir(globals.WorkingDir); e != nil {
			fmt.Fprintln(os.Stderr, "zk: error: "+e.Error())
			return 1
		}
	}
	switch cmd {
	case "init":
		return cmdInitMain(rest)
	case "index":
		return cmdIndexMain(rest)
	case "new":
		return cmdNewMain(rest)
	case "list":
		return cmdListMain(rest)
	case "graph":
		return cmdGraphMain(rest)
	case "edit":
		return cmdEditMain(rest)
	case "tag":
		return cmdTagMain(rest)
	case "config":
		return cmdConfigMain(rest)
	case "lsp":
		return cmdLSPMain(rest)
	default:
		fmt.Fprintln(os.Stderr, "zk: error: unexpected argument "+cmd)
		return 1
	}
}
GOEOF
echo done"}}

