//go:embed embed/config.toml
var defaultConfig string

//go:embed embed/default.md
var defaultTemplate string

// Config holds parsed notebook configuration.
type Config struct {
	Note NoteConfig
	// raw sections for listing
	Filters  map[string]string
	Aliases  map[string]string
	Extras   map[string]string
	Groups   map[string]GroupConfig
	Markdown MarkdownConfig
	Tool     ToolConfig
	LSP      LSPConfig
}

type NoteConfig struct {
	Language     string
	DefaultTitle string
	Filename     string
	Extension    string
	Template     string
	Exclude      []string
	IDCharset    string
	IDLength     int
	IDCase       string
}

type GroupConfig struct {
	Paths []string
	Note  *NoteConfig
	Extra map[string]string
}

type MarkdownConfig struct {
	LinkFormat      string
	LinkEncodePath  *bool // nil = default
	LinkDropExt     *bool
	Hashtags        *bool
	ColonTags       *bool
	MultiwordTags   *bool
}

type ToolConfig struct {
	Editor     string
	Pager      *string
	FzfPreview string
}

type LSPConfig struct {
	Diagnostics map[string]interface{}
	Completion  map[string]interface{}
}

func defaultConfigStruct() *Config {
	c := &Config{
		Filters: map[string]string{},
		Aliases: map[string]string{},
		Extras:  map[string]string{},
		Groups:  map[string]GroupConfig{},
	}
	c.Note = NoteConfig{
		Language:     "en",
		DefaultTitle: "Untitled",
		Filename:     "{{id}}",
		Extension:    "md",
		Template:     "default.md",
		IDCharset:    "alphanum",
		IDLength:     4,
		IDCase:       "lower",
	}
	t := true
	f := false
	c.Markdown = MarkdownConfig{
		LinkFormat:    "markdown",
		LinkDropExt:   &t,
		Hashtags:      &t,
		ColonTags:     &f,
		MultiwordTags: &f,
	}
	return c
}

// LoadConfig loads the notebook config from .zk/config.toml, applying user
// overrides on top of defaults.
func LoadConfig(notebookDir string) (*Config, error) {
	c := defaultConfigStruct()
	path := filepath.Join(notebookDir, ".zk", "config.toml")
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return c, nil
		}
		return nil, err
	}
	parseTOML(string(data), c)
	// apply markdown link-format defaults
	applyMarkdownDefaults(c)
	return c, nil
}

func applyMarkdownDefaults(c *Config) {
	if c.Markdown.LinkFormat == "" {
		c.Markdown.LinkFormat = "markdown"
	}
	if c.Markdown.LinkEncodePath == nil {
		v := c.Markdown.LinkFormat == "markdown"
		c.Markdown.LinkEncodePath = &v
	}
	if c.Markdown.LinkDropExt == nil {
		t := true
		c.Markdown.LinkDropExt = &t
	}
	if c.Markdown.Hashtags == nil {
		t := true
		c.Markdown.Hashtags = &t
	}
	if c.Markdown.ColonTags == nil {
		f := false
		c.Markdown.ColonTags = &f
	}
	if c.Markdown.MultiwordTags == nil {
		f := false
		c.Markdown.MultiwordTags = &f
	}
}

// parseTOML is a minimal TOML parser sufficient for zk configs.
func parseTOML(s string, c *Config) {
	var section []string
	var curGroup *GroupConfig
	lines := strings.Split(s, "\n")
	for _, line := range lines {
		l := strings.TrimSpace(line)
		if l == "" || strings.HasPrefix(l, "#") {
			continue
		}
		if strings.HasPrefix(l, "[") {
			// section header
			sec := strings.TrimSpace(strings.TrimSuffix(strings.TrimPrefix(l, "["), "]"))
			parts := splitSection(sec)
			section = parts
			curGroup = nil
			if len(parts) >= 1 && parts[0] == "group" {
				name := ""
				if len(parts) >= 2 {
					name = unquote(parts[1])
				}
				g := GroupConfig{Extra: map[string]string{}}
				c.Groups[name] = g
				// keep a reference to mutate
				g2 := c.Groups[name]
				curGroup = &g2
				// store back after each mutation handled below via reassignment
				c.Groups[name] = *curGroup
				curGroup = groupPtr(c, name)
			}
			continue
		}
		// key = value
		eq := strings.IndexByte(l, '=')
		if eq < 0 {
			continue
		}
		key := strings.TrimSpace(l[:eq])
		val := strings.TrimSpace(l[eq+1:])
		key = unquote(key)
		// strip trailing comment (naive: only if # not in quotes)
		val = stripComment(val)
		assignKV(c, section, key, val, curGroup)
	}
}

func groupPtr(c *Config, name string) *GroupConfig {
	g, ok := c.Groups[name]
	if !ok {
		g = GroupConfig{Extra: map[string]string{}}
	}
	c.Groups[name] = g
	g2 := c.Groups[name]
	return &g2
}

func splitSection(sec string) []string {
	var parts []string
	// split on . but respect quotes
	inq := false
	cur := ""
	for i := 0; i < len(sec); i++ {
		ch := sec[i]
		if ch == '"' {
			inq = !inq
			cur += string(ch)
		} else if ch == '.' && !inq {
			parts = append(parts, cur)
			cur = ""
		} else {
			cur += string(ch)
		}
	}
	if cur != "" {
		parts = append(parts, cur)
	}
	for i := range parts {
		parts[i] = strings.TrimSpace(parts[i])
	}
	return parts
}

func stripComment(v string) string {
	inq := false
	for i := 0; i < len(v); i++ {
		if v[i] == '"' {
			inq = !inq
		} else if v[i] == '#' && !inq {
			return strings.TrimSpace(v[:i])
		}
	}
	return v
}

func unquote(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 && (s[0] == '"' || s[0] == '\'') {
		if s[len(s)-1] == s[0] {
			return s[1 : len(s)-1]
		}
	}
	return s
}

func parseBoolVal(v string) (bool, bool) {
	switch strings.ToLower(v) {
	case "true":
		return true, true
	case "false":
		return false, true
	}
	return false, false
}

func parseStringList(v string) []string {
	v = strings.TrimSpace(v)
	v = strings.TrimPrefix(v, "[")
	v = strings.TrimSuffix(v, "]")
	var out []string
	cur := ""
	inq := false
	for i := 0; i < len(v); i++ {
		ch := v[i]
		if ch == '"' {
			inq = !inq
		} else if ch == ',' && !inq {
			p := strings.TrimSpace(cur)
			if p != "" {
				out = append(out, unquote(p))
			}
			cur = ""
		} else {
			cur += string(ch)
		}
	}
	if strings.TrimSpace(cur) != "" {
		out = append(out, unquote(strings.TrimSpace(cur)))
	}
	return out
}

func assignKV(c *Config, section []string, key, val string, curGroup *GroupConfig) {
	if len(section) == 0 {
		return
	}
	top := section[0]
	switch top {
	case "note":
		assignNote(&c.Note, key, val)
	case "extra":
		c.Extras[key] = unquote(val)
	case "filter":
		c.Filters[key] = unquote(val)
	case "alias":
		c.Aliases[key] = unquote(val)
	case "tool":
		switch key {
		case "editor":
			c.Tool.Editor = unquote(val)
		case "pager":
			p := unquote(val)
			c.Tool.Pager = &p
		case "fzf-preview":
			c.Tool.FzfPreview = unquote(val)
		}
	case "format":
		if len(section) >= 2 && section[1] == "markdown" {
			assignMarkdown(&c.Markdown, key, val)
		}
	case "lsp":
		// not needed for CLI behavior
	case "group":
		if len(section) >= 2 {
			name := unquote(section[1])
			g := groupPtr(c, name)
			if len(section) >= 3 && section[2] == "note" {
				if g.Note == nil {
					nc := c.Note
					g.Note = &nc
				}
				assignNote(g.Note, key, val)
			} else if len(section) >= 3 && section[2] == "extra" {
				g.Extra[key] = unquote(val)
			} else if key == "paths" {
				g.Paths = parseStringList(val)
			}
			c.Groups[name] = *g
		}
	}
}

func assignNote(n *NoteConfig, key, val string) {
	switch key {
	case "language":
		n.Language = unquote(val)
	case "default-title":
		n.DefaultTitle = unquote(val)
	case "filename":
		n.Filename = unquote(val)
	case "extension":
		n.Extension = unquote(val)
	case "template":
		n.Template = unquote(val)
	case "exclude":
		n.Exclude = parseStringList(val)
	case "id-charset":
		n.IDCharset = unquote(val)
	case "id-length":
		if l, ok := atoi(val); ok {
			n.IDLength = l
		}
	case "id-case":
		n.IDCase = unquote(val)
	}
}

func assignMarkdown(m *MarkdownConfig, key, val string) {
	switch key {
	case "link-format":
		m.LinkFormat = unquote(val)
	case "link-encode-path":
		if b, ok := parseBoolVal(val); ok {
			m.LinkEncodePath = &b
		}
	case "link-drop-extension":
		if b, ok := parseBoolVal(val); ok {
			m.LinkDropExt = &b
		}
	case "hashtags":
		if b, ok := parseBoolVal(val); ok {
			m.Hashtags = &b
		}
	case "colon-tags":
		if b, ok := parseBoolVal(val); ok {
			m.ColonTags = &b
		}
	case "multiword-tags":
		if b, ok := parseBoolVal(val); ok {
			m.MultiwordTags = &b
		}
	}
}

func atoi(s string) (int, bool) {
	s = strings.TrimSpace(s)
	n := 0
	for _, ch := range s {
		if ch < '0' || ch > '9' {
			return 0, false
		}
		n = n*10 + int(ch-'0')
	}
	return n, true
}
