package main

import (
	"fmt"
	"os"
	"path/filepath"
)

// Notebook represents a discovered notebook.
type Notebook struct {
	Dir    string // notebook root directory
	Config *Config
}

// findNotebook discovers the notebook directory. If notebookDir is set, use it.
// Otherwise walk up from cwd looking for a .zk directory.
func findNotebook(notebookDir string) (*Notebook, error) {
	dir := notebookDir
	if dir == "" {
		cwd, err := os.Getwd()
		if err != nil {
			return nil, err
		}
		cur := cwd
		for {
			if _, err := os.Stat(filepath.Join(cur, ".zk")); err == nil {
				dir = cur
				break
			}
			parent := filepath.Dir(cur)
			if parent == cur {
				return nil, fmt.Errorf("notebook not found in a parent directory")
			}
			cur = parent
		}
	}
	abs, err := filepath.Abs(dir)
	if err != nil {
		abs = dir
	}
	cfg, err := LoadConfig(abs)
	if err != nil {
		return nil, err
	}
	return &Notebook{Dir: abs, Config: cfg}, nil
}

// Init creates a new notebook in dir.
func Init(dir string) error {
	if dir == "" {
		dir = "."
	}
	zkDir := filepath.Join(dir, ".zk")
	if err := os.MkdirAll(zkDir, 0755); err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Join(zkDir, "templates"), 0755); err != nil {
		return err
	}
	// config.toml
	cfgPath := filepath.Join(zkDir, "config.toml")
	if _, err := os.Stat(cfgPath); os.IsNotExist(err) {
		if err := os.WriteFile(cfgPath, []byte(defaultConfig), 0644); err != nil {
			return err
		}
	}
	// default template
	tplPath := filepath.Join(zkDir, "templates", "default.md")
	if _, err := os.Stat(tplPath); os.IsNotExist(err) {
		if err := os.WriteFile(tplPath, []byte(defaultTemplate), 0644); err != nil {
			return err
		}
	}
	// notebook.db placeholder
	dbPath := filepath.Join(zkDir, "notebook.db")
	if _, err := os.Stat(dbPath); os.IsNotExist(err) {
		if err := os.WriteFile(dbPath, []byte(emptyDB), 0644); err != nil {
			return err
		}
	}
	return nil
}

// emptyDB is a minimal placeholder for the SQLite database file. We do not use
// a real SQLite engine; this just ensures the file exists like the original.
var emptyDB = make([]byte, 0)
