package main

import (
	"regexp"
	"strconv"
	"strings"
)

// Minimal YAML parser for frontmatter, approximating go-yaml v2 (YAML 1.1)
// scalar resolution for the common cases.

func parseYAML(s string) map[string]interface{} {
	lines := strings.Split(s, "\n")
	p := &yamlParser{lines: lines}
	res := p.parseMap(0)
	if res == nil {
		return map[string]interface{}{}
	}
	m, ok := res.(map[string]interface{})
	if !ok {
		return map[string]interface{}{}
	}
	return m
}

type yamlParser struct {
	lines []string
	i     int
}

func (p *yamlParser) peek() (string, bool) {
	if p.i >= len(p.lines) {
		return "", false
	}
	return p.lines[p.i], true
}

func indentOf(s string) int {
	n := 0
	for n < len(s) && s[n] == ' ' {
		n++
	}
	return n
}

// parseMap parses a mapping at the given minimum indent.
func (p *yamlParser) parseMap(minIndent int) interface{} {
	m := map[string]interface{}{}
	for {
		line, ok := p.peek()
		if !ok {
			break
		}
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			p.i++
			continue
		}
		ind := indentOf(line)
		if ind < minIndent {
			break
		}
		if trimmed == "---" || strings.HasPrefix(trimmed, "#") {
			p.i++
			continue
		}
		// expect key: value
		colon := findColon(trimmed)
		if colon < 0 {
			// not a mapping line; stop
			break
		}
		key := strings.TrimSpace(trimmed[:colon])
		key = unquoteYAML(key)
		rest := strings.TrimSpace(trimmed[colon+1:])
		p.i++
		if rest == "" {
			// nested block: could be map or list
			child := p.parseChild(ind + 1)
			m[key] = child
		} else {
			m[key] = resolveScalarOrInline(rest)
		}
	}
	return m
}

func (p *yamlParser) parseChild(minIndent int) interface{} {
	// look ahead for first non-empty line
	for {
		line, ok := p.peek()
		if !ok {
			return nil
		}
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			p.i++
			continue
		}
		ind := indentOf(line)
		if ind < minIndent {
			return nil
		}
		if strings.HasPrefix(trimmed, "- ") || trimmed == "-" {
			return p.parseList(ind)
		}
		return p.parseMap(ind)
	}
}

func (p *yamlParser) parseList(minIndent int) []interface{} {
	var out []interface{}
	for {
		line, ok := p.peek()
		if !ok {
			break
		}
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			p.i++
			continue
		}
		ind := indentOf(line)
		if ind < minIndent {
			break
		}
		if !(strings.HasPrefix(trimmed, "- ") || trimmed == "-") {
			break
		}
		val := strings.TrimSpace(strings.TrimPrefix(trimmed, "-"))
		p.i++
		if val == "" {
			child := p.parseChild(ind + 1)
			out = append(out, child)
		} else {
			out = append(out, resolveScalarOrInline(val))
		}
	}
	return out
}

func findColon(s string) int {
	inq := false
	var qch byte
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if inq {
			if ch == qch {
				inq = false
			}
			continue
		}
		if ch == '"' || ch == '\'' {
			inq = true
			qch = ch
			continue
		}
		if ch == ':' {
			// colon followed by space or end => separator
			if i+1 >= len(s) || s[i+1] == ' ' {
				return i
			}
		}
	}
	return -1
}

func resolveScalarOrInline(s string) interface{} {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil
	}
	// inline list
	if strings.HasPrefix(s, "[") && strings.HasSuffix(s, "]") {
		inner := strings.TrimSpace(s[1 : len(s)-1])
		var out []interface{}
		if inner != "" {
			for _, p := range splitTopLevel(inner, ',') {
				out = append(out, resolveScalarOrInline(strings.TrimSpace(p)))
			}
		}
		return out
	}
	// inline map
	if strings.HasPrefix(s, "{") && strings.HasSuffix(s, "}") {
		inner := strings.TrimSpace(s[1 : len(s)-1])
		m := map[string]interface{}{}
		if inner != "" {
			for _, p := range splitTopLevel(inner, ',') {
				c := findColon(p)
				if c >= 0 {
					k := unquoteYAML(strings.TrimSpace(p[:c]))
					m[k] = resolveScalarOrInline(strings.TrimSpace(p[c+1:]))
				}
			}
		}
		return m
	}
	// quoted string
	if len(s) >= 2 && (s[0] == '"' || s[0] == '\'') && s[len(s)-1] == s[0] {
		return unquoteYAML(s)
	}
	return resolveScalar(s)
}

func splitTopLevel(s string, sep byte) []string {
	var out []string
	inq := false
	var qch byte
	depth := 0
	cur := ""
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if inq {
			cur += string(ch)
			if ch == qch {
				inq = false
			}
			continue
		}
		if ch == '"' || ch == '\'' {
			inq = true
			qch = ch
			cur += string(ch)
			continue
		}
		if ch == '[' || ch == '{' {
			depth++
			cur += string(ch)
			continue
		}
		if ch == ']' || ch == '}' {
			depth--
			cur += string(ch)
			continue
		}
		if ch == sep && depth == 0 {
			out = append(out, cur)
			cur = ""
			continue
		}
		cur += string(ch)
	}
	out = append(out, cur)
	return out
}

func unquoteYAML(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		inner := s[1 : len(s)-1]
		// double-quoted: process escapes
		return unescapeDoubleQuoted(inner)
	}
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		inner := s[1 : len(s)-1]
		return strings.ReplaceAll(inner, "''", "'")
	}
	return s
}

func unescapeDoubleQuoted(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			i++
			continue
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

var (
	reYAMLInt   = regexp.MustCompile(`^[-+]?[0-9]+$`)
	reYAMLOct   = regexp.MustCompile(`^0o[0-7]+$`)
	reYAMLHex   = regexp.MustCompile(`^0x[0-9a-fA-F]+$`)
	reYAMLFloat = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][-+]?[0-9]+)?$`)
)

func resolveScalar(s string) interface{} {
	switch s {
	case "", "~", "null", "Null", "NULL":
		return nil
	case "true", "True", "TRUE", "yes", "Yes", "YES", "on", "On", "ON", "y", "Y":
		return true
	case "false", "False", "FALSE", "no", "No", "NO", "off", "Off", "OFF", "n", "N":
		return false
	}
	if reYAMLInt.MatchString(s) {
		if n, err := strconv.ParseInt(s, 10, 64); err == nil {
			return n
		}
	}
	if reYAMLOct.MatchString(s) {
		if n, err := strconv.ParseInt(s[2:], 8, 64); err == nil {
			return n
		}
	}
	if reYAMLHex.MatchString(s) {
		if n, err := strconv.ParseInt(s[2:], 16, 64); err == nil {
			return n
		}
	}
	if reYAMLFloat.MatchString(s) {
		if f, err := strconv.ParseFloat(s, 64); err == nil {
			return f
		}
	}
	return s
}
GOEOF
echo done"}}

{"name": "bash", "arguments": {"command": "cd /workspace/src && cat > note.go <<'GOEOF'
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"regexp"
	"strings"
	"unicode"
)

// Note holds parsed note data.
type Note struct {
	Path       string // relative to notebook dir
	Filename   string
	Stem       string
	Title      string
	Lead       string
	Body       string
	RawContent string
	WordCount  int
	Tags       []string
	Metadata   map[string]interface{}
	Checksum   string
	Created    string // ISO
	Modified   string // ISO
	ModTime    int64  // unix seconds (file mtime)
	ModNano    int    // nanoseconds
	ID         int    // db id
	// links
	Links []ParsedLink
}

// ParsedLink represents a link found in a note.
type ParsedLink struct {
	Title        string
	Href         string
	Type         string // "wiki-link", "markdown-link"
	External     bool
	Rels         []string
	Snippet      string
	SnippetStart int
	SnippetEnd   int
	// resolution
	TargetPath string
	TargetID   int
}

var (
	reATXH1    = regexp.MustCompile(`^ {0,3}#\s+(.+?)\s*$`)
	reSetextUL = regexp.MustCompile(`^ {0,3}=+\s*$`)
)

// ParseNote parses raw content into a Note (without path/db fields).
func ParseNote(raw string, md MarkdownConfig) (title, body, lead string, tags []string, metadata map[string]interface{}, links []ParsedLink) {
	content, metadata := splitFrontmatter(raw)
	// Determine title.
	hasFmTitle := false
	if metadata != nil {
		if t, ok := metadata["title"]; ok {
			if ts, ok := t.(string); ok && ts != "" {
				title = ts
				hasFmTitle = true
			}
		}
	}
	if !hasFmTitle {
		// find first heading
		if h, pos, isSetext := findFirstHeading(content); h != "" {
			title = h
			// body = content after the heading line(s)
			if isSetext {
				// setext: title is one line, underline next; body starts at underline
				// find start of title line
				body = content[pos:]
			} else {
				// ATX: body = content after the heading line + skip one blank line
				after := content[pos:]
				body = skipOneBlankLine(after)
			}
		} else {
			body = content
		}
	} else {
		body = content
	}
	body = strings.TrimSpace(body)
	lead = firstParagraph(body)
	tags = extractTags(content, md)
	links = extractLinks(content, md)
	return
}

func splitFrontmatter(raw string) (content string, metadata map[string]interface{}) {
	// frontmatter must start with --- on first line
	nl := strings.IndexByte(raw, '\n')
	var firstLine string
	if nl < 0 {
		firstLine = raw
	} else {
		firstLine = raw[:nl]
	}
	if strings.TrimSpace(firstLine) != "---" {
		return raw, nil
	}
	// find closing ---
	rest := raw
	if nl >= 0 {
		rest = raw[nl+1:]
	} else {
		rest = ""
	}
	lines := strings.Split(rest, "\n")
	closeIdx := -1
	for i, l := range lines {
		if strings.TrimSpace(l) == "---" {
			closeIdx = i
			break
		}
	}
	if closeIdx < 0 {
		return raw, nil
	}
	fm := strings.Join(lines[:closeIdx], "\n")
	body := strings.Join(lines[closeIdx+1:], "\n")
	metadata = parseYAML(fm)
	// normalize keys to lower case
	metadata = lowerKeys(metadata)
	content = body
	// drop exactly one leading newline
	content = strings.TrimPrefix(content, "\n")
	return content, metadata
}

func lowerKeys(m map[string]interface{}) map[string]interface{} {
	out := map[string]interface{}{}
	for k, v := range m {
		out[strings.ToLower(k)] = v
		if mm, ok := v.(map[string]interface{}); ok {
			out[strings.ToLower(k)] = lowerKeys(mm)
		}
	}
	return out
}

// findFirstHeading returns the heading title, the byte position where the body
// should start, and whether it was a setext heading.
func findFirstHeading(content string) (title string, pos int, isSetext bool) {
	lines := strings.Split(content, "\n")
	off := 0
	for i, line := range lines {
		if m := reATXH1.FindStringSubmatch(line); m != nil {
			return m[1], off + len(line) + 1, false
		}
		if i+1 < len(lines) && reSetextUL.MatchString(lines[i+1]) {
			t := strings.TrimSpace(strings.TrimLeft(line, " "))
			if t != "" {
				// body starts at the title line position (underline kept)
				return t, off, true
			}
		}
		off += len(line) + 1
	}
	return "", 0, false
}

func skipOneBlankLine(s string) string {
	// s starts right after the heading line. Skip a single leading blank line.
	if strings.HasPrefix(s, "\r\n") {
		s = s[2:]
	} else if strings.HasPrefix(s, "\n") {
		s = s[1:]
	}
	return s
}

func firstParagraph(body string) string {
	lines := strings.Split(body, "\n")
	var para []string
	for _, l := range lines {
		if strings.TrimSpace(l) == "" {
			if len(para) > 0 {
				break
			}
			continue
		}
		para = append(para, l)
	}
	return strings.TrimSpace(strings.Join(para, "\n"))
}

var reHashtag = regexp.MustCompile(`#(\p{L}[\p{L}\p{N}_-]*)`)

func extractTags(content string, md MarkdownConfig) map[string]bool {
	// returns set; converted to slice later in ordering
	_ = content
	return nil
}

// extractTagsList returns ordered unique tags.
func extractTagsList(content string, md MarkdownConfig, metadata map[string]interface{}) []string {
	seen := map[string]bool{}
	var out []string
	add := func(t string) {
		t = strings.ToLower(t)
		if !seen[t] {
			seen[t] = true
			out = append(out, t)
		}
	}
	// frontmatter tags
	if metadata != nil {
		if t, ok := metadata["tags"]; ok {
			switch v := t.(type) {
			case []interface{}:
				for _, x := range v {
					if s, ok := x.(string); ok {
						add(s)
					}
				}
			case string:
				for _, x := range strings.Split(v, ",") {
					add(strings.TrimSpace(x))
				}
			}
		}
	}
	// hashtags
	if md.Hashtags != nil && *md.Hashtags {
		for _, m := range reHashtag.FindAllStringSubmatch(content, -1) {
			add(m[1])
		}
	}
	// colon tags
	if md.ColonTags != nil && *md.ColonTags {
		for _, m := range regexp.MustCompile(`:(\p{L}[\p{L}\p{N}_-]*):`).FindAllStringSubmatch(content, -1) {
			add(m[1])
		}
	}
	// multiword tags
	if md.MultiwordTags != nil && *md.MultiwordTags {
		for _, m := range regexp.MustCompile(`#([^#]+)#`).FindAllStringSubmatch(content, -1) {
			add(strings.TrimSpace(m[1]))
		}
	}
	return out
}

// re-implement extractTags to also be used by ParseNote signature above.
func init() {}

var reWikiLink = regexp.MustCompile(`\[\[([^\]]+)\]\]`)
var reMDLink = regexp.MustCompile(`\[([^\]]*)\]\(([^)]+)\)`)

func extractLinks(content string, md MarkdownConfig) []ParsedLink {
	var links []ParsedLink
	// wiki links
	for _, m := range reWikiLink.FindAllStringSubmatchIndex(content, -1) {
		inner := content[m[2]:m[3]]
		href := inner
		title := inner
		if idx := strings.IndexByte(inner, '|'); idx >= 0 {
			href = inner[:idx]
			title = inner[idx+1:]
		}
		sn, s, e := snippetAround(content, m[0], m[1])
		links = append(links, ParsedLink{
			Title: title, Href: href, Type: "wiki-link",
			Snippet: sn, SnippetStart: s, SnippetEnd: e,
		})
	}
	// markdown links
	for _, m := range reMDLink.FindAllStringSubmatchIndex(content, -1) {
		text := content[m[2]:m[3]]
		dest := content[m[4]:m[5]]
		title := text
		href := dest
		// parse title <dest> or dest "title"
		external := isExternalURL(dest)
		sn, s, e := snippetAround(content, m[0], m[1])
		links = append(links, ParsedLink{
			Title: title, Href: href, Type: "markdown-link",
			External: external, Snippet: sn, SnippetStart: s, SnippetEnd: e,
		})
	}
	return links
}

func isExternalURL(s string) bool {
	if strings.HasPrefix(s, "http://") || strings.HasPrefix(s, "https://") {
		return true
	}
	if strings.HasPrefix(s, "mailto:") || strings.HasPrefix(s, "ftp://") {
		return true
	}
	if strings.Contains(s, "://") {
		return true
	}
	if strings.HasPrefix(s, "/") {
		return true
	}
	return false
}

// snippetAround returns the line containing the match, and start/end byte offsets.
func snippetAround(content string, matchStart, matchEnd int) (snippet string, start, end int) {
	lineStart := matchStart
	for lineStart > 0 && content[lineStart-1] != '\n' {
		lineStart--
	}
	lineEnd := matchEnd
	for lineEnd < len(content) && content[lineEnd] != '\n' {
		lineEnd++
	}
	snippet = strings.TrimSpace(content[lineStart:lineEnd])
	return snippet, lineStart, lineEnd
}

func computeChecksum(raw string) string {
	h := sha256.Sum256([]byte(raw))
	return hex.EncodeToString(h[:])
}

func countWords(raw string) int {
	return len(strings.Fields(raw))
}

// for unicode tag regex compatibility
var _ = unicode.IsLetter
GOEOF
echo done"}}

