package main

import (
	"encoding/gob"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

type cacheEntry struct {
	Checksum string
	Created  string
	Modified string
	ID       int
}

type cacheFile struct {
	Entries map[string]cacheEntry
	NextID  int
}

// Index represents the indexed notebook state.
type Index struct {
	nb      *Notebook
	notes   []*Note
	byPath  map[string]*Note
	added   int
	modified int
	removed int
}

func dbPath(nb *Notebook) string {
	return filepath.Join(nb.Dir, ".zk", "notebook.db")
}

func loadCache(nb *Notebook) *cacheFile {
	cf := &cacheFile{Entries: map[string]cacheEntry{}, NextID: 1}
	f, err := os.Open(dbPath(nb))
	if err != nil {
		return cf
	}
	defer f.Close()
	dec := gob.NewDecoder(f)
	var c cacheFile
	if err := dec.Decode(&c); err == nil && c.Entries != nil {
		return &c
	}
	return cf
}

func saveCache(nb *Notebook, cf *cacheFile) {
	os.MkdirAll(filepath.Join(nb.Dir, ".zk"), 0755)
	f, err := os.Create(dbPath(nb))
	if err != nil {
		return
	}
	defer f.Close()
	enc := gob.NewEncoder(f)
	enc.Encode(cf)
}

// IndexNotebook scans the notebook directory, updates the cache, and returns
// the indexed notes.
func IndexNotebook(nb *Notebook, force bool) *Index {
	idx := &Index{nb: nb, byPath: map[string]*Note{}}
	cf := loadCache(nb)
	now := time.Now().UTC()
	nowStr := now.Format(time.RFC3339Nano)
	// discover files
	type fileEntry struct {
		rel  string
		info os.FileInfo
	}
	var files []fileEntry
	excludes := nb.Config.Note.Exclude
	walkErr := filepath.Walk(nb.Dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			base := filepath.Base(path)
			if path != nb.Dir && (base == ".zk" || base == ".git") {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".md") {
			return nil
		}
		rel, _ := filepath.Rel(nb.Dir, path)
		rel = filepath.ToSlash(rel)
		if excluded(rel, excludes) {
			return nil
		}
		files = append(files, fileEntry{rel: rel, info: info})
		return nil
	})
	_ = walkErr
	sort.Slice(files, func(i, j int) bool { return files[i].rel < files[j].rel })

	seen := map[string]bool{}
	for _, fe := range files {
		seen[fe.rel] = true
		abs := filepath.Join(nb.Dir, fe.rel)
		raw, err := os.ReadFile(abs)
		if err != nil {
			continue
		}
		rawStr := string(raw)
		checksum := computeChecksum(rawStr)
		ce, ok := cf.Entries[fe.rel]
		var created, modified string
		var id int
		changed := false
		if !ok {
			created = nowStr
			mt := fe.info.ModTime().UTC()
			modified = mt.Format(time.RFC3339Nano)
			id = cf.NextID
			cf.NextID++
			changed = true
			idx.added++
		} else if force || ce.Checksum != checksum {
			created = ce.Created
			mt := fe.info.ModTime().UTC()
			modified = mt.Format(time.RFC3339Nano)
			id = ce.ID
			changed = true
			if ce.Checksum != checksum {
				idx.modified++
			} else if force {
				idx.modified++
			}
		} else {
			created = ce.Created
			modified = ce.Modified
			id = ce.ID
		}
		cf.Entries[fe.rel] = cacheEntry{Checksum: checksum, Created: created, Modified: modified, ID: id}
		n := buildNote(nb, fe.rel, rawStr, checksum, created, modified, id, fe.info)
		idx.notes = append(idx.notes, n)
		idx.byPath[fe.rel] = n
	}
	// removals
	for path, ce := range cf.Entries {
		if !seen[path] {
			delete(cf.Entries, path)
			idx.removed++
			_ = ce
		}
	}
	saveCache(nb, cf)
	// resolve links
	idx.resolveLinks()
	return idx
}

func excluded(rel string, patterns []string) bool {
	for _, p := range patterns {
		if matchGlob(p, rel) {
			return true
		}
	}
	return false
}

func matchGlob(pattern, name string) bool {
	m, _ := filepath.Match(pattern, name)
	if m {
		return true
	}
	// also match as directory prefix
	if strings.HasSuffix(pattern, "/*") {
		prefix := strings.TrimSuffix(pattern, "/*")
		if strings.HasPrefix(name, prefix+"/") {
			return true
		}
	} else if !strings.Contains(pattern, "/") {
		// pattern matches any path component? zk matches on filename too
		if filepath.Base(name) == pattern {
			return true
		}
	}
	return false
}

func buildNote(nb *Notebook, rel, raw, checksum, created, modified string, id int, info os.FileInfo) *Note {
	title, body, lead, tags, metadata, links := ParseNoteFull(raw, nb.Config.Markdown)
	filename := filepath.Base(rel)
	stem := strings.TrimSuffix(filename, filepath.Ext(filename))
	n := &Note{
		Path:       rel,
		Filename:   filename,
		Stem:       stem,
		Title:      title,
		Lead:       lead,
		Body:       body,
		RawContent:  raw,
		WordCount:  countWords(raw),
		Tags:       tags,
		Metadata:   metadata,
		Checksum:   checksum,
		Created:    created,
		Modified:   modified,
		ID:         id,
		Links:      links,
	}
	return n
}

func (idx *Index) resolveLinks() {
	// build lookup by stem and by path for wiki-link resolution
	byStem := map[string]*Note{}
	byPath := map[string]*Note{}
	for _, n := range idx.notes {
		byStem[n.Stem] = n
		byPath[n.Path] = n
	}
	for _, n := range idx.notes {
		for i := range n.Links {
			l := &n.Links[i]
			if l.External {
				continue
			}
			if t, ok := byStem[l.Href]; ok {
				l.TargetPath = t.Path
				l.TargetID = t.ID
				continue
			}
			if t, ok := byPath[l.Href]; ok {
				l.TargetPath = t.Path
				l.TargetID = t.ID
				continue
			}
			// try as path prefix
			for _, c := range idx.notes {
				if strings.HasPrefix(c.Stem, l.Href) || strings.HasPrefix(c.Path, l.Href) {
					l.TargetPath = c.Path
					l.TargetID = c.ID
					break
				}
			}
		}
	}
}

// ensureIndex indexes the notebook if needed (auto-index).
func ensureIndex(nb *Notebook) *Index {
	return IndexNotebook(nb, false)
}
