// A minimal Handlebars-like template engine.

type tmplNode interface{}
type tmplText string
type tmplVar struct {
	path string
	raw  string // original {{...}} for fallback
}
type tmplHelper struct {
	name string
	args []string // raw arg expressions (paths or quoted strings)
	body []tmplNode
	hash map[string]string
