// parseTemplate tokenizes a handlebars template into nodes.
func parseTemplate(tpl string) ([]tmplNode, error) {
	var nodes []tmplNode
	i := 0
	for i < len(tpl) {
		if i+1 < len(tpl) && tpl[i] == '{' && tpl[i+1] == '{' {
			// find closing }}
			end := indexClose(tpl, i+2)
			if end < 0 {
				nodes = append(nodes, tmplText(tpl[i:]))
				break
			}
			inner := tpl[i+2 : end]
			node := parseTag(inner)
			nodes = append(nodes, node)
			i = end + 2
		} else {
			// accumulate text until next {{
			start := i
			for i < len(tpl) {
				if i+1 < len(tpl) && tpl[i] == '{' && tpl[i+1] == '{' {
					break
				}
				i++
			}
			nodes = append(nodes, tmplText(tpl[start:i]))
		}
	}
	return nodes, nil
}

func indexClose(s string, from int) int {
	for i := from; i+1 < len(s); i++ {
		if s[i] == '}' && s[i+1] == '}' {
			return i
		}
	}
	return -1
}

func parseTag(inner string) tmplNode {
	inner = strings.TrimSpace(inner)
	if strings.HasPrefix(inner, "#") {
		// block helper
		return parseBlockHelper(inner[1:])
	}
	if strings.HasPrefix(inner, "/") {
		// close marker - shouldn't reach here at top level
		return tmplText("")
	}
	if strings.HasPrefix(inner, "else") && (inner == "else" || strings.HasPrefix(inner, "else ")) {
		return tmplText("")
	}
	// variable or helper call
	if isHelperCall(inner) {
		return parseHelper(inner, nil, nil)
	}
	return tmplVar{path: inner, raw: "{{" + inner + "}}"}
}

func isHelperCall(inner string) bool {
	// has a space and first token is an identifier followed by space
	idx := strings.IndexByte(inner, ' ')
	if idx <= 0 {
		return false
	}
	name := inner[:idx]
	for _, ch := range name {
		if !(ch == '_' || ch == '-' || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) {
			return false
		}
	}
	return true
}

func parseBlockHelper(rest string) tmplNode {
	// e.g. if x  /  each items  /  prepend "> "  /  style "red"  /  sh "cmd"
	return parseHelper(rest, nil, nil)
}

func parseHelper(inner string, body, inv []tmplNode) tmplHelper {
	// split name and args, respecting quotes
	parts := splitArgs(inner)
	if len(parts) == 0 {
		return tmplHelper{}
	}
	h := tmplHelper{name: parts[0], args: parts[1:], body: body, inverse: inv, raw: "{{" + inner + "}}"}
	return h
}

func splitArgs(s string) []string {
	var out []string
	cur := ""
	inq := false
	var qch byte
	depth := 0
	for i := 0; i < len(s); i++ {
		ch := s[i]
		if inq {
			cur += string(ch)
			if ch == qch {
				inq = false
			}
			continue
		}
		if ch == '"' || ch == '\'' {
			inq = true
			qch = ch
			cur += string(ch)
			continue
		}
		if ch == '(' {
			depth++
			cur += string(ch)
			continue
		}
		if ch == ')' {
			depth--
			cur += string(ch)
			continue
		}
		if (ch == ' ' || ch == '\t') && depth == 0 {
			if cur != "" {
				out = append(out, cur)
				cur = ""
			}
			continue
		}
		cur += string(ch)
	}
	if cur != "" {
		out = append(out, cur)
	}
	return out
}

