		return a[1 : len(a)-1]
	}
	// subexpression (helper call)
	if strings.HasPrefix(a, "(") && strings.HasSuffix(a, ")") {
		inner := a[1 : len(a)-1]
		var b strings.Builder
		h := parseHelper(inner, nil, nil)
		renderHelper(h, data, &b)
		return b.String()
	}
	// path lookup
	if v, ok := lookupPath(data, a); ok {
		return v
	}
	return nil
}

func lookupPath(data map[string]interface{}, path string) (interface{}, bool) {
	parts := strings.Split(path, ".")
	var cur interface{} = data
	for _, p := range parts {
		if p == "this" {
			continue
		}
		switch m := cur.(type) {
		case map[string]interface{}:
			v, ok := m[p]
			if !ok {
				return nil, false
			}
			cur = v
		default:
			return nil, false
		}
	}
	return cur, true
