func toStr(v interface{}) string {
	switch x := v.(type) {
	case nil:
		return ""
	case string:
		return x
	case int:
		return strconv.Itoa(x)
	case int64:
		return strconv.FormatInt(x, 10)
	case float64:
		return strconv.FormatFloat(x, 'g', -1, 64)
	case bool:
		if x {
			return "true"
		}
		return "false"
	case []interface{}:
		var parts []string
		for _, i := range x {
			parts = append(parts, toStr(i))
		}
		return strings.Join(parts, ",")
	default:
		j, _ := json.Marshal(v)
		return string(j)
	}
}

func toInt(v interface{}) int {
	switch x := v.(type) {
	case int:
		return x
	case int64:
		return int(x)
	case float64:
		return int(x)
	case string:
		n, _ := strconv.Atoi(x)
		return n
	}
	return 0
}

func toSlice(v interface{}) []interface{} {
	switch x := v.(type) {
	case []interface{}:
		return x
	case []string:
		out := make([]interface{}, len(x))
		for i, s := range x {
			out[i] = s
		}
		return out
	}
	return nil
}

func truthy(v interface{}) bool {
	switch x := v.(type) {
	case nil:
		return false
	case bool:
		return x
	case string:
		return x != ""
	case int:
		return x != 0
	case int64:
		return x != 0
	case float64:
		return x != 0
	case []interface{}:
		return len(x) > 0
	case map[string]interface{}:
		return len(x) > 0
	}
	return true
}

func substring(s string, idx, length int) string {
	if idx < 0 {
		idx = len(s) + idx
	}
	if idx < 0 {
		idx = 0
	}
	if idx > len(s) {
		return ""
	}
	if length < 0 {
		return s[idx:]
	}
	end := idx + length
	if end > len(s) {
		end = len(s)
	}
	return s[idx:end]
}

func runShell(cmd, input string) string {
	c := exec.Command("sh", "-c", cmd)
	if input != "" {
		c.Stdin = strings.NewReader(input)
	}
	out, _ := c.CombinedOutput()
	return string(out)
}

