// parseBlockBody parses the body and optional {{else}} inverse until {{/name}}.
func (p *tparser) parseBlockBody(tag string) (body []tmplNode, inv []tmplNode, err error) {
	body, err = p.parseNodes("")
	if err != nil {
		return nil, nil, err
	}
	// current position is at a {{else}} or {{/...}}
	// detect else
	if p.i < len(p.s) {
		// peek the tag
		if p.i+1 < len(p.s) && p.s[p.i] == '{' && p.s[p.i+1] == '{' {
