// --- slug ---
func slugify(s string) string {
	s = strings.ToLower(s)
	var b strings.Builder
	prevDash := false
	for _, r := range s {
		if unicode.IsLetter(r) || unicode.IsNumber(r) {
			b.WriteRune(r)
			prevDash = false
		} else if r == ' ' || r == '-' || r == '_' {
			if !prevDash && b.Len() > 0 {
				b.WriteRune('-')
				prevDash = true
			}
		}
	}
	return strings.Trim(b.String(), "-")
}

// --- dates ---
type timeVal struct {
	t time.Time
	ok bool
}

func asTime(v interface{}) timeVal {
	switch x := v.(type) {
	case time.Time:
		return timeVal{t: x, ok: true}
	case timeVal:
		return x
	case string:
		if t, err := parseNaturalDate(x); err == nil {
			return timeVal{t: t, ok: true}
		}
	}
	return timeVal{}
}

func parseNaturalDate(s string) (time.Time, error) {
	s = strings.TrimSpace(s)
	if s == "" || s == "now" {
		return time.Now().UTC(), nil
	}
	// try common formats
	formats := []string{
		"2006-01-02 15:04:05",
		"2006-01-02T15:04:05",
		"2006-01-02",
		time.RFC3339,
		time.RFC3339Nano,
	}
	for _, f := range formats {
		if t, err := time.Parse(f, s); err == nil {
			return t.UTC(), nil
		}
	}
	// natural language relative
	return parseRelativeDate(s)
}

func parseRelativeDate(s string) (time.Time, error) {
	now := time.Now().UTC()
	s = strings.ToLower(s)
	switch s {
	case "today":
		return now, nil
	case "yesterday":
		return now.AddDate(0, 0, -1), nil
	case "tomorrow":
		return now.AddDate(0, 0, 1), nil
	}
	// "last week", "2 weeks ago", "3 days ago"
	if strings.HasSuffix(s, " ago") {
		num, unit := parseAgo(s[:len(s)-4])
		return now.Add(-dur(num, unit)), nil
	}
	if strings.HasPrefix(s, "last ") {
		num, unit := parseAgo(strings.TrimPrefix(s, "last "))
		return now.Add(-dur(num, unit)), nil
	}
	if strings.HasPrefix(s, "next ") {
		num, unit := parseAgo(strings.TrimPrefix(s, "next "))
		return now.Add(dur(num, unit)), nil
	}
	if strings.Contains(s, " ") {
		parts := strings.Fields(s)
		if len(parts) == 3 && parts[1] == "ago" {
			n, _ := strconv.Atoi(parts[0])
			return now.Add(-dur(n, parts[1])), nil
		}
	}
	return now, fmt.Errorf("unrecognized")
}

func parseAgo(s string) (int, string) {
	parts := strings.Fields(s)
	if len(parts) == 2 {
		n, _ := strconv.Atoi(parts[0])
		return n, parts[1]
	}
	if len(parts) == 1 {
		return 1, parts[0]
	}
	return 1, s
}

func dur(n int, unit string) time.Duration {
	if !strings.HasSuffix(unit, "s") {
		unit += "s"
	}
	switch unit {
	case "seconds":
		return time.Duration(n) * time.Second
	case "minutes":
		return time.Duration(n) * time.Minute
	case "hours":
		return time.Duration(n) * time.Hour
	case "days":
		return time.Duration(n) * 24 * time.Hour
	case "weeks":
		return time.Duration(n) * 7 * 24 * time.Hour
	case "months":
		return time.Duration(n) * 30 * 24 * time.Hour
	case "years":
		return time.Duration(n) * 365 * 24 * time.Hour
	}
	return 0
}

func formatDate(tv timeVal, format string) string {
	if !tv.ok {
		return ""
	}
	t := tv.t
	switch format {
	case "":
		return t.Format("2006-01-02")
	case "short":
		return t.Format("01/02/2006")
	case "medium":
		return t.Format("Jan 2, 2006")
	case "long":
		return t.Format("January 2, 2006")
	case "full":
		return t.Format("Monday, January 2, 2006")
	case "year":
		return strconv.Itoa(t.Year())
	case "time":
		return t.Format("15:04")
	case "timestamp":
		return t.Format("200601021504")
	case "timestamp-unix":
		return strconv.FormatInt(t.Unix(), 10)
	case "elapsed":
		return elapsedHuman(t)
	}
	if strings.HasPrefix(format, "%") {
		return strftime(format, t)
	}
	return t.Format("2006-01-02")
}

// elapsedHuman computes the "x ago" string like zk.
func elapsedHuman(t time.Time) string {
	d := time.Since(t)
	secs := int(d.Seconds())
	if secs < 0 {
		secs = -secs
	}
	if secs < 60 {
		return "just now"
	}
	if secs < 120 {
		return "1 minute ago"
	}
	if secs < 3600 {
		return fmt.Sprintf("%d minutes ago", secs/60)
	}
	if secs < 7200 {
		return "1 hour ago"
	}
	if secs < 86400 {
		return fmt.Sprintf("%d hours ago", secs/3600)
	}
	if secs < 172800 {
		return "yesterday"
	}
	if secs < 604800 {
		return fmt.Sprintf("%d days ago", secs/86400)
	}
	// weeks
	w := (secs + 604799) / 604800
	if secs == 604800 {
		w = 1
	}
	secsPerMonth := 2629800
	if secs < secsPerMonth {
		return fmt.Sprintf("%d weeks ago", w)
	}
	if secs < 2*secsPerMonth {
		return "1 month ago"
	}
	if secs < 31557600 {
		return fmt.Sprintf("%d months ago", secs/secsPerMonth)
	}
	secsPerYear := 31557600
	if secs < 2*secsPerYear {
		return "1 year ago"
	}
	return fmt.Sprintf("%d years ago", secs/secsPerYear)
}

// strftime implements a subset of strftime.
func strftime(format string, t time.Time) string {
	var b strings.Builder
	for i := 0; i < len(format); i++ {
		if format[i] != '%' || i+1 >= len(format) {
			b.WriteByte(format[i])
			continue
		}
		i++
		c := format[i]
		switch c {
		case 'Y':
			b.WriteString(strconv.Itoa(t.Year()))
		case 'y':
			b.WriteString(fmt.Sprintf("%02d", t.Year()%100))
		case 'm':
			b.WriteString(fmt.Sprintf("%02d", int(t.Month())))
		case 'd':
			b.WriteString(fmt.Sprintf("%02d", t.Day()))
		case 'H':
			b.WriteString(fmt.Sprintf("%02d", t.Hour()))
		case 'M':
			b.WriteString(fmt.Sprintf("%02d", t.Minute()))
		case 'S':
			b.WriteString(fmt.Sprintf("%02d", t.Second()))
		case 'B':
			b.WriteString(t.Month().String())
		case 'b':
			b.WriteString(t.Month().String()[:3])
		case 'A':
			b.WriteString(t.Weekday().String())
		case 'a':
			b.WriteString(t.Weekday().String()[:3])
		case 'e':
			b.WriteString(fmt.Sprintf("%2d", t.Day()))
		case 'j':
			b.WriteString(fmt.Sprintf("%03d", t.YearDay()))
		case 'p':
			if t.Hour() < 12 {
				b.WriteString("AM")
			} else {
				b.WriteString("PM")
			}
		case 'I':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			b.WriteString(fmt.Sprintf("%02d", h))
		case '%':
			b.WriteByte('%')
		case 'n':
			b.WriteByte('\n')
		case 't':
			b.WriteByte('\t')
		case 'G':
			b.WriteString(strconv.Itoa(t.ISOYear()))
		case 'g':
			b.WriteString(fmt.Sprintf("%02d", t.ISOYear()%100))
		default:
			b.WriteByte('%')
			b.WriteByte(c)
		}
	}
	return b.String()
}

// formatLink generates an internal link per markdown config.
func formatLink(path, title string, md MarkdownConfig) string {
	dropExt := md.LinkDropExt == nil || *md.LinkDropExt
	encode := md.LinkEncodePath != nil && *md.LinkEncodePath
	p := path
	if dropExt {
		// remove extension
		if dot := strings.LastIndex(p, "."); dot >= 0 {
			p = p[:dot]
		}
	}
	href := p
	if encode {
		href = urlEscape(p)
	}
	switch md.LinkFormat {
	case "wiki":
		return "[[" + p + "]]"
	case "markdown":
		return "[" + title + "](" + href + ")"
	default:
		// custom template
		return md.LinkFormat
	}
}

func urlEscape(s string) string {
	return s
}

// JSON marshaling helper for notes.
func noteJSON(n *Note, nb *Notebook) string {
	obj := noteToMap(n, nb)
	j, _ := json.Marshal(obj)
	return string(j)
}

func noteToMap(n *Note, nb *Notebook) map[string]interface{} {
	abs := n.Path
	if nb != nil {
		abs = nb.Dir + "/" + n.Path
	}
	link := formatLink(n.Path, n.Stem, *nb.Config.Markdown)
	snippets := []string{}
	if n.Lead != "" {
		snippets = []string{n.Lead}
	}
	return map[string]interface{}{
		"filename":      n.Filename,
		"filenameStem":  n.Stem,
		"path":          n.Path,
		"absPath":       abs,
		"title":         n.Title,
		"link":          link,
		"lead":          n.Lead,
		"body":          n.Body,
		"snippets":      snippets,
		"rawContent":    n.RawContent,
		"wordCount":     n.WordCount,
		"tags":          n.Tags,
		"metadata":      n.Metadata,
		"created":       n.Created,
		"modified":      n.Modified,
		"checksum":      n.Checksum,
	}
}

