package main

import "strings"

// Proper recursive parser for handlebars-like templates with blocks.

func parseTemplate2(tpl string) ([]tmplNode, error) {
	p := &tparser{s: tpl}
	nodes, _ := p.parseNodes()
	return nodes, nil
}

type tparser struct {
	s string
	i int
}

// nextTag returns the inner text of the tag at position i (if any), advancing i past it.
// Returns inner, true if a tag was parsed, or "", false if not at a tag.
func (p *tparser) peekTag() (string, bool) {
	if p.i+1 >= len(p.s) || p.s[p.i] != '{' || p.s[p.i+1] != '{' {
		return "", false
	}
	end := indexClose(p.s, p.i+2)
	if end < 0 {
		return "", false
	}
	return strings.TrimSpace(p.s[p.i+2 : end]), true
}

func (p *tparser) consumeTag() (string, bool) {
	if p.i+1 >= len(p.s) || p.s[p.i] != '{' || p.s[p.i+1] != '{' {
		return "", false
	}
	end := indexClose(p.s, p.i+2)
	if end < 0 {
		return "", false
	}
	inner := strings.TrimSpace(p.s[p.i+2 : end])
	p.i = end + 2
	return inner, true
}

func (p *tparser) parseNodes() ([]tmplNode, error) {
	var nodes []tmplNode
	for p.i < len(p.s) {
		// check for a tag
		if inner, ok := p.peekTag(); ok {
			if strings.HasPrefix(inner, "/") {
				// closing tag — let caller handle
				return nodes, nil
			}
			if inner == "else" || strings.HasPrefix(inner, "else ") {
				return nodes, nil
			}
			// consume it
			inner, _ = p.consumeTag()
			if strings.HasPrefix(inner, "#") {
				body, inv := p.parseBlock()
				h := parseHelper(inner[1:], body, inv)
				nodes = append(nodes, tmplHelper(h))
			} else {
				if isHelperCall(inner) {
					nodes = append(nodes, parseHelper(inner, nil, nil))
				} else {
					nodes = append(nodes, tmplVar{path: inner, raw: "{{" + inner + "}}"})
				}
			}
		} else {
			start := p.i
			for p.i < len(p.s) {
				if p.i+1 < len(p.s) && p.s[p.i] == '{' && p.s[p.i+1] == '{' {
					break
				}
				p.i++
			}
			nodes = append(nodes, tmplText(p.s[start:p.i]))
		}
	}
	return nodes, nil
}

// parseBlock parses the body and optional inverse, then consumes the closing {{/name}}.
func (p *tparser) parseBlock() (body []tmplNode, inv []tmplNode) {
	body, _ = p.parseNodes()
	// now at {{else}} or {{/name}}
	if inner, ok := p.peekTag(); ok {
		if inner == "else" || strings.HasPrefix(inner, "else ") {
			p.consumeTag()
			inv, _ = p.parseNodes()
		}
	}
	// consume closing tag {{/...}}
	if _, ok := p.peekTag(); ok {
		p.consumeTag()
	}
	return body, inv
}
