	var fo FilterOptions
	fs.Flags = append(fs.Flags, newFormattingFlags(&ff, "list", true)...)
	fs.Flags = append(fs.Flags, newFilterFlags("", &fo)...)
	res, err := fs.parse(args)
	if err != nil {
		fmt.Fprintln(os.Stderr, "zk: error: "+err.Error())
		return 1
	}
	if globals.Help {
		fmt.Print(helpList)
		return 0
	}
	fo.Paths = res.Positionals
	nb, ferr := findNotebook(globals.NotebookDir)
	if ferr != nil {
		fmt.Fprintln(os.Stderr, "zk: error: "+ferr.Error())
		return 1
	}
	curMarkdown = *nb.Config.Markdown
	idx := ensureIndex(nb)
	notes := filterNotes(idx, nb, &fo)
	sortNotes(notes, &fo)
	if fo.Limit > 0 && len(notes) > fo.Limit {
		notes = notes[:fo.Limit]
	}
	return outputNotes(notes, nb, &ff, "note")
}

func outputNotes(notes []*Note, nb *Notebook, ff *FormattingFlags, kind string) int {
	stdout := os.Stdout
	if len(notes) > 0 {
		fmt.Fprint(stdout, unescapeZK(ff.Header))
		var blocks []string
		format := ff.Format
		if format == "" {
			format = "short"
		}
		switch format {
		case "json":
			arr := []map[string]interface{}{}
			for _, n := range notes {
				arr = append(arr, noteToMap(n, nb))
			}
			b, _ := json.Marshal(arr)
			blocks = []string{string(b)}
		case "jsonl":
			for _, n := range notes {
				b, _ := json.Marshal(noteToMap(n, nb))
				blocks = append(blocks, string(b))
			}
		default:
			tpl := formatTemplate(format, kind)
			for _, n := range notes {
				blocks = append(blocks, renderTemplate(tpl, noteContext(n, nb)))
			}
		}
		delim := "\n"
		if ff.Delimiter0 {
			delim = "\x00"
		} else if ff.Delimiter != "" {
			delim = unescapeZK(ff.Delimiter)
		}
		fmt.Fprint(stdout, strings.Join(blocks, delim))
		fmt.Fprint(stdout, unescapeZK(ff.Footer))
	}
	if !ff.Quiet {
		fmt.Fprintf(os.Stderr, "\nFound %d %s\n", len(notes), pluralKind(kind, len(notes)))
	}
	return 0
}

func pluralKind(kind string, n int) string {
	switch kind {
	case "note":
		if n > 1 {
			return "notes"
		}
		return "note"
	default:
		if n == 1 {
			return kind
		}
		return kind + "s"
	}
}

func formatTemplate(format, kind string) string {
	switch format {
	case "oneline":
		return "{{title}} {{path}} ({{format-date created \"elapsed\"}})"
	case "short":
		return "{{title}} {{path}} ({{format-date created \"elapsed\"}})\n{{#if lead}}\n  ‣ {{lead}}{{/if}}\n"
	case "medium":
		return "{{title}} {{path}}\nCreated: {{format-date created \"short\"}}\n{{#if lead}}\n  ‣ {{lead}}{{/if}}\n"
	case "long":
		return "{{title}} {{path}}\nCreated: {{format-date created \"short\"}}\nModified: {{format-date modified \"short\"}}\n{{#if lead}}\n  ‣ {{lead}}{{/if}}\n"
	case "full":
		return "{{title}} {{path}}\nCreated: {{format-date created \"short\"}}\nModified: {{format-date modified \"short\"}}\nTags: {{join tags \", \"}}\n{{#if body}}\n{{prepend \"  \" body}}{{/if}}\n"
	}
	return format
