// filterNotes applies the filtering options.
func filterNotes(idx *Index, nb *Notebook, fo *FilterOptions) []*Note {
	var out []*Note
	for _, n := range idx.notes {
		if !matchPaths(n, fo.Paths) {
			continue
		}
		if len(fo.Exclude) > 0 {
			ex := false
			for _, p := range fo.Exclude {
				if pathMatches(n, p) {
					ex = true
					break
				}
			}
			if ex {
				continue
			}
		}
		if len(fo.Tag) > 0 {
			if !hasAllTags(n, fo.Tag) {
				continue
			}
		}
		if fo.Tagless && len(n.Tags) > 0 {
			continue
		}
		if len(fo.Match) > 0 {
			if !matchAll(n, fo.Match, fo.MatchStrategy) {
				continue
			}
		}
		if !dateFilter(n, fo) {
			continue
		}
		out = append(out, n)
	}
	// link-based filters
	out = applyLinkFilters(idx, nb, out, fo)
	return out
}

func matchPaths(n *Note, paths []string) bool {
	if len(paths) == 0 {
		return true
	}
	for _, p := range paths {
		if pathMatches(n, p) {
			return true
		}
	}
	return false
}

func pathMatches(n *Note, p string) bool {
	if p == n.Path || p == n.Stem {
		return true
	}
	if strings.HasPrefix(n.Path, p+"/") {
		return true
	}
	if strings.HasPrefix(n.Stem, p) {
		return true
	}
	if strings.HasSuffix(p, ".md") && strings.HasPrefix(n.Path, p) {
		return true
	}
	return false
}

func hasAllTags(n *Note, tags []string) bool {
	set := map[string]bool{}
	for _, t := range n.Tags {
		set[strings.ToLower(t)] = true
	}
	for _, t := range tags {
		if !set[strings.ToLower(t)] {
			return false
		}
	}
	return true
}

func matchAll(n *Note, queries []string, strategy string) bool {
	for _, q := range queries {
		if !matchOne(n, q, strategy) {
			return false
		}
	}
	return true
}

func matchOne(n *Note, q, strategy string) bool {
	hay := strings.ToLower(n.Title + " " + n.Body)
	q = strings.ToLower(q)
	switch strategy {
	case "re":
		// regex
		return strings.Contains(hay, q) // simplified
	case "exact":
		return strings.Contains(hay, q)
	default:
		// fts: tokenized substring
		return strings.Contains(hay, q)
	}
}

func dateFilter(n *Note, fo *FilterOptions) bool {
	created, _ := time.Parse(time.RFC3339Nano, n.Created)
	modified, _ := time.Parse(time.RFC3339Nano, n.Modified)
	if fo.Created != "" {
		if d, err := parseNaturalDate(fo.Created); err == nil && !sameDay(created, d) {
			return false
		}
	}
	if fo.CreatedBefore != "" {
		if d, err := parseNaturalDate(fo.CreatedBefore); err == nil && !created.Before(d) {
			return false
		}
	}
	if fo.CreatedAfter != "" {
		if d, err := parseNaturalDate(fo.CreatedAfter); err == nil && !created.After(d) {
			return false
		}
	}
	if fo.Modified != "" {
		if d, err := parseNaturalDate(fo.Modified); err == nil && !sameDay(modified, d) {
			return false
		}
	}
	if fo.ModifiedBefore != "" {
		if d, err := parseNaturalDate(fo.ModifiedBefore); err == nil && !modified.Before(d) {
			return false
		}
	}
	if fo.ModifiedAfter != "" {
		if d, err := parseNaturalDate(fo.ModifiedAfter); err == nil && !modified.After(d) {
			return false
		}
	}
	return true
}

func sameDay(a, b time.Time) bool {
	a = a.UTC()
	b = b.UTC()
	return a.Year() == b.Year() && a.Month() == b.Month() && a.Day() == b.Day()
}

func applyLinkFilters(idx *Index, nb *Notebook, in []*Note, fo *FilterOptions) []*Note {
	// link-to, linked-by, orphan, etc. (simplified)
	if fo.Orphan {
		linked := map[int]bool{}
		for _, n := range idx.notes {
			for _, l := range n.Links {
				if l.TargetID != 0 {
					linked[l.TargetID] = true
				}
			}
		}
		var out []*Note
		for _, n := range in {
			if !linked[n.ID] {
				out = append(out, n)
			}
		}
		return out
	}
	return in
}

func sortNotes(notes []*Note, fo *FilterOptions) {
	terms := fo.Sort
	if len(terms) == 0 {
		terms = []string{"title"}
	}
	for i := len(terms) - 1; i >= 0; i-- {
		t := terms[i]
		desc := strings.HasSuffix(t, "-")
		t = strings.TrimSuffix(t, "-")
		sort.SliceStable(notes, func(a, b int) bool {
			ra := sortKey(notes[a], t)
			rb := sortKey(notes[b], t)
			if desc {
				return ra > rb
			}
			return ra < rb
		})
	}
}

func sortKey(n *Note, t string) string {
	switch t {
	case "title":
		return strings.ToLower(n.Title)
	case "path":
		return n.Path
	case "created":
		return n.Created
	case "modified":
		return n.Modified
	case "word-count":
		return fmt.Sprintf("%010d", n.WordCount)
	}
	return n.Title
}
