		if ff.Delimiter0 {
			delim = "\x00"
		} else if ff.DelimiterSet {
			delim = unescapeZK(ff.Delimiter)
		}
		fmt.Fprint(stdout, strings.Join(blocks, delim))
		footer := "\n"
		if ff.FooterSet {
			footer = unescapeZK(ff.Footer)
		}
		fmt.Fprint(stdout, footer)
	}
	if !ff.Quiet {
		n := len(tags)
		word := "tags"
		if n == 1 {
			word = "tag"
		}
		fmt.Fprintf(os.Stderr, "\nFound %d %s\n", n, word)
