				b, _ := json.Marshal(m)
				blocks = append(blocks, string(b))
			}
		case "name":
			for _, t := range tags {
				blocks = append(blocks, t.Name)
			}
		case "full":
			for _, t := range tags {
				blocks = append(blocks, fmt.Sprintf("%s (%d)", t.Name, t.NoteCount))
			}
		default:
			for _, t := range tags {
				ctx := map[string]interface{}{
					"name":       t.Name,
					"note-count": t.NoteCount,
					"id":         t.ID,
					"kind":       "tag",
				}
				blocks = append(blocks, renderTemplate(format, ctx))
			}
		}
		delim := "\n"
		if ff.Delimiter0 {
			delim = "\x00"
		} else if ff.DelimiterSet {
			delim = unescapeZK(ff.Delimiter)
		}
		fmt.Fprint(stdout, strings.Join(blocks, delim))
		footer := "\n"
		if ff.FooterSet {
			footer = unescapeZK(ff.Footer)
		}
		fmt.Fprint(stdout, footer)
	}
	if !ff.Quiet {
		n := len(tags)
		word := "tags"
		if n == 1 {
			word = "tag"
		}
		fmt.Fprintf(os.Stderr, "\nFound %d %s\n", n, word)
	}
	return 0
}
