	SourceID     int      `json:"sourceId"`
	SourcePath   string   `json:"sourcePath"`
	TargetID     int      `json:"targetId"`
	TargetPath   string   `json:"targetPath"`
}

type GraphJSON struct {
	Notes []NoteJSON `json:"notes"`
	Links []LinkJSON `json:"links"`
}

func noteToJSON(n *Note, nb *Notebook) NoteJSON {
	abs := n.Path
	if nb != nil {
		abs = nb.Dir + "/" + n.Path
	}
	snippets := []string{}
	if n.Lead != "" {
		snippets = []string{n.Lead}
	}
	tags := n.Tags
	if tags == nil {
		tags = []string{}
	}
	meta := n.Metadata
	if meta == nil {
		meta = map[string]interface{}{}
	}
	return NoteJSON{
		Filename:     n.Filename,
		FilenameStem: n.Stem,
		Path:         n.Path,
		AbsPath:      abs,
		Title:        n.Title,
		Link:         formatLink(n.Path, n.Stem, nb.Config.Markdown),
		Lead:         n.Lead,
		Body:         n.Body,
		Snippets:     snippets,
		RawContent:   n.RawContent,
		WordCount:    n.WordCount,
		Tags:         tags,
		Metadata:     meta,
		Created:      n.Created,
		Modified:     n.Modified,
		Checksum:     n.Checksum,
	}
}

func marshalNote(n *Note, nb *Notebook) string {
	b, _ := json.Marshal(noteToJSON(n, nb))
	return string(b)
}

func marshalNoteIndent(n *Note, nb *Notebook, indent string) string {
	b, _ := json.MarshalIndent(noteToJSON(n, nb), "", indent)
	return string(b)
}
