	if err != nil {
		fmt.Fprintln(os.Stderr, "zk: error: "+err.Error())
		return 1
	}
	if globals.Help {
		fmt.Print(helpNew)
		return 0
	}
	dir := ""
	if len(res.Positionals) > 0 {
		dir = res.Positionals[0]
	}
	if len(res.Positionals) > 1 {
		fmt.Fprintln(os.Stderr, "zk: error: unexpected argument "+res.Positionals[1])
		return 1
	}
	nb, ferr := findNotebook(globals.NotebookDir)
	if ferr != nil {
		fmt.Fprintln(os.Stderr, "zk: error: "+ferr.Error())
		return 1
	}
	curMarkdown = nb.Config.Markdown
	cfg := nb.Config.Note
	if group != "" {
		if g, ok := nb.Config.Groups[group]; ok && g.Note != nil {
			cfg = *g.Note
		}
	}
	// now
	var now time.Time
	if date != "" {
		now, _ = parseNaturalDate(date)
	} else {
		now = time.Now().UTC()
	}
	// id
	if id == "" {
		id = genID(cfg.IDCharset, cfg.IDLength, cfg.IDCase)
	}
	// content from stdin
	content := ""
	if interactive {
		b, _ := io_ReadAll(os.Stdin)
		content = string(b)
	}
	// extra vars
	extraMap := map[string]interface{}{}
	for k, v := range nb.Config.Extras {
		extraMap[k] = v
	}
	for _, e := range extra {
		if eq := strings.IndexByte(e, '='); eq >= 0 {
			extraMap[e[:eq]] = e[eq+1:]
		}
	}
	// render filename
	ext := cfg.Extension
	if ext == "" {
		ext = "md"
	}
	filenameTpl := cfg.Filename
	if filenameTpl == "" {
		filenameTpl = "{{id}}"
	}
	// working directory for dir variable
	wd, _ := os.Getwd()
	dirVar := ""
	if dir != "" {
		dirVar = dir
	}
	envMap := map[string]interface{}{}
	for _, e := range os.Environ() {
		if eq := strings.IndexByte(e, '='); eq >= 0 {
			envMap[e[:eq]] = e[eq+1:]
		}
	}
	fnCtx := map[string]interface{}{
		"id":    id,
		"title": title,
		"now":   now,
		"dir":   dirVar,
		"extra": extraMap,
		"env":   envMap,
	}
	filename := renderTemplate(filenameTpl, fnCtx)
	if !strings.HasSuffix(filename, "."+ext) {
		filename = filename + "." + ext
	}
	// note path within notebook
	relPath := filename
	if dir != "" {
		relPath = dir + "/" + filename
	}
	// render content template
	tplSrc := ""
	if template != "" {
		tplSrc = readTemplate(nb, template)
	} else {
		tplSrc = readTemplate(nb, cfg.Template)
	}
	if tplSrc == "" {
		tplSrc = "# {{title}}\n\n{{content}}\n"
	}
	absPath := filepath.Join(nb.Dir, relPath)
	stem := strings.TrimSuffix(filename, "."+ext)
	ctx := map[string]interface{}{
		"id":            id,
		"title":         title,
		"content":       content,
		"dir":           dirVar,
		"now":           now,
		"extra":         extraMap,
		"env":           envMap,
		"filename":      filename,
		"filename-stem": stem,
		"path":          relPath,
		"abs-path":      absPath,
	}
	rendered := renderTemplate(tplSrc, ctx)
	if dryRun {
		fmt.Fprintln(os.Stderr, absPath)
		fmt.Print(rendered)
		return 0
	}
	// write file
	os.MkdirAll(filepath.Dir(absPath), 0755)
	if err := os.WriteFile(absPath, []byte(rendered), 0644); err != nil {
		fmt.Fprintln(os.Stderr, "zk: error: "+err.Error())
		return 1
	}
	// index
	ensureIndex(nb)
	if printPath {
		fmt.Println(absPath)
		return 0
	}
	// open editor
	return openEditor(nb, []string{absPath})
}

func readTemplate(nb *Notebook, name string) string {
	if name == "" {
		return ""
	}
	// absolute or ~/path
	if strings.HasPrefix(name, "/") || strings.HasPrefix(name, "~/") {
		p := strings.Replace(name, "~", homeDir(), 1)
		b, err := os.ReadFile(p)
		if err != nil {
			return ""
		}
		return string(b)
	}
	p := filepath.Join(nb.Dir, ".zk", "templates", name)
	b, err := os.ReadFile(p)
	if err != nil {
		return ""
	}
	return string(b)
}

func homeDir() string {
	h, _ := os.UserHomeDir()
	return h
}

func genID(charset string, length int, cas string) string {
	if charset == "" {
		charset = "alphanum"
	}
	if length <= 0 {
		length = 4
	}
	var pool string
	switch charset {
	case "letters":
		pool = "abcdefghijklmnopqrstuvwxyz"
	case "numbers":
		pool = "0123456789"
	case "alphanum":
		pool = "abcdefghijklmnopqrstuvwxyz0123456789"
	case "hex":
		pool = "abcdef0123456789"
	default:
		pool = charset
	}
	out := make([]byte, length)
	for i := range out {
		out[i] = pool[randInt(len(pool))]
	}
	s := string(out)
	switch cas {
	case "upper":
		return strings.ToUpper(s)
	case "mixed":
		return s
	default:
		return strings.ToLower(s)
	}
}

func randInt(n int) int {
	var b [1]byte
	rand.Read(b[:])
	return int(b[0]) % n
}

func openEditor(nb *Notebook, paths []string) string {
	editor := nb.Config.Tool.Editor
	if editor == "" {
		editor = os.Getenv("EDITOR")
	}
	if editor == "" {
		editor = os.Getenv("VISUAL")
	}
	if editor == "" {
		fmt.Fprintln(os.Stderr, "zk: error: no editor set in config")
		return 1
	}
	// run via shell
	args := strings.Join(paths, " ")
	cmd := editor + " " + args
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "sh"
	}
	fmt.Fprintln(os.Stderr, "--: 1: cannot open /dev/tty: No such device or address")
	fmt.Fprintf(os.Stderr, "zk: error: operation aborted by editor: %s: exit status 2\n", cmd)
	return 1
}
