#!/usr/bin/env python3
"""revise - a TUI spaced repetition client (reimplementation)."""
import sys, os, sqlite3, subprocess, tempfile, shutil, re, time, datetime, struct, fcntl, termios, tty, select, math, random, uuid, traceback

