    if v and os.path.isabs(v):
        return v
    return os.path.join(os.path.expanduser("~"), ".config")

def _xdg_data_home():
    v = os.environ.get("XDG_DATA_HOME")
    if v and os.path.isabs(v):
        return v
    return os.path.join(os.path.expanduser("~"), ".local", "share")

def config_path():
