        log_init()
    _log_fh.write(f"{_ts()} ERROR {file_line}: {msg}\n")
    _log_fh.flush()

# ---------------------------------------------------------------------------
# Error reporting (color-eyre / human-panic emulation)
# ---------------------------------------------------------------------------
def print_eyre_error(message):
    """message may be multi-line. Mimics color-eyre single-error report."""
    lines = message.split("\n")
    out = []
    out.append("Error: \n")
    out.append("   0: \033[91m")
    out.append(lines[0])
    for l in lines[1:]:
        out.append("\n   0: ")
        out.append(l)
    out.append("\033[0m\n")
    sys.stderr.write("".join(out))
    sys.stderr.flush()

def relpath_to_cwd(path):
    try:
        return os.path.relpath(path)
    except ValueError:
        return path

# ---------------------------------------------------------------------------
# Minimal TOML parser (for config). Lenient: returns dict; raises TomlError.
# ---------------------------------------------------------------------------
class TomlError(Exception):
    def __init__(self, line, col, message, src_line):
        self.line = line
        self.col = col
        self.message = message
        self.src_line = src_line

def parse_toml(text):
    """Very small TOML parser: key=value, strings, ints, floats, bools, arrays, tables."""
    result = {}
    current = result
    lines = text.split("\n")
    i = 0
    while i < len(lines):
        raw = lines[i]
        line = raw.strip()
        # track original line number (1-based) and column
        lineno = i + 1
        if line == "" or line.startswith("#"):
            i += 1
            continue
        if line.startswith("["):
            # table header
            if not line.endswith("]"):
                _toml_err(lineno, len(raw)+1, "expected `]`", raw)
            name = line[1:-1].strip()
            parts = [p.strip() for p in name.split(".")]
            d = result
            for p in parts:
                if p == "":
                    _toml_err(lineno, 2, "expected key", raw)
                d = d.setdefault(p, {})
            current = d
            i += 1
            continue
        # key = value
        m = re.match(r'^([^=]*)=(.*)$', line)
        if not m:
            # find column of unexpected char
            col = 0
            for ch in line:
                if ch.isspace():
                    col += 1
                else:
                    break
            _toml_err(lineno, col+1, "expected `.`, `=`", raw)
        key = m.group(1).strip()
        val = m.group(2).strip()
        if key == "":
            _toml_err(lineno, 1, "expected key", raw)
        # parse value
        try:
            current[key] = _parse_val(val, lineno, raw)
        except TomlError:
            raise
        except Exception:
            _toml_err(lineno, len(line)+1, "invalid value", raw)
        i += 1
    return result

def _toml_err(line, col, message, src_line):
    raise TomlError(line, col, message, src_line)

def _parse_val(val, lineno, raw):
    if val.startswith('"'):
        # string
        end = val.find('"', 1)
        if end == -1:
            _toml_err(lineno, len(raw)+1, "unterminated string", raw)
        return val[1:end]
    if val.startswith("'"):
        end = val.find("'", 1)
        if end == -1:
            _toml_err(lineno, len(raw)+1, "unterminated string", raw)
        return val[1:end]
    if val.startswith("["):
        # array
        inner = val[1:val.rfind("]")]
        items = []
        for it in _split_array(inner):
            it = it.strip()
            if it:
                items.append(_parse_val(it, lineno, raw))
        return items
    if val in ("true", "false"):
        return val == "true"
    # number
    try:
        if "." in val or "e" in val or "E" in val:
            return float(val)
        return int(val)
    except ValueError:
        _toml_err(lineno, len(raw)+1, f"invalid value", raw)

def _split_array(s):
    out = []
    cur = ""
    depth = 0
    instr = False
    for ch in s:
        if instr:
            cur += ch
            if ch == '"':
                instr = False
            continue
        if ch == '"':
            instr = True
            cur += ch
        elif ch == "[":
            depth += 1; cur += ch
        elif ch == "]":
            depth -= 1; cur += ch
        elif ch == "," and depth == 0:
            out.append(cur); cur = ""
        else:
            cur += ch
    if cur.strip():
        out.append(cur)
    return out

def toml_error_message(e, text, relpath):
    """Format like the toml crate's error display."""
    lines = text.split("\n")
    src_line = lines[e.line-1] if e.line-1 < len(lines) else ""
    caret = " " * (e.col - 1) + "^"
    msg = f"TOML parse error at line {e.line}, column {e.col}\n"
    msg += "  |\n"
    msg += f"{e.line} | {src_line}\n"
    msg += f"  | {caret}\n"
    msg += f"{e.message}\n"
    msg += f" in {relpath}"
    return msg

# ---------------------------------------------------------------------------
# Config
# ---------------------------------------------------------------------------
class Config:
    def __init__(self):
        self.editor = None
        self.raw = {}

def load_config():
    cfg = Config()
    p = config_path()
    if not os.path.exists(p):
        log_error("src/config.rs:75", "No configuration file found. Application may not behave as expected")
        return cfg
    try:
        with open(p, "r") as f:
            text = f.read()
        cfg.raw = parse_toml(text)
    except TomlError as e:
        rel = relpath_to_cwd(p)
        msg = toml_error_message(e, text, rel)
        print_eyre_error(msg)
        sys.exit(1)
    except Exception as e:
        rel = relpath_to_cwd(p)
        print_eyre_error(str(e))
        sys.exit(1)
    # extract editor if present
    ed = cfg.raw.get("editor")
    if isinstance(ed, str):
        cfg.editor = ed
    return cfg

# ---------------------------------------------------------------------------
# Database
# ---------------------------------------------------------------------------
SCHEMA = """
CREATE TABLE IF NOT EXISTS decks (
            id integer primary key autoincrement,
            name text NOT NULL,
            created_at text NOT NULL
        );
CREATE TABLE IF NOT EXISTS cards (
            id integer primary key autoincrement,
            deck_id integer NOT NULL,
