            interval integer NOT NULL,
            review_time text NOT NULL,
            stability real NOT NULL,
            difficulty real NOT NULL,
            FOREIGN KEY(card_id) REFERENCES cards(id)
        );
"""

def db_init():
    p = db_path()
    os.makedirs(os.path.dirname(p), exist_ok=True)
    con = sqlite3.connect(p)
    con.executescript(SCHEMA)
    con.commit()
    return con

# ---------------------------------------------------------------------------
# Time helpers (chrono-style formatting)
# ---------------------------------------------------------------------------
def now_utc():
    return datetime.datetime.now(datetime.timezone.utc)

def chrono_fmt(dt):
    """Format like chrono's DateTime<Utc> to_string: 'YYYY-MM-DD HH:MM:SS.nnnnnnnnn+00:00'"""
    return dt.strftime("%Y-%m-%d %H:%M:%S.") + f"{dt.microsecond*1000:09d}" + "+00:00"

def parsechrono(s):
    """Parse the chrono-format string back to a datetime."""
    # 'YYYY-MM-DD HH:MM:SS.nnnnnnnnn+00:00'
    try:
        return datetime.datetime.fromisoformat(s)
    except Exception:
        # try without tz
        return datetime.datetime.strptime(s[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=datetime.timezone.utc)

def date_only(s):
    return s[:10]

# ---------------------------------------------------------------------------
# FSRS
# ---------------------------------------------------------------------------
# Measured initial stability & difficulty for first review (FSRS-6 defaults)
INIT_S = {1: 0.40255001187324524, 2: 1.1838500499725342, 3: 3.1730000972747803, 4: 15.691049575805664}
INIT_D = {1: 7.194900035858154, 2: 6.48830509185791, 3: 5.282434463500977, 4: 3.224501609802246}

def fsrs_first_review(rating):
    """Returns (stability, difficulty) for a new card."""
    return INIT_S[rating], INIT_D[rating]

def fsrs_next_interval_days(stability):
    """Stored interval in days (floor of stability for retention 0.9)."""
    return int(stability)

def fsrs_display_interval(stability):
    """Displayed interval in the review dialog (round)."""
    return int(round(stability))

# Placeholder for subsequent review stability/difficulty updates
def fsrs_update(stability, difficulty, rating, elapsed_days, retrievability):
    """Best-effort FSRS-5 update. Returns (new_stability, new_difficulty)."""
    w = _FSRS_W
    if rating == 1:
        ns = w[11] * (stability ** (-w[12])) * (math.exp((1 - retrievability) * w[13]) - 1)
    else:
        hard_penalty = w[15] if rating == 2 else 1.0
        easy_bonus = w[16] if rating == 4 else 1.0
        ns = stability * (1 + math.exp(w[8]) * (11 - difficulty) * (stability ** (-w[9])) * (math.exp((1 - retrievability) * w[10]) - 1)) * hard_penalty * easy_bonus
    # difficulty update
    nd = difficulty + (rating - 3) * w[17] - (rating - 3) * difficulty / 10.0 * w[18]
    nd = min(max(nd, 1.0), 10.0)
    return ns, nd

