					// clap: "error: unexpected value 'X' for '--flag' found"
					return nil, newClapError(fmt.Sprintf("unexpected value '%s' for '--%s' found", value, f.long))
				}
				setFlag(opts, f)
			}

			seenMap[f.long] = true
			seenFlags = append(seenFlags, f.long)
		} else if strings.HasPrefix(arg, "-") && arg != "-" {
			// Short flag(s)
			body := arg[1:]
			j := 0
			for j < len(body) {
				c := body[j]
				f := findShortFlag(c)
				if f == nil {
					// Unknown short flag
					return nil, unknownShortFlagError(c)
				}

				if f.long == "help" {
					opts.help = true
					opts.helpLong = false
					return opts, nil
				}
				if f.long == "version" {
					opts.version = true
					return opts, nil
				}

