					// Value is the rest of the body, or next arg
					rest := body[j+1:]
					if len(rest) > 0 {
						if rest[0] == '=' {
							setFlagValue(opts, f, rest[1:])
						} else {
							setFlagValue(opts, f, rest)
						}
					} else {
