func unknownFlagError(name string) *clapError {
	suggestion := suggestFlag(name)
	msg := fmt.Sprintf("unexpected argument '--%s' found", name)
	if suggestion != "" {
		msg += fmt.Sprintf("\n\n  tip: a similar argument exists: '--%s'", suggestion)
	} else {
		msg += fmt.Sprintf("\n\n  tip: to pass '--%s' as a value, use '-- --%s'", name, name)
	}
	usage := buildUsageForSuggestion(suggestion)
	return &clapError{msg: msg, usage: usage}
}

func unknownShortFlagError(c byte) *clapError {
	flag := fmt.Sprintf("-%c", c)
	msg := fmt.Sprintf("unexpected argument '%s' found", flag)
	msg += fmt.Sprintf("\n\n  tip: to pass '%s' as a value, use '-- %s'", flag, flag)
	return &clapError{msg: msg}
}

func buildUsageForSuggestion(suggestion string) string {
	if suggestion == "" {
		return ""
	}
	f := findLongFlag(suggestion)
	if f == nil {
		return "[OPTIONS] [PATH]"
	}
	return flagUsageStr(f) + " [PATH]"
}

// Suggest a flag using jaro-winkler similarity (threshold 0.7)
func suggestFlag(input string) string {
	type candidate struct {
		flag string
		sim  float64
	}
	var candidates []candidate
	for _, fd := range flagDefs {
		sim := jaroWinkler(input, fd.long)
		if sim >= 0.7 {
			candidates = append(candidates, candidate{fd.long, sim})
		}
	}
	if len(candidates) == 0 {
		return ""
	}
	// Sort by sim descending; on ties, last one wins (clap uses >= comparison)
	// So we iterate and keep the last one with max sim
	best := candidates[0]
	for _, c := range candidates[1:] {
		if c.sim >= best.sim {
			best = c
		}
	}
	return best.flag
}

func requiredExportError(seenFlags []string) *clapError {
	// Build usage: executable <given-flags> <--export-pdf|--export-html> [PATH]
	var parts []string
	for _, f := range seenFlags {
		fd := findLongFlag(f)
		if fd != nil {
			parts = append(parts, flagUsageStr(fd))
		}
	}
	parts = append(parts, "<--export-pdf|--export-html>")
	usage := strings.Join(parts, " ") + " [PATH]"
	return &clapError{
		msg:   "the following required arguments were not provided:\n  <--export-pdf|--export-html>",
		usage: usage,
	}
}

func checkConflicts(seenFlags []string, positionals []string) *clapError {
	hasPath := len(positionals) > 0

	// Find exclusive flags
	var exclFlags []string
	for _, f := range seenFlags {
		if exclusiveFlags[f] {
			exclFlags = append(exclFlags, f)
		}
	}

	// Find export flags
	var expFlags []string
	for _, f := range seenFlags {
		if exportFlags[f] {
			expFlags = append(expFlags, f)
		}
	}

	// Check exclusive flag conflicts
	if len(exclFlags) > 0 {
		// First exclusive flag conflicts with the rest + path
		first := exclFlags[0]
		var conflicts []string
		for _, f := range exclFlags[1:] {
			conflicts = append(conflicts, "--"+f)
		}
		if hasPath {
			conflicts = append(conflicts, "[PATH]")
		}

		if len(conflicts) == 1 {
			return newClapErrorUsage(
				fmt.Sprintf("the argument '--%s' cannot be used with '%s'", first, conflicts[0]),
				buildConflictUsage(seenFlags),
			)
		} else if len(conflicts) > 1 {
			msg := fmt.Sprintf("the argument '--%s' cannot be used with:", first)
			for _, c := range conflicts {
				msg += fmt.Sprintf("\n  %s", c)
			}
			return newClapErrorUsage(msg, buildConflictUsage(seenFlags))
		}
	}

	// Check export flag conflicts (only if 2+ export flags)
	if len(expFlags) > 1 {
		first := expFlags[0]
		second := expFlags[1]
		// Export flags conflict with each other, not with path
		// But if path is present, the first one conflicts with the second AND path is required
		var msg, usage string
		if hasPath {
			// When path is given, export flag requires path (<PATH>)
			msg = fmt.Sprintf("the argument '--%s' cannot be used with '--%s'", first, second)
			usage = buildExportConflictUsage(seenFlags, true)
		} else {
			msg = fmt.Sprintf("the argument '--%s' cannot be used with '--%s'", first, second)
			usage = buildExportConflictUsage(seenFlags, false)
		}
		return newClapErrorUsage(msg, usage)
	}

	// Check exclusive flag vs path (when only 1 exclusive flag and path)
	if len(exclFlags) == 1 && hasPath && len(exclFlags) == 1 {
		// Already handled above when len(conflicts) >= 1
	}

	return nil
}

func buildConflictUsage(seenFlags []string) string {
	var parts []string
	for _, f := range seenFlags {
		fd := findLongFlag(f)
		if fd != nil {
			parts = append(parts, flagConflictStr(fd))
		}
	}
	parts = append(parts, "[PATH]")
	return strings.Join(parts, " ")
}

func buildExportConflictUsage(seenFlags []string, hasPath bool) string {
	var parts []string
	for _, f := range seenFlags {
		fd := findLongFlag(f)
		if fd != nil {
			parts = append(parts, flagConflictStr(fd))
		}
	}
	if hasPath {
		// Only show the first export flag + <PATH>
