package main

import (
	"encoding/base64"
	"fmt"
	"math/rand"
	"os"
	"os/user"
	"path/filepath"
	"strings"
)

var knownThemes = []string{
	"catppuccin-frappe", "catppuccin-latte", "catppuccin-macchiato", "catppuccin-mocha",
	"dark", "gruvbox-dark", "light", "terminal-dark", "terminal-light",
	"tokyonight-day", "tokyonight-moon", "tokyonight-night", "tokyonight-storm",
}

func isKnownTheme(theme string) bool {
	for _, t := range knownThemes {
		if t == theme {
			return true
		}
	}
	return false
}

type Config struct {
	defaultsTheme string
	hasDefaults   bool
}

func loadConfig(opts *Options) (*Config, error) {
	configPath := ""

	if opts.hasConfigFile {
		configPath = opts.configFile
	} else if envPath := os.Getenv("PRESENTERM_CONFIG_FILE"); envPath != "" {
		configPath = envPath
	} else {
		// Default config path
		configPath = defaultConfigPath()
		if configPath == "" {
			// No default config, use built-in defaults
			return &Config{}, nil
		}
		// Check if default config exists
		if _, err := os.Stat(configPath); err != nil {
			// Default config doesn't exist, use built-in defaults
			return &Config{}, nil
		}
	}

	// If config path is from -c or env, it must exist
	if opts.hasConfigFile || os.Getenv("PRESENTERM_CONFIG_FILE") != "" {
		if _, err := os.Stat(configPath); err != nil {
			if os.IsNotExist(err) {
				return nil, fmt.Errorf("config file not found")
			}
		}
	}

	data, err := os.ReadFile(configPath)
	if err != nil {
		return nil, err
	}

	cfg, err := parseConfig(string(data), configPath)
	if err != nil {
		return nil, err
	}

	return cfg, nil
}

func defaultConfigPath() string {
	xdgConfig := os.Getenv("XDG_CONFIG_HOME")
	if xdgConfig != "" {
		return filepath.Join(xdgConfig, "presenterm", "config.yaml")
	}
	// Fall back to ~/.config/presenterm/config.yaml
	usr, err := user.Current()
	if err != nil || usr.HomeDir == "" {
		// Try HOME env
		home := os.Getenv("HOME")
		if home == "" {
			return ""
		}
		return filepath.Join(home, ".config", "presenterm", "config.yaml")
	}
	return filepath.Join(usr.HomeDir, ".config", "presenterm", "config.yaml")
}

// parseConfig does a basic YAML parse for the fields we care about
func parseConfig(data, configPath string) (*Config, error) {
	cfg := &Config{}

	// Basic YAML parsing
	// We need to detect: unknown top-level fields, and defaults.theme
	lines := strings.Split(data, "\n")

	// Simple state machine for YAML parsing
	// Track indentation level
	type yamlLine struct {
		indent  int
		key     string
		value   string
		hasValue bool
		lineNum int
	}

	var ylines []yamlLine
	for i, line := range lines {
		// Remove trailing whitespace
		line = strings.TrimRight(line, " \t\r")
		if strings.TrimSpace(line) == "" {
			continue
		}
		// Skip comments
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		indent := 0
		for indent < len(line) && line[indent] == ' ' {
			indent++
		}
		content := line[indent:]
		// Parse key: value
		colonIdx := strings.IndexByte(content, ':')
		if colonIdx < 0 {
			// Not a key-value, could be a list item or other
			continue
		}
		key := strings.TrimSpace(content[:colonIdx])
		rest := ""
		if colonIdx+1 < len(content) {
			rest = strings.TrimSpace(content[colonIdx+1:])
		}
		yl := yamlLine{
			indent:   indent,
			key:      key,
			value:    rest,
			hasValue: rest != "",
			lineNum:  i + 1,
		}
		ylines = append(ylines, yl)
	}

	validTopFields := []string{"defaults", "typst", "mermaid", "d2", "options", "bindings", "snippet", "speaker_notes", "export", "transition"}

	// Parse top-level fields (indent 0)
	for i := 0; i < len(ylines); i++ {
		yl := ylines[i]
		if yl.indent != 0 {
			continue
		}
		// Check if it's a known top-level field
		known := false
		for _, vf := range validTopFields {
			if vf == yl.key {
				known = true
				break
			}
		}
		if !known {
			return nil, fmt.Errorf("invalid configuration: unknown field `%s`, expected one of `defaults`, `typst`, `mermaid`, `d2`, `options`, `bindings`, `snippet`, `speaker_notes`, `export`, `transition`", yl.key)
		}

		// Check for inline value (should be empty for struct types)
		if yl.hasValue {
			// It has a value - check if it's a valid type
			val := yl.value
			if yl.key == "defaults" {
				// defaults should be a struct, not a scalar
				// Check if it's an integer
				if isInteger(val) {
					return nil, fmt.Errorf("invalid configuration: defaults: invalid type: integer `%s`, expected struct DefaultsConfig at line %d column %d", val, yl.lineNum, indentForKey(yl.key, lines[yl.lineNum-1])+1)
				}
				// Could be other types
			}
		}

		// Parse defaults sub-fields
		if yl.key == "defaults" {
			cfg.hasDefaults = true
			validDefaultsFields := []string{"theme", "terminal_font_size", "image_protocol", "validate_overflows", "max_columns", "max_columns_alignment", "max_rows", "max_rows_alignment", "incremental_lists", "incremental_tables"}

			// Find sub-fields (indent > 0, until next indent-0 field)
			for j := i + 1; j < len(ylines); j++ {
				sub := ylines[j]
				if sub.indent == 0 {
					break
				}
				if sub.indent > 0 {
					// Check if known sub-field
					subKnown := false
					for _, vf := range validDefaultsFields {
						if vf == sub.key {
							subKnown = true
							break
						}
					}
					if !subKnown {
						return nil, fmt.Errorf("invalid configuration: defaults: unknown field `%s`, expected one of `theme`, `terminal_font_size`, `image_protocol`, `validate_overflows`, `max_columns`, `max_columns_alignment`, `max_rows`, `max_rows_alignment`, `incremental_lists`, `incremental_tables` at line %d column %d", sub.key, sub.lineNum, sub.indent+1)
					}
					if sub.key == "theme" && sub.hasValue {
						cfg.defaultsTheme = sub.value
					}
				}
			}
		}
	}

	return cfg, nil
}

func indentForKey(key, line string) int {
	idx := strings.Index(line, key)
	return idx
}

func isInteger(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func resolveTheme(opts *Options, cfg *Config) string {
	if opts.hasTheme {
		return opts.theme
	}
	if cfg != nil && cfg.hasDefaults && cfg.defaultsTheme != "" {
		return cfg.defaultsTheme
	}
	return "dark"
}

func runCurrentTheme(opts *Options) {
	// Load config
	cfg, err := loadConfig(opts)
	if err != nil {
		printRuntimeError(err.Error())
		os.Exit(1)
	}
	theme := resolveTheme(opts, cfg)
	fmt.Println(theme)
	os.Exit(0)
}

func runListThemes(opts *Options) {
	// Send kitty query
	sendKittyQuery()

	// Load config
	cfg, err := loadConfig(opts)
	if err != nil {
		printRuntimeError(err.Error())
		os.Exit(1)
	}
	_ = cfg

	// Try terminal init - fails without TTY
	printRuntimeError("No such device or address (os error 6)")
	os.Exit(1)
}

func runNormalMode(opts *Options) {
	// Send kitty query
	sendKittyQuery()

	// Read response fails
	printRuntimeError("io: No such device or address (os error 6)")
	os.Exit(1)
}

func sendKittyQuery() {
	// Create temp file with 4 zero bytes
	tmpFile, err := os.CreateTemp("/tmp", ".tmp*")
	if err != nil {
		return
	}
	tmpPath := tmpFile.Name()
	tmpFile.Write([]byte{0, 0, 0, 0})
	tmpFile.Close()

	// Generate random image ID
	id := rand.Uint32()

	// Send kitty graphics query: f=32,a=q,t=f,i=<id>,s=1,v=1;<base64 path>
	pathB64 := base64.StdEncoding.EncodeToString([]byte(tmpPath))
	fmt.Printf("\x1b_Gf=32,a=q,t=f,i=%d,s=1,v=1;%s\x1b\\", id, pathB64)

	// Send second query: f=32,a=q,t=d,i=<id+1>,s=1,v=1;AAAAAA==
	dataB64 := base64.StdEncoding.EncodeToString([]byte{0, 0, 0, 0})
	fmt.Printf("\x1b_Gf=32,a=q,t=d,i=%d,s=1,v=1;%s\x1b\\", id+1, dataB64)
}
