func parseArgs(args []string) (*Options, *clapError) {
	opts := &Options{}
	var seenFlags []string
	seenMap := map[string]bool{}
	var positionals []string
	doubleDash := false

	i := 0
	for i < len(args) {
		arg := args[i]
		i++

		if doubleDash {
			positionals = append(positionals, arg)
			continue
		}

		if arg == "--" {
			doubleDash = true
			continue
		}

		if strings.HasPrefix(arg, "--") {
			body := arg[2:]
			var name, value string
			hasEqValue := false
			if idx := strings.IndexByte(body, '='); idx >= 0 {
				name = body[:idx]
				value = body[idx+1:]
				hasEqValue = true
			} else {
				name = body
			}

