							return nil, missingValueError(f)
						}
						nextArg := args[i]
						if isFlagLike(nextArg) {
							return nil, missingValueError(f)
						}
						setFlagValue(opts, f, nextArg)
						i++
					}
					seenMap[f.long] = true
					seenFlags = append(seenFlags, f.long)
					break
				} else {
					setFlag(opts, f)
					seenMap[f.long] = true
					seenFlags = append(seenFlags, f.long)
					j++
				}
			}
		} else {
			positionals = append(positionals, arg)
		}
	}

	if len(positionals) > 1 {
		return nil, newClapError(fmt.Sprintf("unexpected argument '%s' found", positionals[1]))
	}
	if len(positionals) == 1 {
		opts.path = positionals[0]
	}

	if opts.hasImageProtocol {
		valid := false
		for _, p := range imageProtocols {
			if opts.imageProtocol == p {
				valid = true
				break
			}
		}
		if !valid {
			return nil, &clapError{
				msg: fmt.Sprintf("invalid value '%s' for '--image-protocol <IMAGE_PROTOCOL>'\n  [possible values: auto, iterm2, iterm2-multipart, kitty-local, kitty-remote, sixel, ascii-blocks]", opts.imageProtocol),
			}
		}
	}

	if opts.hasExportTempPath || opts.hasOutput {
		if !opts.exportPdf && !opts.exportHtml {
			return nil, requiredExportError(seenFlags)
		}
	}

	if cerr := checkConflicts(seenFlags, positionals); cerr != nil {
		return nil, cerr
	}

	return opts, nil
}

func isFlagLike(s string) bool {
	if s == "-" {
		return false
	}
	return strings.HasPrefix(s, "-")
}

func setFlag(opts *Options, f *flagDef) {
	switch f.long {
	case "export-pdf":
		opts.exportPdf = true
	case "export-html":
		opts.exportHtml = true
	case "present":
		opts.present = true
	case "list-themes":
		opts.listThemes = true
	case "current-theme":
		opts.currentTheme = true
	case "acknowledgements":
		opts.acknowledgements = true
	case "validate-overflows":
		opts.validateOverflows = true
	case "enable-snippet-execution":
		opts.enableSnippetExec = true
	case "enable-snippet-execution-replace":
		opts.enableSnippetReplace = true
	case "publish-speaker-notes":
		opts.publishNotes = true
	case "listen-speaker-notes":
		opts.listenNotes = true
	case "validate-snippets":
		opts.validateSnippets = true
	case "list-comment-commands":
		opts.listCommentCommands = true
	}
}

func setFlagValue(opts *Options, f *flagDef, value string) {
	switch f.long {
	case "export-temporary-path":
		opts.exportTempPath = value
		opts.hasExportTempPath = true
	case "output":
		opts.output = value
		opts.hasOutput = true
	case "theme":
		opts.theme = value
		opts.hasTheme = true
	case "image-protocol":
		opts.imageProtocol = value
		opts.hasImageProtocol = true
	case "config-file":
		opts.configFile = value
		opts.hasConfigFile = true
	}
}

func missingValueError(f *flagDef) *clapError {
	msg := fmt.Sprintf("a value is required for '%s' but none was supplied", flagUsageStr(f))
	if f.long == "image-protocol" {
		msg += "\n  [possible values: auto, iterm2, iterm2-multipart, kitty-local, kitty-remote, sixel, ascii-blocks]"
	}
	return newClapErrorNoUsage(msg)
}

func unknownFlagError(name string) *clapError {
	suggestion := suggestFlag(name)
	msg := fmt.Sprintf("unexpected argument '--%s' found", name)
	if suggestion != "" {
		msg += fmt.Sprintf("\n\n  tip: a similar argument exists: '--%s'", suggestion)
	} else {
		msg += fmt.Sprintf("\n\n  tip: to pass '--%s' as a value, use '-- --%s'", name, name)
	}
	usage := buildUsageForSuggestion(suggestion)
	return &clapError{msg: msg, usage: usage}
}

func unknownShortFlagError(c byte) *clapError {
	flag := fmt.Sprintf("-%c", c)
	msg := fmt.Sprintf("unexpected argument '%s' found", flag)
	msg += fmt.Sprintf("\n\n  tip: to pass '%s' as a value, use '-- %s'", flag, flag)
	return newClapError(msg)
}

func buildUsageForSuggestion(suggestion string) string {
	if suggestion == "" {
		return ""
	}
	f := findLongFlag(suggestion)
	if f == nil {
		return "[OPTIONS] [PATH]"
	}
	return flagUsageStr(f) + " [PATH]"
}

func suggestFlag(input string) string {
	type candidate struct {
		flag string
		sim  float64
	}
	var candidates []candidate
	for _, fd := range flagDefs {
		sim := jaroWinkler(input, fd.long)
		if sim >= 0.7 {
			candidates = append(candidates, candidate{fd.long, sim})
		}
	}
	if len(candidates) == 0 {
		return ""
	}
	best := candidates[0]
	for _, c := range candidates[1:] {
		if c.sim >= best.sim {
			best = c
		}
	}
	return best.flag
}

func requiredExportError(seenFlags []string) *clapError {
	var parts []string
	for _, f := range seenFlags {
		fd := findLongFlag(f)
		if fd != nil {
			parts = append(parts, flagUsageStr(fd))
		}
	}
	parts = append(parts, "<--export-pdf|--export-html>")
	usage := strings.Join(parts, " ") + " [PATH]"
	return &clapError{
		msg:   "the following required arguments were not provided:\n  <--export-pdf|--export-html>",
		usage: usage,
	}
}

func checkConflicts(seenFlags []string, positionals []string) *clapError {
	hasPath := len(positionals) > 0

	var exclFlags []string
	for _, f := range seenFlags {
		if exclusiveFlags[f] {
			exclFlags = append(exclFlags, f)
		}
	}

	var expFlags []string
	for _, f := range seenFlags {
		if exportFlags[f] {
			expFlags = append(expFlags, f)
		}
	}

	// Check exclusive flag conflicts
	if len(exclFlags) > 0 {
		first := exclFlags[0]
		var conflicts []string
		for _, f := range exclFlags[1:] {
			conflicts = append(conflicts, "--"+f)
		}
		if hasPath {
			conflicts = append(conflicts, "[PATH]")
		}

		if len(conflicts) == 1 {
			return newClapErrorUsage(
				fmt.Sprintf("the argument '--%s' cannot be used with '%s'", first, conflicts[0]),
				"--"+first+" [PATH]",
			)
		} else if len(conflicts) > 1 {
			msg := fmt.Sprintf("the argument '--%s' cannot be used with:", first)
			for _, c := range conflicts {
				msg += fmt.Sprintf("\n  %s", c)
			}
			return newClapErrorUsage(msg, "--"+first+" [PATH]")
		}
	}

	// Check export flag conflicts
	if len(expFlags) > 1 {
		first := expFlags[0]
		second := expFlags[1]
		var msg string
		var usage string
		if hasPath {
			msg = fmt.Sprintf("the argument '--%s' cannot be used with '--%s'", first, second)
			usage = "--" + first + " <PATH>"
		} else {
			msg = fmt.Sprintf("the argument '--%s' cannot be used with '--%s'", first, second)
			usage = "--" + first + " [PATH]"
		}
		return newClapErrorUsage(msg, usage)
	}

	return nil
}

