	fmt.Printf("\x1b_Gf=32,a=q,t=f,i=%d,s=1,v=1;%s\x1b\\", id, pathB64)

	dataB64 := base64.StdEncoding.EncodeToString([]byte{0, 0, 0, 0})
	fmt.Printf("\x1b_Gf=32,a=q,t=d,i=%d,s=1,v=1;%s\x1b\\", id+1, dataB64)
}
