package main

import (
	"fmt"
)

func checkConflictsV2(seenFlags []string, positionals []string) *clapError {
	hasPath := len(positionals) > 0

	var exclFlags []string
	for _, f := range seenFlags {
		if exclusiveFlags[f] {
			exclFlags = append(exclFlags, f)
		}
	}

	var expFlags []string
	for _, f := range seenFlags {
		if exportFlags[f] {
			expFlags = append(expFlags, f)
		}
	}

	// Check exclusive flag conflicts
	if len(exclFlags) > 0 {
		first := exclFlags[0]
		// Build the set of conflicting targets (all exclusive flags after first + PATH if given)
		conflictTargets := map[string]bool{}
		var conflictList []string
		for _, f := range exclFlags[1:] {
			conflictTargets[f] = true
			conflictList = append(conflictList, "--"+f)
		}
		if hasPath {
			conflictList = append(conflictList, "[PATH]")
		}

		if len(conflictList) == 0 {
			// Only 1 exclusive flag, no other exclusive flags, but might conflict with path
			// This is handled below
		} else if len(conflictList) == 1 {
			usage := buildConflictUsageExcluding(seenFlags, conflictTargets)
			return newClapErrorUsage(
				fmt.Sprintf("the argument '--%s' cannot be used with '%s'", first, conflictList[0]),
				usage,
			)
		} else {
			msg := fmt.Sprintf("the argument '--%s' cannot be used with:", first)
			for _, c := range conflictList {
				msg += fmt.Sprintf("\n  %s", c)
			}
			usage := buildConflictUsageExcluding(seenFlags, conflictTargets)
			return newClapErrorUsage(msg, usage)
		}
	}

	// Check export flag conflicts
	if len(expFlags) > 1 {
		first := expFlags[0]
		second := expFlags[1]
		var msg string
		var usage string
		if hasPath {
			msg = fmt.Sprintf("the argument '--%s' cannot be used with '--%s'", first, second)
			// For export conflicts with path, usage shows only first export flag + <PATH>
			usage = "--" + first + " <PATH>"
		} else {
			msg = fmt.Sprintf("the argument '--%s' cannot be used with '--%s'", first, second)
			usage = "--" + first + " [PATH]"
		}
		return newClapErrorUsage(msg, usage)
	}

	return nil
}
