func parseFlags(args []string) (*flags, error) {
	f := &flags{
		inputFile: "input.txt",
	}
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			f.positional = append(f.positional, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") {
			// Long flag
			name := arg[2:]
			var value string
			hasValue := false
			if idx := strings.Index(name, "="); idx >= 0 {
				value = name[idx+1:]
				name = name[:idx]
				hasValue = true
			}
			err := setLongFlag(f, name, value, hasValue, &i, args)
			if err != nil {
				return nil, err
			}
			i++
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			// Short flags - can be combined
			chars := arg[1:]
			for j := 0; j < len(chars); j++ {
				c := chars[j]
				err := setShortFlag(f, c, &j, &i, args, chars)
				if err != nil {
					return nil, err
				}
			}
			i++
		} else {
			f.positional = append(f.positional, arg)
			i++
		}
	}
	return f, nil
}

