	f, err := parseFlags(os.Args[1:])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(2)
	}

	// Priority: v > u > h > s > l > c > p > e > b > t > F > editor
	if f.version {
		fmt.Printf("Orbiton %s\n", version)
		return
	}
	if f.upsie {
		upsie()
