func cacheDir() string {
	if xdg := os.Getenv("XDG_CACHE_HOME"); xdg != "" {
		return filepath.Join(xdg, "o")
	}
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".cache", "o")
}

