		Machine string
	}
	// Get kernel release and machine
	release := getUnameRelease()
	machine := getUnameMachine()
	// Short release: before first '-'
	shortRelease := release
	if idx := strings.Index(release, "-"); idx >= 0 {
		shortRelease = release[:idx]
	}

	uptime := getUptime()
	upStr := formatUptime(uptime)

	if noColor() {
		fmt.Printf("%s @ %s (%s) - Up: %s\n", hostname, shortRelease, machine, upStr)
	} else {
		fmt.Printf("\033[94m%s\033[0m \033[97m@\033[0m \033[91m%s\033[0m \033[90m(\033[0m\033[33m%s\033[0m\033[90m)\033[0m - \033[93mUp:\033[0m \033[93m%s\033[0m\n",
