	var utsname syscall.Utsname
	if err := syscall.Uname(&utsname); err == nil {
		return int8ToString(utsname.Release[:])
	}
	// Fallback
	out, err := exec.Command("uname", "-r").Output()
	if err == nil {
		return strings.TrimSpace(string(out))
	}
	return "unknown"
}

func getUnameMachine() string {
	var utsname syscall.Utsname
	if err := syscall.Uname(&utsname); err == nil {
		return int8ToString(utsname.Machine[:])
	}
	out, err := exec.Command("uname", "-m").Output()
	if err == nil {
		return strings.TrimSpace(string(out))
	}
	return "unknown"
}

func int8ToString(b []int8) string {
	var sb strings.Builder
	for _, c := range b {
		if c == 0 {
			break
		}
		sb.WriteByte(byte(c))
	}
	return sb.String()
}

func getUptime() float64 {
	// Read /proc/uptime
	data, err := os.ReadFile("/proc/uptime")
	if err == nil {
		parts := strings.Fields(string(data))
		if len(parts) > 0 {
			uptime, err := strconv.ParseFloat(parts[0], 64)
			if err == nil {
				return uptime
			}
		}
	}
	// Fallback: use syscall for uptime
	var info syscall.Sysinfo_t
	if err := syscall.Sysinfo(&info); err == nil {
		return float64(info.Uptime)
	}
	return 0
}

func formatUptime(seconds float64) string {
	totalMin := int(seconds / 60)
	minutes := totalMin % 60
	totalHours := totalMin / 60
	hours := totalHours % 24
	totalDays := totalHours / 24
	days := totalDays % 7
	weeks := totalDays / 7
	return fmt.Sprintf("%dw, %dd, %dh, %dm", weeks, days, hours, minutes)
}

func listDigraphs() {
	// Shuffle the digraphs (Go map iteration order simulation)
	rng := rand.New(rand.NewSource(time.Now().UnixNano()))
	indices := rng.Perm(len(digraphs))
	var sb strings.Builder
	for _, idx := range indices {
		d := digraphs[idx]
		// Format: XXXX XX DESCRIPTION<padding>SYMBOL
		// Description is left-justified in 54-char field
		// Symbol or "N/A" follows
		desc := d.Desc
		// Pad description to 54 chars
		if len(desc) < 54 {
			desc = desc + strings.Repeat(" ", 54-len(desc))
		}
		symbol := getSymbol(d.Codepoint)
		fmt.Fprintf(&sb, "%04X %s %s%s\n", d.Codepoint, d.Digraph, desc, symbol)
	}
	fmt.Print(sb.String())
}

func getSymbol(codepoint int) string {
	// Check if this is a non-printable/whitespace codepoint
	if isNonPrintable(codepoint) {
		return "N/A"
	}
	return string(rune(codepoint))
}

func isNonPrintable(cp int) bool {
	// Control characters
	if cp <= 0x1F {
		return true
	}
	if cp >= 0x7F && cp <= 0x9F {
		return true
	}
	// NBSP, soft hyphen
	if cp == 0xA0 || cp == 0xAD {
		return true
	}
	// Various spaces
	switch cp {
	case 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2009, 0x200A, 0x3000:
		return true
	}
	return false
}

