			endIdx := strings.Index(line[i:], "*/")
			if endIdx >= 0 {
				end := i + endIdx + 2
				text := line[i:end]
				writeColored(&sb, text, colorDarkGray, noColor)
				*inBlockComment = false
				i = end
				continue
			} else {
				// Rest of line is comment
				writeColored(&sb, line[i:], colorDarkGray, noColor)
				i = n
				continue
			}
		}

		// Check for backtick string continuation
		if *inBacktickString {
			endIdx := strings.IndexByte(line[i:], '`')
			if endIdx >= 0 {
				end := i + endIdx + 1
				text := line[i:end]
				writeColored(&sb, text, colorWhite, noColor)
