			writeColored(&sb, string(c), colorWhite, noColor)
			i++
			continue
		}

		// Red symbols (individual)
		if isRedSymbol(c) {
			writeColored(&sb, string(c), colorRed, noColor)
			i++
			continue
		}

		// Fallback (shouldn't reach here for ASCII)
		sb.WriteByte(c)
		i++
	}

	return sb.String()
}

func writeColored(sb *strings.Builder, text, color string, noColor bool) {
