// matchNumber tries to match a number starting at position i
// Returns the length of the match, or 0 if no match
func matchNumber(line string, i int) int {
	n := len(line)
	if i >= n {
		return 0
	}
	c := line[i]

	// Check for 0x, 0b, 0o prefixes
	if c == '0' && i+1 < n {
		next := line[i+1]
		if next == 'x' || next == 'X' {
			// Hex number: 0[xX][0-9a-fA-F_]*([.][0-9a-fA-F_]*)?([pP][+-]?[0-9]*)?
			return matchHexNumber(line, i)
		}
		if next == 'b' || next == 'B' {
			// Binary: 0[bB][0-9_]*
			j := i + 2
			for j < n && (isDigitChar(line[j]) || line[j] == '_') {
				j++
			}
			return j - i
		}
		if next == 'o' || next == 'O' {
			// Octal: 0[oO][0-9_]*
			j := i + 2
			for j < n && (isDigitChar(line[j]) || line[j] == '_') {
				j++
			}
			return j - i
		}
	}

	// Check for . followed by digit
	if c == '.' {
		if i+1 < n && isDigitChar(line[i+1]) {
			// .[0-9][0-9_]*([eEpP][+-]?[0-9]*)?
			return matchDecimalFromDot(line, i)
		}
		return 0
	}

	// Decimal number: [0-9][0-9_]*([.][0-9_]*)?([eEpP][+-]?[0-9]*)?
	if isDigitChar(c) {
		return matchDecimalNumber(line, i)
	}

	return 0
}

func matchHexNumber(line string, i int) int {
	n := len(line)
	j := i + 2 // skip 0x
	// Hex digits and underscores
	for j < n && (isHexChar(line[j]) || line[j] == '_') {
		j++
	}
	// Optional fractional part
	if j < n && line[j] == '.' {
		j++
		for j < n && (isHexChar(line[j]) || line[j] == '_') {
			j++
		}
	}
	// Optional exponent
	if j < n && (line[j] == 'p' || line[j] == 'P') {
		j++
		if j < n && (line[j] == '+' || line[j] == '-') {
			j++
		}
		for j < n && isDigitChar(line[j]) {
			j++
		}
	}
	return j - i
}

func matchDecimalNumber(line string, i int) int {
	n := len(line)
	j := i
	// Digits and underscores
	for j < n && (isDigitChar(line[j]) || line[j] == '_') {
		j++
	}
	// Optional fractional part
	if j < n && line[j] == '.' {
		j++
		for j < n && (isDigitChar(line[j]) || line[j] == '_') {
			j++
		}
	}
	// Optional exponent
	if j < n && (line[j] == 'e' || line[j] == 'E' || line[j] == 'p' || line[j] == 'P') {
		j++
		if j < n && (line[j] == '+' || line[j] == '-') {
			j++
		}
		for j < n && isDigitChar(line[j]) {
			j++
		}
	}
	return j - i
}

func matchDecimalFromDot(line string, i int) int {
	n := len(line)
	j := i + 1 // skip dot
	// Digits and underscores
	for j < n && (isDigitChar(line[j]) || line[j] == '_') {
		j++
	}
	// Optional exponent
	if j < n && (line[j] == 'e' || line[j] == 'E' || line[j] == 'p' || line[j] == 'P') {
		j++
		if j < n && (line[j] == '+' || line[j] == '-') {
			j++
		}
		for j < n && isDigitChar(line[j]) {
			j++
		}
	}
	return j - i
}
