			continue
		}
		// Table header
		if strings.HasPrefix(trimmed, "[") {
			// Find closing ]
			if !strings.HasSuffix(trimmed, "]") {
				lineNum++
				continue
			}
			tablePath := trimmed[1 : len(trimmed)-1]
			parts := strings.Split(tablePath, ".")
			for i := range parts {
				parts[i] = strings.TrimSpace(parts[i])
				parts[i] = strings.Trim(parts[i], "\"'")
			}
			// Navigate/create nested tables
			t := root
			for _, p := range parts {
				existing, ok := t.tbl[p]
				if !ok {
					existing = &tomlValue{typ: "table", tbl: make(map[string]*tomlValue), keys: []string{}}
					t.tbl[p] = existing
					t.keys = append(t.keys, p)
				}
				t = existing
			}
			currentTable = t
			lineNum++
			continue
		}
		// Key = value
		eqIdx := strings.Index(trimmed, "=")
		if eqIdx < 0 {
			return nil, &tomlError{line: lineNum + 1, msg: fmt.Sprintf("expected '.' or '=', but got '\\n' instead")}
		}
		key := strings.TrimSpace(trimmed[:eqIdx])
		key = strings.Trim(key, "\"'")
		valStr := strings.TrimSpace(trimmed[eqIdx+1:])
		// Remove trailing comment
		valStr = stripTOMLComment(valStr)
		val, consumed, err := parseTOMLValue(valStr, lineNum+1, key)
		if err != nil {
			return nil, err
		}
		_ = consumed
		currentTable.tbl[key] = val
		currentTable.keys = append(currentTable.keys, key)
		lineNum++
	}
	return root, nil
}

func stripTOMLValue(s string) string {
	return strings.TrimSpace(s)
}

func stripTOMLComment(s string) string {
	// Don't strip inside strings
	inStr := false
	var quote byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inStr {
			if c == '\\' && i+1 < len(s) {
				i++
				continue
			}
			if c == quote {
				inStr = false
			}
		} else {
			if c == '"' || c == '\'' {
				inStr = true
				quote = c
			} else if c == '#' {
				return strings.TrimSpace(s[:i])
			}
		}
	}
	return strings.TrimSpace(s)
}

func parseTOMLValue(s string, line int, lastKey string) (*tomlValue, int, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, 0, &tomlError{line: line, lastKey: lastKey, msg: "expected value but found '\\n' instead"}
	}
	c := s[0]
	switch {
	case c == '"' || c == '\'':
		// String
		quote := c
		end := 1
		for end < len(s) {
			if s[end] == '\\' && quote == '"' && end+1 < len(s) {
				end += 2
				continue
			}
			if s[end] == quote {
				break
			}
			end++
		}
		if end >= len(s) {
			return nil, 0, &tomlError{line: line, lastKey: lastKey, msg: "unterminated string"}
		}
		str := s[1:end]
		if quote == '"' {
			str = unescapeTOMLString(str)
		}
		return &tomlValue{typ: "string", str: str}, end + 1, nil
	case c == 't' || c == 'f':
		if strings.HasPrefix(s, "true") {
			return &tomlValue{typ: "bool", bul: true}, 4, nil
		}
		if strings.HasPrefix(s, "false") {
			return &tomlValue{typ: "bool", bul: false}, 5, nil
		}
		return nil, 0, &tomlError{line: line, lastKey: lastKey, msg: fmt.Sprintf("expected value but found %q instead", s)}
	case c == '-' || c == '+' || (c >= '0' && c <= '9'):
		// Number or date
		end := 0
		for end < len(s) && (s[end] == '-' || s[end] == '+' || s[end] == '.' || s[end] == '_' || (s[end] >= '0' && s[end] <= '9') || s[end] == 'T' || s[end] == ':' || s[end] == 'Z' || s[end] == 'e' || s[end] == 'E') {
			end++
		}
		numStr := s[:end]
		numStr = strings.ReplaceAll(numStr, "_", "")
		if strings.Contains(numStr, ".") || strings.ContainsAny(numStr, "eE") {
			return &tomlValue{typ: "float", num: numStr}, end, nil
		}
		return &tomlValue{typ: "int", num: numStr}, end, nil
	case c == '[':
		// Array
		arr := []tomlValue{}
		i := 1
		for i < len(s) {
			for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
				i++
			}
			if i < len(s) && s[i] == ']' {
				i++
				break
			}
			val, consumed, err := parseTOMLValue(s[i:], line, lastKey)
			if err != nil {
				return nil, 0, err
			}
			arr = append(arr, *val)
			i += consumed
			for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
				i++
			}
			if i < len(s) && s[i] == ',' {
				i++
			}
		}
		return &tomlValue{typ: "array", arr: arr}, 0, nil
	case c == '{':
		// Inline table
		tbl := make(map[string]*tomlValue)
		var keys []string
		i := 1
		for i < len(s) {
			for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
				i++
			}
			if i < len(s) && s[i] == '}' {
				i++
				break
			}
			// Parse key
			keyStart := i
			for i < len(s) && s[i] != '=' && s[i] != ' ' {
				i++
			}
			k := s[keyStart:i]
			k = strings.Trim(k, "\"'")
			for i < len(s) && s[i] != '=' {
				i++
			}
			i++ // skip =
			val, consumed, err := parseTOMLValue(s[i:], line, k)
			if err != nil {
				return nil, 0, err
			}
			tbl[k] = val
			keys = append(keys, k)
			i += consumed
			for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
				i++
			}
			if i < len(s) && s[i] == ',' {
				i++
			}
		}
		return &tomlValue{typ: "table", tbl: tbl, keys: keys}, 0, nil
	default:
		return nil, 0, &tomlError{line: line, lastKey: lastKey, msg: fmt.Sprintf("expected value but found %q instead", s)}
	}
}

func unescapeTOMLString(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			switch s[i+1] {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			default:
				sb.WriteByte(s[i])
				sb.WriteByte(s[i+1])
			}
			i++
		} else {
			sb.WriteByte(s[i])
		}
	}
	return sb.String()
}

func encodeTOML(root *tomlValue) string {
	var sb strings.Builder
	encodeTOMLTable(root, "", &sb)
	return sb.String()
}

func encodeTOMLTable(t *tomlValue, prefix string, sb *strings.Builder) {
	// First write non-table keys
	var nonTableKeys, tableKeys []string
	for _, k := range t.keys {
		v := t.tbl[k]
		if v.typ == "table" {
			tableKeys = append(tableKeys, k)
		} else {
			nonTableKeys = append(nonTableKeys, k)
		}
	}
	// Sort keys? Let me check the original output - it seems to preserve order
	for _, k := range nonTableKeys {
		v := t.tbl[k]
		sb.WriteString(fmt.Sprintf("%s%s = %s\n", prefix, k, encodeTOMLValue(v)))
	}
	for _, k := range tableKeys {
		v := t.tbl[k]
		if prefix != "" || sb.Len() > 0 {
			sb.WriteString("\n")
		}
		sb.WriteString(fmt.Sprintf("[%s%s]\n", getTablePath(prefix, k), ""))
		encodeTOMLTable(v, "  "+prefix, sb)
	}
}

func getTablePath(prefix, key string) string {
	if prefix != "" {
		return strings.TrimSpace(prefix) + "." + key
	}
	return key
}

func encodeTOMLValue(v *tomlValue) string {
	switch v.typ {
	case "string":
		return strconv.Quote(v.str)
	case "int":
		return v.num
	case "float":
		return v.num
	case "bool":
		if v.bul {
			return "true"
		}
		return "false"
	case "array":
		parts := make([]string, len(v.arr))
		for i, item := range v.arr {
			parts[i] = encodeTOMLValue(&item)
		}
		return "[" + strings.Join(parts, ", ") + "]"
	default:
		return ""
	}
}
