{"name": "bash", "arguments": {"command": "cat <<'EOF' > main.go
package main

import (
	"bytes"
	"flag"
	"fmt"
	"log"
	"os"
	"os/exec"
	"strings"
	"time"
)

const version = "0.0.12"

// Config holds all configuration for the kick workflow.
type Config struct {
	Debug    bool
	Nonce    bool
	FetchAll bool
	PullAll  bool
	PushAll  bool
	SyncTags bool
	Message  string
	Remotes  []string
}

func envBool(key string, def bool) bool {
	val, ok := os.LookupEnv(key)
	if !ok {
		return def
	}
	return val == "1"
}

func envString(key, def string) string {
	val, ok := os.LookupEnv(key)
	if !ok {
		return def
	}
	return val
}

func main() {
	debugFlag := flag.Bool("debug", false, "Enable additional logging")
	helpFlag := flag.Bool("help", false, "Show usage menu")
	versionFlag := flag.Bool("version", false, "Show version banner")
	flag.Parse()

	if *versionFlag {
		fmt.Print(version)
		os.Exit(0)
	}

	if *helpFlag {
		exe, _ := os.Executable()
		fmt.Printf("Usage: %s [OPTIONS]\n", exe)
		flag.PrintDefaults()
		os.Exit(0)
	}

	config := Config{
		Debug:    *debugFlag,
		Nonce:    envBool("KICK_NONCE", false),
		FetchAll: true,
		PullAll:  envBool("KICK_PULL_ALL", true),
		PushAll:  envBool("KICK_PUSH_ALL", true),
		SyncTags: envBool("KICK_SYNC_TAGS", true),
		Message:  envString("KICK_MESSAGE", "up"),
		Remotes:  []string{},
	}

	if config.Debug {
		log.Printf("config: %v", config)
	}

	gitPath, lookErr := exec.LookPath("git")
	if lookErr != nil {
		gitPath = "git"
	}

	logCmd := func(args ...string) {
		if config.Debug {
			log.Printf("cmd: %s %s", gitPath, strings.Join(args, " "))
		}
	}

	runGit := func(args ...string) error {
		logCmd(args...)
		cmd := exec.Command(gitPath, args...)
		if config.Debug {
			cmd.Stdout = os.Stdout
			cmd.Stderr = os.Stderr
		}
		return cmd.Run()
	}

	fatal := func(err error) {
		if config.Debug {
			log.Print(err)
		} else {
			log.Print("git crashed, enable -debug to diagnose")
		}
		os.Exit(1)
	}

	runGitFatal := func(args ...string) {
		if err := runGit(args...); err != nil {
			fatal(err)
		}
	}

	// Step 1: discover remotes via "git remote"
	logCmd("remote")
	remoteCmd := exec.Command(gitPath, "remote")
	var remoteStdout bytes.Buffer
	remoteCmd.Stdout = &remoteStdout
	remoteCmd.Stderr = os.Stderr
	if err := remoteCmd.Run(); err != nil {
		fatal(err)
	}
	config.Remotes = strings.Fields(remoteStdout.String())

	// Step 2: write nonce file if enabled
	if config.Nonce {
		ts := time.Now().UTC().Format(time.RFC3339)
		os.WriteFile(".kick", []byte(ts), 0644)
	}

	// Step 3: stage all changes
	runGitFatal("add", ".")

	// Step 4: commit (errors are non-fatal)
	var commitArgs []string
	if config.Message == "" {
		commitArgs = []string{"commit", "-a"}
	} else {
		commitArgs = []string{"commit", "-a", "-m", config.Message}
	}
	if err := runGit(commitArgs...); err != nil && config.Debug {
		log.Print(err)
	}

	// Step 5: pull
	if config.PullAll {
		runGitFatal("pull", "--all")
	} else {
		runGitFatal("pull")
	}

	// Step 6: push
	if config.PushAll {
		runGitFatal("push", "--all")
	} else {
		runGitFatal("push")
	}

	// Step 7: sync tags
	if config.SyncTags {
		runGitFatal("fetch", "--tags", "--all")

		if config.PushAll {
			for _, remote := range config.Remotes {
				runGitFatal("push", remote, "--tags")
			}
		} else {
			runGitFatal("push", "--tags")
		}
	}
}
EOF"}}

