{"name": "bash", "arguments": {"command": "cd /workspace && cat > command.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"strings"
)

// Flag describes a command-line flag.
type Flag struct {
	Short    string // single char, or ""
	Long     string
	Kind     string // "bool" or "string"
	Default  string
	Desc     string
	Value    string
	BoolVal  bool
	Provided bool
}

func (f *Flag) Spec() string {
	if f.Short != "" {
		return "-" + f.Short + " --" + f.Long
	}
	return "--" + f.Long
}

// Command describes a CLI command.
type Command struct {
	Name        string
	Short       string
	Long        string
	Example     string
	UseLine     string // full usage line after "toney" e.g. "note create [--flags]"
	ListSuffix  string // suffix in parent's command list
	Flags       []*Flag
	Args        string // "noargs","exact1","arbitrary"
	HasRun      bool
	Hidden      bool
	Subcommands []*Command
	parent      *Command
	Run         func(c *Command, args []string, flags map[string]*Flag) int
}

func (c *Command) Path() string {
	parts := []string{}
	for x := c; x != nil; x = x.parent {
		parts = append([]string{x.Name}, parts...)
	}
	return strings.Join(parts, " ")
}

func (c *Command) FindSub(name string) *Command {
	for _, s := range c.Subcommands {
		if s.Name == name {
			return s
		}
	}
	return nil
}

// allFlags returns user flags + auto help flag (+ version for root), sorted by long name.
func (c *Command) allFlags() []*Flag {
	out := append([]*Flag{}, c.Flags...)
	// auto help
	out = append(out, &Flag{Short: "h", Long: "help", Kind: "bool", Desc: "Help for " + c.Name})
	if c.parent == nil {
		// root: version flag
		out = append(out, &Flag{Short: "v", Long: "version", Kind: "bool", Desc: "Version for " + c.Name})
	}
	// sort by long name
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j].Long < out[j-1].Long; j-- {
			out[j], out[j-1] = out[j-1], out[j]
		}
	}
	return out
}

func (c *Command) hasSubCommands() bool {
	for _, s := range c.Subcommands {
		if !s.Hidden {
			return true
		}
	}
	return false
}

// hasUserFlags: any flag besides auto help (and version)
func (c *Command) hasUserFlags() bool {
	return len(c.Flags) > 0
}

func (c *Command) Desc() string {
	if c.Long != "" {
		return c.Long
	}
	return c.Short
}

// flagByName lookup including auto flags
func (c *Command) flagByLong(name string) *Flag {
	for _, f := range c.Flags {
		if f.Long == name {
			return f
		}
	}
	if name == "help" {
		return &Flag{Short: "h", Long: "help", Kind: "bool"}
	}
	if c.parent == nil && name == "version" {
		return &Flag{Short: "v", Long: "version", Kind: "bool"}
	}
	return nil
}

func (c *Command) flagByShort(ch string) *Flag {
	for _, f := range c.Flags {
		if f.Short == ch {
			return f
		}
	}
	if ch == "h" {
		return &Flag{Short: "h", Long: "help", Kind: "bool"}
	}
	if c.parent == nil && ch == "v" {
		return &Flag{Short: "v", Long: "version", Kind: "bool"}
	}
	return nil
}

// parseFlags parses args, returning positional args and a flag map.
// Returns error like pflag.
func (c *Command) parseFlags(args []string) ([]string, map[string]*Flag, error) {
	flags := map[string]*Flag{}
	for _, f := range c.Flags {
		nf := *f
		flags[f.Long] = &nf
	}
	var positional []string
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			positional = append(positional, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") {
			name := arg[2:]
			val := ""
			hasVal := false
			if idx := strings.Index(name, "="); idx >= 0 {
				val = name[idx+1:]
				name = name[:idx]
				hasVal = true
			}
			f := c.flagByLong(name)
			if f == nil {
				return nil, nil, fmt.Errorf("unknown flag: --%s", name)
			}
			if f.Kind == "bool" {
				if hasVal {
					b := val == "true" || val == "1"
					setFlag(flags, f, b, "")
				} else {
					setFlag(flags, f, true, "")
				}
			} else {
				if hasVal {
					setFlag(flags, f, false, val)
				} else {
					if i+1 >= len(args) {
						return nil, nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					i++
					setFlag(flags, f, false, args[i])
				}
			}
			i++
			continue
		}
		if len(arg) > 1 && arg[0] == '-' {
			// short flags, possibly combined
			rest := arg[1:]
			for k := 0; k < len(rest); k++ {
				ch := string(rest[k])
				f := c.flagByShort(ch)
				if f == nil {
					return nil, nil, fmt.Errorf("unknown shorthand flag: %q in -%s", ch, rest)
				}
				if f.Kind == "bool" {
					setFlag(flags, f, true, "")
					continue
				}
				// string flag: consume rest of arg or next arg
				if k+1 < len(rest) {
					val := rest[k+1:]
					setFlag(flags, f, false, val)
					k = len(rest) // done
				} else {
					if i+1 >= len(args) {
						return nil, nil, fmt.Errorf("flag needs an argument: %q in -%s", ch, rest)
					}
					i++
					setFlag(flags, f, false, args[i])
				}
			}
			i++
			continue
		}
		positional = append(positional, arg)
		i++
	}
	return positional, flags, nil
}

func setFlag(m map[string]*Flag, f *Flag, b bool, s string) {
	existing := m[f.Long]
	if existing == nil {
		existing = &Flag{}
		m[f.Long] = existing
	}
	existing.Long = f.Long
	existing.Short = f.Short
	existing.Kind = f.Kind
	existing.BoolVal = b
	existing.Value = s
	existing.Provided = true
}

// helpRequested checks if help/version flags were set
func helpRequested(flags map[string]*Flag) bool {
	if f, ok := flags["help"]; ok && f.BoolVal {
		return true
	}
	return false
}

func versionRequested(flags map[string]*Flag) bool {
	if f, ok := flags["version"]; ok && f.BoolVal {
		return true
	}
	return false
}

// validateArgs checks arg count constraints.
func (c *Command) validateArgs(args []string) error {
	switch c.Args {
	case "noargs":
		if len(args) > 0 {
			return fmt.Errorf("unknown command %q for %q", args[0], c.Path())
		}
	case "exact1":
		if len(args) != 1 {
			return fmt.Errorf("accepts 1 arg(s), received %d", len(args))
		}
	}
	return nil
}

// dispatch executes the command tree.
func (root *Command) Execute() int {
	args := os.Args[1:]
	cmd, cargs, err := root.traverse(args)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 0
	}
	// parse flags on the resolved command
	pos, flags, perr := cmd.parseFlags(cargs)
	if perr != nil {
		fmt.Fprintln(os.Stderr, perr)
		return 0
	}
	if helpRequested(flags) {
		fmt.Print(renderHelp(cmd))
		return 0
	}
	if cmd.parent == nil && versionRequested(flags) {
		fmt.Println("toney version unknown (built from source)")
		return 0
	}
	// validate args
	if verr := cmd.validateArgs(pos); verr != nil {
		fmt.Fprintln(os.Stderr, verr)
		return 0
	}
	if !cmd.HasRun {
		// parent command with no run: show help
		fmt.Print(renderHelp(cmd))
		return 0
	}
	return cmd.Run(cmd, pos, flags)
}

// traverse walks the command tree consuming subcommand names.
func (root *Command) traverse(args []string) (*Command, []string, error) {
	cmd := root
	rest := args
	for {
		// find first non-flag token to check for subcommand
		idx := -1
		for i, a := range rest {
			if a == "--" {
				break
			}
			if len(a) > 0 && a[0] == '-' {
				// skip flag and possibly its value
				continue
			}
			idx = i
			break
		}
		if idx < 0 {
			return cmd, rest, nil
		}
		sub := cmd.FindSub(rest[idx])
		if sub == nil {
			// not a subcommand
			if cmd.hasSubCommands() && !cmd.HasRun {
				// parent with no run: show help (ignore the unknown arg)
				return cmd, rest, nil
			}
			if cmd.Args == "noargs" {
				return cmd, rest, nil // let validateArgs handle
			}
			return cmd, rest, nil
		}
		// consume subcommand token
		rest = append(append([]string{}, rest[:idx]...), rest[idx+1:]...)
		cmd = sub
	}
}
