package main

import (
	"os"
	"strings"
	"syscall"
	"unsafe"
)

type winsize struct {
	Row, Col, X, Y uint16
}

func termWidth() int {
	ws := &winsize{}
	fd := os.Stdout.Fd()
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
	if errno != 0 {
		return 0
	}
	return int(ws.Col)
}

func helpWidth() int {
	w := termWidth()
	if w == 0 || w > 120 {
		w = 120
	}
	return w
}

func padRight(s string, w int) string {
	if len(s) >= w {
		return s
	}
	return s + strings.Repeat(" ", w-len(s))
}

func centerString(s string, w int) string {
	if len(s) >= w {
		return s
	}
	total := w - len(s)
	left := total / 2
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", total-left)
}

// writeHeader writes a 3-line header block: blank, "  TITLE  ", blank (each width = len(title)+4)
func writeHeader(b *strings.Builder, title string) {
	w := len(title) + 4
	b.WriteString(strings.Repeat(" ", w))
	b.WriteString("\n")
	b.WriteString("  " + title + "  ")
	b.WriteString("\n")
	b.WriteString(strings.Repeat(" ", w))
	b.WriteString("\n")
}

// sharedColWidth: max(maxSubName, maxFlagSpec)+2
func sharedColWidth(c *Command) int {
	maxw := 0
	for _, s := range c.Subcommands {
		if s.Hidden {
			continue
		}
		n := len(s.Name + s.ListSuffix)
		if n > maxw {
			maxw = n
		}
	}
	for _, f := range c.allFlags() {
		n := len(f.Spec())
		if n > maxw {
			maxw = n
		}
	}
	return maxw + 2
}

func renderHelp(c *Command) string {
	width := helpWidth()
	var b strings.Builder
	b.WriteString("\n")
	// Description block
	desc := c.Desc()
	for _, line := range strings.Split(desc, "\n") {
		b.WriteString(padRight("  "+line, width))
		b.WriteString("\n")
	}
	// USAGE header
	writeHeader(&b, "USAGE")
	// usage line + examples
	usageLine := "    " + c.UseLine + "  "
	var exLines []string
	if c.Example != "" {
		for _, l := range strings.Split(c.Example, "\n") {
			exLines = append(exLines, "    "+l+"  ")
		}
	}
	w1 := len(usageLine)
	for _, l := range exLines {
		if len(l) > w1 {
			w1 = len(l)
		}
	}
	b.WriteString(padRight(usageLine, w1))
	b.WriteString("\n")
	if len(exLines) > 0 {
		writeHeader(&b, "EXAMPLES")
		for _, l := range exLines {
			b.WriteString(padRight(l, w1))
			b.WriteString("\n")
		}
	}
	// COMMANDS
	if c.hasSubCommands() {
		writeHeader(&b, "COMMANDS")
		colW := sharedColWidth(c)
		for _, s := range c.Subcommands {
			if s.Hidden {
				continue
			}
			name := s.Name + s.ListSuffix
			b.WriteString("    " + padRight(name, colW-2) + "  " + s.Short + "\n")
		}
	}
	// FLAGS
	writeHeader(&b, "FLAGS")
	colW := sharedColWidth(c)
	for _, f := range c.allFlags() {
		b.WriteString("    " + padRight(f.Spec(), colW-2) + "  " + f.Desc + "\n")
	}
	b.WriteString("\n")
	return b.String()
}
GOEOF
echo "help.go written"; go build ./... 2>&1 | head"}}

