{"name": "bash", "arguments": {"command": "cd /workspace && cat > config.go <<'GOEOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func homeDir() string {
	h, err := os.UserHomeDir()
	if err != nil || h == "" {
		if e := os.Getenv("HOME"); e != "" {
			return e
		}
	}
	return h
}

func configDir() string  { return filepath.Join(homeDir(), ".config", "toney") }
func configFile() string { return filepath.Join(configDir(), "config.toml") }
func notesDir() string   { return filepath.Join(homeDir(), ".toney") }
func dailyDir() string   { return filepath.Join(notesDir(), ".daily") }

// Config holds the parsed config values we care about.
type Config struct {
	Editor []string
}

var defaultEditor = []string{"nvim"}

// loadConfig ensures the config file exists and parses it. Returns config and error.
// Error format mimics viper: "failed to read config: While parsing config: toml: <msg>"
func loadConfig() (*Config, error) {
	// ensure dir + file exist
	if err := os.MkdirAll(configDir(), 0755); err != nil {
		// best effort
	}
	if _, err := os.Stat(configFile()); os.IsNotExist(err) {
		f, ferr := os.Create(configFile())
		if ferr == nil {
			f.Close()
		}
	}
	data, err := os.ReadFile(configFile())
	if err != nil {
		return nil, fmt.Errorf("failed to read config: While parsing config: %v", err)
	}
	tree, perr := parseToml(string(data))
	if perr != nil {
		return nil, fmt.Errorf("failed to read config: While parsing config: toml: %s", perr.Error())
	}
	cfg := &Config{Editor: defaultEditor}
	if g, ok := tree.tables["General"]; ok {
		if v, ok := g.values["Editor"]; ok {
			if arr, ok := v.([]string); ok {
				cfg.Editor = arr
			}
		}
	}
	return cfg, nil
}

// subcommandConfigError prints the config error to stderr and returns true if config failed.
func subcommandConfigError() (*Config, bool) {
	cfg, err := loadConfig()
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to load config: %v\n\nTry running the `toney init` command and try again.\n", err)
		return nil, true
	}
	return cfg, false
}

// ---------- minimal TOML parser ----------

type tomlTable struct {
	tables map[string]*tomlTable
	values map[string]interface{}
}

func newTomlTable() *tomlTable {
	return &tomlTable{tables: map[string]*tomlTable{}, values: map[string]interface{}{}}
}

func parseToml(s string) (*tomlTable, error) {
	root := newTomlTable()
	current := root
	lines := strings.Split(s, "\n")
	for li := 0; li < len(lines); li++ {
		line := lines[li]
		// strip comment (basic, not handling # in strings perfectly)
		raw := line
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		// table header
		if strings.HasPrefix(trimmed, "[") {
			if !strings.HasSuffix(trimmed, "]") {
				return nil, fmt.Errorf("expected character =")
			}
			name := strings.TrimSpace(trimmed[1 : len(trimmed)-1])
			parts := strings.Split(name, ".")
			t := root
			for i, p := range parts {
				p = strings.TrimSpace(p)
				key := unquoteKey(p)
				existing, ok := t.values[key]
				if ok {
					_ = existing
					return nil, fmt.Errorf("key %s should be a table, not a value", key)
				}
				nt, ok := t.tables[key]
				if !ok {
					nt = newTomlTable()
					t.tables[key] = nt
				}
				t = nt
				_ = i
			}
			// check conflict: if this path was already a value
			current = t
			continue
		}
		// key = value
		idx := strings.Index(trimmed, "=")
		if idx < 0 {
			return nil, fmt.Errorf("expected character =")
		}
		key := strings.TrimSpace(trimmed[:idx])
		key = unquoteKey(key)
		valstr := strings.TrimSpace(trimmed[idx+1:])
		val, err := parseTomlValue(valstr)
		if err != nil {
			return nil, err
		}
		if _, ok := current.tables[key]; ok {
			return nil, fmt.Errorf("key %s should be a table, not a value", key)
		}
		current.values[key] = val
	}
	return root, nil
}

func unquoteKey(k string) string {
	k = strings.TrimSpace(k)
	if len(k) >= 2 && (k[0] == '\'' || k[0] == '"') && k[len(k)-1] == k[0] {
		return k[1 : len(k)-1]
	}
	return k
}

func parseTomlValue(s string) (interface{}, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil, fmt.Errorf("expected character =")
	}
	if s[0] == '[' {
		// array
		if !strings.HasSuffix(s, "]") {
			return nil, fmt.Errorf("unterminated array")
		}
		inner := strings.TrimSpace(s[1 : len(s)-1])
		var items []string
		if inner != "" {
			parts := splitArray(inner)
			for _, p := range parts {
				p = strings.TrimSpace(p)
				v, err := parseTomlScalar(p)
				if err != nil {
					return nil, err
				}
				items = append(items, v)
			}
		}
		return items, nil
	}
	return parseTomlScalar(s)
}

func splitArray(s string) []string {
	var parts []string
	depth := 0
	inStr := false
	q := byte(0)
	last := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if inStr {
			if c == q {
				inStr = false
			}
			continue
		}
		switch c {
		case '\'', '"':
			inStr = true
			q = c
		case '[':
			depth++
		case ']':
			depth--
		case ',':
			if depth == 0 {
				parts = append(parts, s[last:i])
				last = i + 1
			}
		}
	}
	parts = append(parts, s[last:])
	return parts
}

func parseTomlScalar(s string) (string, error) {
	s = strings.TrimSpace(s)
	if len(s) >= 2 && s[0] == '\'' && s[len(s)-1] == '\'' {
		return s[1 : len(s)-1], nil
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		return unescapeToml(s[1 : len(s)-1]), nil
	}
	// bare scalar (bool/number) - return as string for our purposes
	return s, nil
}

func unescapeToml(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			i++
			switch s[i] {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case '"':
