// defaultUsage produces cobra's default usage template for the root command.
func defaultUsage(root *Command) string {
	var b strings.Builder
	b.WriteString("Usage:\n")
	b.WriteString("  toney\n")
	b.WriteString("  toney [command]\n")
	b.WriteString("\n")
	b.WriteString("Available Commands:\n")
	// list non-hidden subcommands sorted by name
	subs := []*Command{}
	for _, s := range root.Subcommands {
		if !s.Hidden {
			subs = append(subs, s)
		}
	}
	// sort
	for i := 1; i < len(subs); i++ {
		for j := i; j > 0 && subs[j].Name < subs[j-1].Name; j-- {
			subs[j], subs[j-1] = subs[j-1], subs[j]
		}
	}
	// padding = max name len + 1
	maxn := 0
	for _, s := range subs {
		if len(s.Name) > maxn {
			maxn = len(s.Name)
		}
	}
	pad := maxn + 1
	for _, s := range subs {
		name := s.Name
		if len(name) < pad {
			name += strings.Repeat(" ", pad-len(name))
		}
		b.WriteString("  " + name + " " + s.Short + "\n")
	}
	b.WriteString("\n")
	b.WriteString("Use \"toney [command] --help\" for more information about a command.\n")
	return b.String()
}
