package main

import (
	"strings"
)

func alignLeft(s string, w int) string {
	if len(s) >= w {
		return s
	}
	return s + strings.Repeat(" ", w-len(s))
}

func alignCenter(s string, w int) string {
	if len(s) >= w {
		return s
	}
	total := w - len(s)
	left := total / 2
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", total-left)
}

func padCell(content string, width int, centered bool, padding int) string {
	var inner string
	if centered {
		inner = alignCenter(content, width)
	} else {
		inner = alignLeft(content, width)
	}
	if padding > 0 {
		return strings.Repeat(" ", padding) + inner + strings.Repeat(" ", padding)
	}
	return inner
}

// renderTable renders a lipgloss-style rounded table.
func renderTable(headers []string, rows [][]string) string {
	ncols := len(headers)
	colWidths := make([]int, ncols)
	for i, h := range headers {
		colWidths[i] = len(h)
	}
	for _, r := range rows {
		for i := 0; i < ncols && i < len(r); i++ {
			if w := len(r[i]); w > colWidths[i] {
				colWidths[i] = w
			}
		}
	}
	padding := 1
	if len(rows) == 0 {
		padding = 0
	}
	fullW := make([]int, ncols)
	for i := range colWidths {
		fullW[i] = colWidths[i] + 2*padding
	}
	hline := func(jointL, joint, jointR string) string {
		var b strings.Builder
		b.WriteString(jointL)
		for i, w := range fullW {
			if i > 0 {
				b.WriteString(joint)
			}
			b.WriteString(strings.Repeat("─", w))
		}
		b.WriteString(jointR)
		return b.String()
	}
	var b strings.Builder
	b.WriteString(hline("╭", "┬", "╮"))
	b.WriteString("\n")
	// header row
	b.WriteString("│")
	for i, h := range headers {
		b.WriteString(padCell(h, colWidths[i], true, padding))
		b.WriteString("│")
	}
	b.WriteString("\n")
	b.WriteString(hline("├", "┼", "┤"))
	b.WriteString("\n")
	for _, r := range rows {
		b.WriteString("│")
		for i := 0; i < ncols; i++ {
			val := ""
			if i < len(r) {
				val = r[i]
			}
			b.WriteString(padCell(val, colWidths[i], false, padding))
			b.WriteString("│")
		}
		b.WriteString("\n")
	}
	b.WriteString(hline("╰", "┴", "╯"))
	b.WriteString("\n")
	return b.String()
}
GOEOF
