}

type noteEntry struct {
	name string
	mod  time.Time
	size int64
}

func runNoteList(c *Command, args []string, flags map[string]*Flag) int {
	if _, fail := subcommandConfigError(); fail {
		return 0
	}
	base := notesDir()
	if p := flagStr(flags, "path"); p != "" {
		base = filepath.Join(notesDir(), p)
	}
	all := flagBool(flags, "all")
	search := flagStr(flags, "search")
	var entries []noteEntry
	walkFiles(base, "", all, func(rel string, info os.FileInfo) {
		ename := rel
		if search != "" {
			if !fuzzyMatch(ename, search) {
				return
			}
		}
		entries = append(entries, noteEntry{name: ename, mod: info.ModTime(), size: info.Size()})
	})
	if entries == nil {
		// log.Fatal style for missing dir
		if fi, err := os.Stat(base); err != nil || !fi.IsDir() {
			logFatalf("failed to read notes directory (%s) : %v", base, err)
		}
	}
	headers := []string{"Filename", "Updated", "Size"}
	var rows [][]string
	for _, e := range entries {
		rows = append(rows, []string{e.name, e.mod.Format("02 Jan"), strconv.FormatInt(e.size, 10) + "Kb"})
	}
	fmt.Print(renderTable(headers, rows))
	return 0
}

// walkFiles walks dir, calling fn with paths relative to root base.
func walkFiles(base, rel string, all bool, fn func(string, os.FileInfo)) {
	full := base
	if rel != "" {
		full = filepath.Join(base, rel)
	}
	f, err := os.Open(full)
	if err != nil {
		return
	}
	entries, _ := f.ReadDir(-1)
	f.Close()
	// sort by name for determinism (original uses readdir order which is nondeterministic)
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
	for _, e := range entries {
		name := e.Name()
		childRel := name
		if rel != "" {
			childRel = rel + "/" + name
		}
		if e.IsDir() {
			if !all && strings.HasPrefix(name, ".") {
				continue
			}
			walkFiles(base, childRel, all, fn)
		} else {
			info, err := e.Info()
			if err != nil {
				continue
			}
			fn(childRel, info)
		}
	}
}

// fuzzyMatch returns true if query is a subsequence of s (case-sensitive).
func fuzzyMatch(s, query string) bool {
	if query == "" {
		return true
	}
	i := 0
	for j := 0; j < len(s) && i < len(query); j++ {
		if s[j] == query[i] {
			i++
		}
	}
	return i == len(query)
}
