package main

import (
	"strconv"
	"strings"
	"unicode/utf8"
)

func visWidth(s string) int {
	return utf8.RuneCountInString(s)
}

// truncatePad truncates s to W visual columns (using … if truncated) or pads with spaces.
func truncatePad(s string, W int) string {
	if visWidth(s) <= W {
		return s + strings.Repeat(" ", W-visWidth(s))
	}
	// truncate to W-1 runes + …
	runes := []rune(s)
	trunc := string(runes[:W-1])
	return trunc + "…"
}

var statusIcon = map[int]string{0: "~", 1: "○", 2: "×", 3: "✓"}
var statusPriority = map[int]int{0: 1, 1: 0, 2: 2, 3: 3}

func priorityOf(status int) int {
	if p, ok := statusPriority[status]; ok {
		return p
	}
	return status
}

type task struct {
	title  string
	desc   string
	status int
}

func iconFor(status int) string {
	if ic, ok := statusIcon[status]; ok {
		return ic
	}
	return ""
}

// renderTasks renders the task list. verbose controls desc display.
func renderTasks(tasks []task, verbose bool) string {
	if len(tasks) == 0 {
		return "\n\nNo items.\n\n"
	}
	W := 45
	if verbose {
		W = 65
	}
	// sort stable by priority
	idx := make([]int, len(tasks))
	for i := range idx {
		idx[i] = i
	}
	// stable sort
	for i := 1; i < len(idx); i++ {
		for j := i; j > 0; j-- {
			if priorityOf(tasks[idx[j]].status) < priorityOf(tasks[idx[j-1]].status) {
				idx[j], idx[j-1] = idx[j-1], idx[j]
			} else {
				break
			}
		}
	}
	var b strings.Builder
	b.WriteString("\n\n")
	for n, i := range idx {
		t := tasks[i]
		num := strconv.Itoa(n + 1)
		icon := iconFor(t.status)
		prefix := "   " + num + ". " + icon + " | "
		titleLine := truncatePad(prefix+t.title, W)
		b.WriteString(titleLine)
		b.WriteString("\n")
		if verbose {
			descLine := truncatePad(strings.Repeat(" ", visWidth(prefix))+t.desc, W)
			b.WriteString(descLine)
			b.WriteString("\n")
		}
		b.WriteString(strings.Repeat(" ", W))
		b.WriteString("\n")
	}
	b.WriteString("\n")
	return b.String()
}
