func readTasks(path string) ([]task, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDONLY, 0644)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	r := csv.NewReader(f)
	records, err := r.ReadAll()
	if err != nil {
		if err == io.EOF {
			return nil, nil
		}
		return nil, err
	}
	var tasks []task
	for i, rec := range records {
		if i == 0 {
			continue
		}
		if len(rec) < 3 {
			continue
		}
		st, _ := strconv.Atoi(rec[2])
		tasks = append(tasks, task{title: rec[0], desc: rec[1], status: st})
	}
	return tasks, nil
}

func writeTasks(path string, tasks []task) error {
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()
	w := csv.NewWriter(f)
	w.UseCRLF = false
	w.Write([]string{"title", "desc", "status"})
	for _, t := range tasks {
		w.Write([]string{t.title, t.desc, strconv.Itoa(t.status)})
	}
	w.Flush()
	return nil
}

