import struct, zlib, sys

def make_png(path, width, height, pixel_func):
    raw = bytearray()
    for y in range(height):
        raw.append(0)
        for x in range(width):
            r, g, b = pixel_func(x, y)
            raw += bytes([r, g, b])
    compressed = zlib.compress(bytes(raw))
    def chunk(ctype, data):
        c = ctype + data
        crc = struct.pack(">I", zlib.crc32(c) & 0xffffffff)
        return struct.pack(">I", len(data)) + c + crc
    sig = b'\x89PNG\r\n\x1a\n'
    ihdr = struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0)
    png = sig + chunk(b'IHDR', ihdr) + chunk(b'IDAT', compressed) + chunk(b'IEND', b'')
    with open(path, 'wb') as f:
        f.write(png)

if __name__ == "__main__":
    # args: prefix npages variant
    prefix = sys.argv[1]
    npages = int(sys.argv[2])
    variant = sys.argv[3] if len(sys.argv) > 3 else "a"
    for p in range(npages):
        if variant == "a":
            # white with a black square top-left
            def pf(x,y):
                if x < 2 and y < 2: return (0,0,0)
                return (255,255,255)
        else:
            # white with a black square bottom-right (different)
            def pf(x,y):
                if x >= 2 and y >= 2: return (0,0,0)
                return (255,255,255)
        make_png(f"{prefix}-{p+1}.png", 4, 4, pf)
