package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

// ---------------- Flag ----------------

type Flag struct {
	Name      string
	Shorthand string
	Usage     string
	Type      string // "string", "bool"
	DefValue  string
	Value     string
	Changed   bool
	NoOptDef  string // for bool flags, default when no arg
}

type FlagSet struct {
	flags     []*Flag
	byName    map[string]*Flag
	byShort   map[string]*Flag
}

func newFlagSet() *FlagSet {
	return &FlagSet{byName: map[string]*Flag{}, byShort: map[string]*Flag{}}
}

func (fs *FlagSet) add(f *Flag) {
	fs.flags = append(fs.flags, f)
	fs.byName[f.Name] = f
	if f.Shorthand != "" {
		fs.byShort[f.Shorthand] = f
	}
}

func (fs *FlagSet) String(name, short, def, usage string) *Flag {
	f := &Flag{Name: name, Shorthand: short, Usage: usage, Type: "string", DefValue: def, Value: def}
	fs.add(f)
	return f
}

func (fs *FlagSet) Bool(name, short string, def bool, usage string) *Flag {
	dv := "false"
	if def {
		dv = "true"
	}
	f := &Flag{Name: name, Shorthand: short, Usage: usage, Type: "bool", DefValue: dv, Value: dv, NoOptDef: "true"}
	fs.add(f)
	return f
}

func (fs *FlagSet) lookup(name string) *Flag { return fs.byName[name] }
func (fs *FlagSet) lookupShort(s string) *Flag { return fs.byShort[s] }

func (fs *FlagSet) hasFlags() bool { return len(fs.flags) > 0 }

func (fs *FlagSet) GetString(name string) string {
	f := fs.byName[name]
	if f == nil {
		return ""
	}
	return f.Value
}
func (fs *FlagSet) GetBool(name string) bool {
	f := fs.byName[name]
	if f == nil {
		return false
	}
	return f.Value == "true"
}

// flagUsages produces pflag-compatible output.
func (fs *FlagSet) flagUsages() string {
	type entry struct {
		left  string
		usage string
	}
	var entries []entry
	maxlen := 0
	// pflag sorts flags alphabetically by default (SortFlags=true)
	sorted := make([]*Flag, len(fs.flags))
	copy(sorted, fs.flags)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Name < sorted[j].Name })
	for _, f := range sorted {
		var line string
		if f.Shorthand != "" {
			line = fmt.Sprintf("  -%s, --%s", f.Shorthand, f.Name)
		} else {
			line = fmt.Sprintf("      --%s", f.Name)
		}
		varname, usage := unquoteUsage(f)
		if varname != "" {
			line += " " + varname
		}
		// NoOptDefVal handling omitted (no such flags here)
		lineWithSentinel := line + "\x00"
		if len(lineWithSentinel) > maxlen {
			maxlen = len(lineWithSentinel)
		}
		// default value
		if !defaultIsZeroValue(f) {
			if f.Type == "string" {
				usage += fmt.Sprintf(" (default %q)", f.DefValue)
			} else {
				usage += fmt.Sprintf(" (default %s)", f.DefValue)
			}
		}
		entries = append(entries, entry{left: line, usage: usage})
	}
	var sb strings.Builder
	for _, e := range entries {
		sidx := len(e.left)
		spacing := strings.Repeat(" ", maxlen-sidx)
		// Fprintln(buf, left, spacing, usage) => left + " " + spacing + " " + usage + "\n"
		sb.WriteString(e.left)
		sb.WriteString(" ")
		sb.WriteString(spacing)
		sb.WriteString(" ")
		sb.WriteString(e.usage)
		sb.WriteString("\n")
	}
	return sb.String()
}

func defaultIsZeroValue(f *Flag) bool {
	switch f.Type {
	case "bool":
		return f.DefValue == "false"
	case "string":
		return f.DefValue == ""
	}
	return false
}

// unquoteUsage returns the varname and usage. For string flags, varname = "string".
func unquoteUsage(f *Flag) (string, string) {
	usage := f.Usage
	// Look for backtick-quoted name in usage
	for i := 0; i < len(usage); i++ {
		if usage[i] == '`' {
			for j := i + 1; j < len(usage); j++ {
				if usage[j] == '`' {
					name := usage[i+1 : j]
					usage = usage[:i] + name + usage[j+1:]
					return name, usage
				}
			}
			break
		}
	}
	name := ""
	switch f.Type {
	case "string":
		name = "string"
	}
	return name, usage
}

// ---------------- Command ----------------

type Command struct {
	Use     string
	Short   string
	Long    string
	Example string
	Aliases []string
	Run     func(c *Command, args []string)

	persistentFlags *FlagSet
	localFlags      *FlagSet
	// excludeInherited lists names of inherited flags to hide in help for this command
	excludeInherited map[string]bool

	parent   *Command
	children []*Command

	disableFlagsInUseLine bool
}

func (c *Command) PersistentFlags() *FlagSet {
	if c.persistentFlags == nil {
		c.persistentFlags = newFlagSet()
	}
	return c.persistentFlags
}
func (c *Command) Flags() *FlagSet {
	if c.localFlags == nil {
		c.localFlags = newFlagSet()
	}
	return c.localFlags
}

func (c *Command) AddCommand(cmds ...*Command) {
	for _, cmd := range cmds {
		cmd.parent = c
		c.children = append(c.children, cmd)
	}
}

func (c *Command) Name() string {
	name := c.Use
	if i := strings.Index(name, " "); i >= 0 {
		name = name[:i]
	}
	return name
}
func (c *Command) HasParent() bool { return c.parent != nil }
func (c *Command) Parent() *Command { return c.parent }
func (c *Command) CommandPath() string {
	if c.HasParent() {
		return c.parent.CommandPath() + " " + c.Name()
	}
	return c.Name()
}
func (c *Command) Runnable() bool { return c.Run != nil }

func (c *Command) hasSubCommands() bool { return len(c.children) > 0 }
func (c *Command) hasAvailableSubCommands() bool {
	for _, cmd := range c.children {
		if !cmd.hidden() {
			return true
		}
	}
	return false
}
func (c *Command) hidden() bool { return false }

func (c *Command) useLine() string {
	var useline string
	if c.HasParent() {
		useline = c.parent.CommandPath() + " " + c.Use
	} else {
		useline = c.Use
	}
	if c.disableFlagsInUseLine {
		return useline
	}
	if c.hasAvailableFlags() && !strings.Contains(useline, "[flags]") {
		useline += " [flags]"
	}
	return useline
}

// localFlagsForHelp: own local + own persistent
func (c *Command) localFlagsForHelp() *FlagSet {
	fs := newFlagSet()
	if c.localFlags != nil {
		for _, f := range c.localFlags.flags {
			fs.add(f)
		}
	}
	if c.persistentFlags != nil {
		for _, f := range c.persistentFlags.flags {
			fs.add(f)
		}
	}
	return fs
}

// inheritedFlagsForHelp: persistent flags from parents (excluding own)
func (c *Command) inheritedFlagsForHelp() *FlagSet {
	fs := newFlagSet()
	for p := c.parent; p != nil; p = p.parent {
		if p.persistentFlags != nil {
			for _, f := range p.persistentFlags.flags {
				if c.excludeInherited != nil && c.excludeInherited[f.Name] {
					continue
				}
				fs.add(f)
			}
		}
	}
	return fs
}

func (c *Command) hasAvailableLocalFlags() bool {
	return c.localFlagsForHelp().hasFlags()
}
func (c *Command) hasAvailableInheritedFlags() bool {
	return c.inheritedFlagsForHelp().hasFlags()
}

func (c *Command) hasAvailableFlags() bool {
	// for UseLine [flags] determination
	return c.localFlagsForHelp().hasFlags() || c.inheritedFlagsForHelp().hasFlags()
}

// allFlagsForParsing returns a combined flagset for parsing (local + persistent + inherited)
func (c *Command) allFlagsForParsing() *FlagSet {
	fs := newFlagSet()
	add := func(src *FlagSet) {
		if src == nil {
			return
		}
		for _, f := range src.flags {
			fs.add(f)
		}
	}
	add(c.localFlags)
	add(c.persistentFlags)
	for p := c.parent; p != nil; p = p.parent {
		add(p.persistentFlags)
	}
	return fs
}

func (c *Command) nameAndAliases() string {
	return strings.Join(append([]string{c.Name()}, c.Aliases...), ", ")
}

func (c *Command) commands() []*Command {
	sorted := make([]*Command, len(c.children))
	copy(sorted, c.children)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Name() < sorted[j].Name() })
	return sorted
}

func (c *Command) namePadding() int {
	const minNamePadding = 11
	maxLen := 0
	for _, cmd := range c.children {
		if cmd.hidden() {
			continue
		}
		if l := len(cmd.Name()); l > maxLen {
			maxLen = l
		}
	}
	if maxLen < minNamePadding {
		return minNamePadding
	}
	return maxLen
}

func rpad(s string, padding int) string {
	return fmt.Sprintf("%-*s", padding, s)
}

func trimRightSpace(s string) string {
	return strings.TrimRight(s, " \t\n\r")
}

func (c *Command) UsageString() string {
	var sb strings.Builder
	sb.WriteString("Usage:")
	if c.Runnable() {
		sb.WriteString("\n  " + c.useLine())
	}
	if c.hasAvailableSubCommands() {
		sb.WriteString("\n  " + c.CommandPath() + " [command]")
	}
	if len(c.Aliases) > 0 {
		sb.WriteString("\n\nAliases:\n  " + c.nameAndAliases())
	}
	if c.Example != "" {
		sb.WriteString("\n\nExamples:\n" + c.Example)
	}
	if c.hasAvailableSubCommands() {
		sb.WriteString("\n\nAvailable Commands:")
		pad := c.namePadding()
		for _, cmd := range c.commands() {
			if cmd.hidden() {
				continue
			}
			sb.WriteString("\n  " + rpad(cmd.Name(), pad) + " " + cmd.Short)
		}
	}
	if c.hasAvailableLocalFlags() {
		sb.WriteString("\n\nFlags:\n" + trimRightSpace(c.localFlagsForHelp().flagUsages()))
	}
	if c.hasAvailableInheritedFlags() {
		sb.WriteString("\n\nGlobal Flags:\n" + trimRightSpace(c.inheritedFlagsForHelp().flagUsages()))
	}
	if c.hasAvailableSubCommands() {
		sb.WriteString("\n\nUse \"" + c.CommandPath() + " [command] --help\" for more information about a command.")
	}
	sb.WriteString("\n")
	return sb.String()
}

func (c *Command) HelpString() string {
	var sb strings.Builder
	long := c.Long
	if long == "" {
		long = c.Short
	}
	if long != "" {
		sb.WriteString(trimRightSpace(long))
		sb.WriteString("\n\n")
	}
	if c.Runnable() || c.hasSubCommands() {
		sb.WriteString(c.UsageString())
	}
	return sb.String()
}

// ---------------- parsing ----------------

type parseResult struct {
	flags *FlagSet
	args  []string
}

// parseFlags parses pflag-style. Returns positional args.
func (c *Command) parseFlags(args []string) (positional []string, err error) {
	fs := c.allFlagsForParsing()
	i := 0
	for i < len(args) {
		s := args[i]
		i++
		if len(s) == 0 || s[0] != '-' || s == "-" {
			positional = append(positional, s)
			continue
		}
		if s == "--" {
			positional = append(positional, args[i:]...)
			break
		}
		if strings.HasPrefix(s, "--") {
			name := s[2:]
			var value string
			hasValue := false
			if eq := strings.Index(name, "="); eq >= 0 {
				value = name[eq+1:]
				name = name[:eq]
				hasValue = true
			}
			f := fs.lookup(name)
			if f == nil {
				return positional, fmt.Errorf("unknown flag: --%s", name)
			}
			if f.Type == "bool" {
				if hasValue {
					f.Value = value
				} else {
					f.Value = f.NoOptDef
				}
				f.Changed = true
			} else {
				if !hasValue {
					if i >= len(args) {
						return positional, fmt.Errorf("flag needs an argument: --%s", name)
					}
					value = args[i]
					i++
				}
				f.Value = value
				f.Changed = true
			}
		} else {
			// shorthand cluster
			chars := s[1:]
			for j := 0; j < len(chars); j++ {
				ch := string(chars[j])
				f := fs.lookupShort(ch)
				if f == nil {
					return positional, fmt.Errorf("unknown shorthand flag: %q in -%s", ch, chars)
				}
				if f.Type == "bool" {
					f.Value = f.NoOptDef
					f.Changed = true
					continue
				}
				// string flag: rest of cluster is value, or next arg
				rest := chars[j+1:]
				if len(rest) > 0 {
					if rest[0] == '=' {
						rest = rest[1:]
					}
					f.Value = rest
					f.Changed = true
				} else {
					if i >= len(args) {
						return positional, fmt.Errorf("flag needs an argument: %q in -%s", ch, chars)
					}
					f.Value = args[i]
					i++
					f.Changed = true
				}
				break
			}
		}
	}
	return positional, nil
}

// ---------------- execution ----------------

func (c *Command) findSub(name string) *Command {
	for _, cmd := range c.children {
		if cmd.Name() == name {
			return cmd
		}
		for _, a := range cmd.Aliases {
			if a == name {
				return cmd
			}
		}
	}
	return nil
}

// Execute runs the root command
func (root *Command) Execute() int {
	args := os.Args[1:]
	return root.execute(args)
}

func (root *Command) execute(args []string) int {
	cmd, cmdArgs, err := root.find(args)
	if err != nil {
		fmt.Fprintln(os.Stderr, "Error:", err.Error())
		fmt.Fprintln(os.Stderr, "Run '"+root.CommandPath()+" --help' for usage.")
		return 1
	}
	// handle help flag specially before parsing? cobra checks help flag in parsing
	positional, perr := cmd.parseFlags(cmdArgs)
	if perr != nil {
		fmt.Fprintln(os.Stderr, "Error:", perr.Error())
		fmt.Fprintln(os.Stderr, cmd.UsageString())
		return 1
	}
	// help flag
	if cmd.allFlagsForParsing().GetBool("help") {
		fmt.Fprint(os.Stdout, cmd.HelpString())
		return 0
	}
	if !cmd.Runnable() {
		// non-runnable: show help
		fmt.Fprint(os.Stdout, cmd.HelpString())
		return 0
	}
	cmd.Run(cmd, positional)
	return exitCode
}

var exitCode int

// find walks the command tree resolving aliases and subcommands.
func (root *Command) find(args []string) (*Command, []string, error) {
	cmd := root
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "" || a[0] == '-' {
			break
		}
		sub := cmd.findSub(a)
		if sub == nil {
			break
		}
		cmd = sub
		i++
	}
	rest := args[i:]
	// If cmd is root and there are leftover non-flag args that aren't subcommands -> unknown command
	if cmd == root && len(rest) > 0 && rest[0] != "" && rest[0][0] != '-' {
		return nil, nil, fmt.Errorf("unknown command %q for %q", rest[0], root.CommandPath())
	}
	return cmd, rest, nil
}

func (c *Command) addHelpFlag() {
	if c.localFlags == nil {
		c.localFlags = newFlagSet()
	}
	if c.localFlags.lookup("help") == nil && c.persistentFlags == nil || (c.persistentFlags == nil) {
		// ensure help not duplicated
	}
	if c.localFlags.lookup("help") == nil {
		c.localFlags.Bool("help", "h", false, "help for "+c.Name())
	}
}

// helper for parsing bool from string
func parseBool(s string) bool {
	b, _ := strconv.ParseBool(s)
	return b
}
