package main

import (
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"time"
)

// ---------------- slog error helper ----------------

var logger *slog.Logger

func initLogger(debug bool) {
	opts := &slog.HandlerOptions{Level: slog.LevelInfo}
	if debug {
		opts.Level = slog.LevelDebug
	}
	handler := slog.NewTextHandler(os.Stderr, opts)
	logger = slog.New(handler)
}

// ---------------- storage ----------------

type Store struct {
	dir     string
	inMem   bool
	data    map[string][]byte
	loaded  bool
	readOnly bool
}

// resolveDBPath returns the database directory path.
func resolveDBPath() string {
	if v := os.Getenv("ZEIT_DATABASE"); v != "" {
		return v
	}
	base := os.Getenv("XDG_DATA_HOME")
	if base == "" {
		home, _ := os.UserHomeDir()
		base = filepath.Join(home, ".local", "share")
	}
	return filepath.Join(base, "zeit", "db")
}

func dataFilePath(dir string) string {
	return filepath.Join(dir, "zeit.json")
}

// openStore opens the database. If readOnly, it errors when the dir/file
// doesn't exist (mimicking badger's read-only open).
func openStore(readOnly bool) (*Store, error) {
	dir := resolveDBPath()
	if dir == "" {
		// in-memory
		return &Store{inMem: true, data: map[string][]byte{}}, nil
	}
	if readOnly {
		// emulate badger read-only: directory must exist & be a DB
		st, err := os.Stat(dir)
		if err != nil || !st.IsDir() {
			logger.Error("Error initializing database\n", "error",
				fmt.Sprintf("Cannot find directory %q for read-only open", dir))
			return nil, fmt.Errorf("db error")
		}
		if _, err := os.Stat(dataFilePath(dir)); err != nil {
			logger.Error("Error initializing database\n", "error",
				"no manifest found, required for read-only db")
			return nil, fmt.Errorf("db error")
		}
	}
	s := &Store{dir: dir, readOnly: readOnly, data: map[string][]byte{}}
	if err := s.load(); err != nil && !readOnly {
		// ignore for new DBs
	}
	return s, nil
}

func openStoreRW() (*Store, error) {
	dir := resolveDBPath()
	if dir == "" {
		return &Store{inMem: true, data: map[string][]byte{}}, nil
	}
	logger.Debug("Using ZEIT_DATABASE directory for database", "directory", dir)
	if err := os.MkdirAll(dir, 0700); err != nil {
		return nil, err
	}
	s := &Store{dir: dir, data: map[string][]byte{}}
	if err := s.load(); err != nil {
		// new DB is fine
	}
	return s, nil
}

func (s *Store) load() error {
	if s.inMem {
		return nil
	}
	b, err := os.ReadFile(dataFilePath(s.dir))
	if err != nil {
		return err
	}
	var m map[string]json.RawMessage
	if err := json.Unmarshal(b, &m); err != nil {
		return err
	}
	for k, v := range m {
		s.data[k] = v
	}
	return nil
}

func (s *Store) save() error {
	if s.inMem || s.readOnly {
		return nil
	}
	m := map[string]json.RawMessage{}
	for k, v := range s.data {
		m[k] = v
	}
	b, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(dataFilePath(s.dir), b, 0644)
}

func (s *Store) get(key string, out interface{}) bool {
	v, ok := s.data[key]
	if !ok {
		return false
	}
	return json.Unmarshal(v, out) == nil
}

func (s *Store) set(key string, val interface{}) {
	b, _ := json.Marshal(val)
	s.data[key] = b
}

func (s *Store) del(key string) {
	delete(s.data, key)
}

func (s *Store) keysWithPrefix(prefix string) []string {
	var ks []string
	for k := range s.data {
		if strings.HasPrefix(k, prefix) {
			ks = append(ks, k)
		}
	}
	return ks
}

// ---------------- high-level helpers ----------------

func (s *Store) getConfig() *Config {
	c := &Config{}
	if !s.get("config", c) {
		return nil
	}
	return c
}

func (s *Store) ensureConfig() *Config {
	c := s.getConfig()
	if c == nil {
		c = &Config{UserKey: newUUID()}
		s.set("config", c)
	}
	return c
}

func (s *Store) getActiveBlock() *ActiveBlock {
	ab := &ActiveBlock{}
	if !s.get("activeblock", ab) {
		return &ActiveBlock{}
	}
	return ab
}

func (s *Store) getBlock(key string) *Block {
	if !strings.HasPrefix(key, "block:") {
		key = "block:" + key
	}
	b := &Block{}
	if !s.get(key, b) {
		return nil
	}
	return b
}

func (s *Store) allBlocks() []*Block {
	var blocks []*Block
	for _, k := range s.keysWithPrefix("block:") {
		b := &Block{}
		if s.get(k, b) {
			blocks = append(blocks, b)
		}
	}
	return blocks
}

func (s *Store) findProject(sid string) (*Project, string) {
	for _, k := range s.keysWithPrefix("project:") {
		p := &Project{}
		if s.get(k, p) && p.SID == sid {
			return p, k
		}
	}
	return nil, ""
}

func (s *Store) findTask(projectSID, taskSID string) (*Task, string) {
	for _, k := range s.keysWithPrefix("task:") {
		t := &Task{}
		if s.get(k, t) && t.SID == taskSID && t.ProjectSID == projectSID {
			return t, k
		}
	}
	return nil, ""
}

func (s *Store) allProjects() []*Project {
	var ps []*Project
	for _, k := range s.keysWithPrefix("project:") {
		p := &Project{}
		if s.get(k, p) {
			ps = append(ps, p)
		}
	}
	return ps
}

func (s *Store) allTasks() []*Task {
	var ts []*Task
	for _, k := range s.keysWithPrefix("task:") {
		t := &Task{}
		if s.get(k, t) {
			ts = append(ts, t)
		}
	}
	return ts
}

// ensureProjectAndTask creates project/task if they don't exist.
func (s *Store) ensureProjectAndTask(projectSID, taskSID string) {
	if projectSID == "" {
		return
	}
	if p, _ := s.findProject(projectSID); p == nil {
		p := &Project{
			OwnerKey:    s.ensureConfig().UserKey,
			SID:         projectSID,
			DisplayName: strings.ToUpper(projectSID),
			Color:       randomColor(),
		}
		s.set("project:"+newUUID(), p)
	}
	if taskSID == "" {
		return
	}
	if t, _ := s.findTask(projectSID, taskSID); t == nil {
		t := &Task{
			OwnerKey:    s.ensureConfig().UserKey,
