package main

import (
	"crypto/rand"
	"encoding/binary"
	"encoding/hex"
	"fmt"
	"math/big"
	"strings"
	"time"
)

// newUUID generates a UUIDv7 (time-ordered) like the original.
func newUUID() string {
	now := time.Now()
	ms := now.UnixMilli()
	var b [16]byte
	// bytes 0-5: 48-bit unixms (big-endian)
	b[0] = byte(ms >> 40)
	b[1] = byte(ms >> 32)
	b[2] = byte(ms >> 24)
	b[3] = byte(ms >> 16)
	b[4] = byte(ms >> 8)
	b[5] = byte(ms)
	// bytes 6-7: version 0111 + 12 random bits
	var rnd [10]byte
	rand.Read(rnd[:])
	b[6] = 0x70 | (rnd[0] & 0x0F)
	b[7] = rnd[1]
	// byte 8: variant 10 + 6 random
	b[8] = 0x80 | (rnd[2] & 0x3F)
	for i := 3; i < 10; i++ {
		b[9+i-3] = rnd[i]
	}
	_ = binary.BigEndian
	return fmt.Sprintf("%s-%s-%s-%s-%s",
		hex.EncodeToString(b[0:4]),
		hex.EncodeToString(b[4:6]),
		hex.EncodeToString(b[6:8]),
		hex.EncodeToString(b[8:10]),
		hex.EncodeToString(b[10:16]),
	)
}

// randomColor generates a random hex color like the original (#RRGGBB).
func randomColor() string {
	// Generate random muted color in HSL space, converted to hex.
	max := big.NewInt(360)
	h, _ := rand.Int(rand.Reader, max)
	hue := int(h.Int64())
	r, g, b := hslToRGB(float64(hue), 0.30, 0.50)
	return fmt.Sprintf("#%02X%02X%02X", r, g, b)
}

func hslToRGB(h, s, l float64) (int, int, int) {
	c := (1 - mathabs(2*l-1)) * s
	x := c * (1 - mathabs(mathMod(h/60.0, 2)-1))
	m := l - c/2
	var r, g, b float64
	switch {
	case h < 60:
		r, g, b = c, x, 0
	case h < 120:
		r, g, b = x, c, 0
	case h < 180:
		r, g, b = 0, c, x
	case h < 240:
		r, g, b = 0, x, c
	case h < 300:
		r, g, b = x, 0, c
	default:
		r, g, b = c, 0, x
	}
	return toInt(r, m), toInt(g, m), toInt(b, m)
}

func toInt(v, m float64) int {
	return int((v + m) * 255)
}

func mathabs(x float64) float64 {
	if x < 0 {
		return -x
	}
	return x
}

func mathMod(a, b float64) float64 {
	m := a
	for m >= b {
		m -= b
	}
	return m
}

// validateSID checks whether a string is a valid simplified ID.
var sidAllowed = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-"

func isValidSID(s string) bool {
	if s == "" {
		return false
	}
	for _, r := range s {
		if !strings.ContainsRune(sidAllowed, r) {
			return false
		}
	}
	return true
}

// simplify generates a SID from a display name.
func simplify(name string) string {
	var sb strings.Builder
	for _, r := range name {
		if strings.ContainsRune(sidAllowed, r) {
			sb.WriteRune(r)
		}
	}
	return sb.String()
}
EOF
echo done"}}

