func runStart(c *Command, args []string) {
	x := newCtx(c)
	pa := parseStartArgs(c, args)
	x.args = pa
	logger.Debug("Parsed args", "pargs", pa.debugString(), "GetTimestampStart", pa.start, "GetTimestampEnd", pa.end)
	pa.process()
	logger.Debug("Processed args", "pargs", pa.debugString(), "GetTimestampStart", pa.start, "GetTimestampEnd", pa.end)

	s, err := openStoreRW()
	if err != nil {
		logger.Error("Error initializing database\n", "error", err)
		exitCode = 1
		return
	}
	x.store = s
	defer s.save()

	if pa.project == "" {
		fmt.Println("▲ A project SID is required")
		exitCode = 1
		return
	}
	if pa.task == "" {
		fmt.Println("▲ A task SID is required")
		exitCode = 1
		return
	}

	startTime := pa.start
	if startTime.IsZero() {
		startTime = time.Now()
	}
	endTime := pa.end

	// if there's an active block, end it first
	ab := s.getActiveBlock()
	if ab.ActiveBlockKey != "" {
		active := s.getBlock(ab.ActiveBlockKey)
		if active != nil {
			activeEnd := startTime.Add(-1 * time.Second)
			if !endTime.IsZero() {
				// start with end: just finish the active block normally?
			}
			if !endTime.IsZero() {
				// new finished block; check same project/task
				if active.ProjectSID == pa.project && active.TaskSID == pa.task {
					fmt.Println("▲ The project/task SIDs for the new block are the same as for the currently running one")
				}
			}
			if !activeEnd.After(active.Start) {
				fmt.Println("▲ The end time/date must be after the start time/date")
				exitCode = 1
				return
			}
			active.End = activeEnd
			s.set(ab.ActiveBlockKey, active)
		}
	}

	if !endTime.IsZero() {
		if !endTime.After(startTime) {
			fmt.Println("▲ The end time/date must be after the start time/date")
			exitCode = 1
			return
		}
	}

	s.ensureProjectAndTask(pa.project, pa.task)
	blk := &Block{
		OwnerKey:   s.ensureConfig().UserKey,
		ProjectSID: pa.project,
		TaskSID:    pa.task,
		Note:       pa.note,
		Start:      startTime,
		End:        endTime,
	}
	key := "block:" + newUUID()
	s.set(key, blk)

	newAB := &ActiveBlock{}
	if !endTime.IsZero() {
		newAB.PreviousBlockKey = ab.ActiveBlockKey
		if newAB.PreviousBlockKey == "" {
			newAB.PreviousBlockKey = ab.PreviousBlockKey
		}
	} else {
		newAB.ActiveBlockKey = key
		newAB.PreviousBlockKey = ab.ActiveBlockKey
	}
	s.set("activeblock", newAB)

	if endTime.IsZero() {
		fmt.Printf("▶ Started tracking on %s/%s ...\n", pa.project, pa.task)
	} else {
		fmt.Printf("▶ Tracked on %s/%s.\n", pa.project, pa.task)
	}
}

