	x.store = s
	defer s.save()

	ab := s.getActiveBlock()
	if ab.ActiveBlockKey == "" {
		fmt.Println("▲ Nothing to end")
		exitCode = 1
		return
	}
	blk := s.getBlock(ab.ActiveBlockKey)
	if blk == nil {
		fmt.Println("▲ Nothing to end")
		exitCode = 1
		return
