	if !endTime.After(blk.Start) {
		fmt.Println("▲ The end time/date must be after the start time/date")
		exitCode = 1
		return
	}
	blk.End = endTime
	if pa.note != "" {
		blk.Note = pa.note
	}
	s.set(ab.ActiveBlockKey, blk)
	newAB := &ActiveBlock{ActiveBlockKey: "", PreviousBlockKey: ab.ActiveBlockKey}
	s.set("activeblock", newAB)
