	return isRangeToken(s)
}

func isRangeToken(s string) bool {
	switch s {
	case "today", "yesterday", "this", "last":
		return true
	}
	return false
}

func consumeRange(tokens []string, i int) (string, int) {
	t := tokens[i]
	switch t {
	case "today", "yesterday":
		return t, i + 1
	case "this", "last":
		if i+1 < len(tokens) {
			next := tokens[i+1]
			switch next {
			case "week", "month":
				return t + " " + next, i + 2
			}
		}
	}
	return "", i + 1
}

func applyRange(p *parsedArgs, r string) {
	now := time.Now()
	p.hasTime = true
	switch r {
	case "today":
		p.timestampStart = now
		p.TimestampStart = "" // handled via timestampStart
		p.hasTime = true
	case "yesterday":
		p.timestampStart = time.Date(now.Year(), now.Month(), now.Day()-1, 0, 0, 0, 0, now.Location())
		p.timestampEnd = time.Date(now.Year(), now.Month(), now.Day()-1, 23, 59, 59, 0, now.Location())
	case "this week":
		p.timestampStart = startOfWeek(now)
		p.timestampEnd = endOfToday(now)
	case "last week":
		ws := startOfWeek(now).AddDate(0, 0, -7)
		p.timestampStart = ws
		p.timestampEnd = ws.AddDate(0, 0, 6)
		p.timestampEnd = time.Date(p.timestampEnd.Year(), p.timestampEnd.Month(), p.timestampEnd.Day(), 23, 59, 59, 0, p.timestampEnd.Location())
	case "this month":
		p.timestampStart = time.Date(now.Year(), now.Month(), 1, 0, 0, 0, 0, now.Location())
		p.timestampEnd = endOfToday(now)
	case "last month":
		y, m := now.Year(), now.Month()-1
		if m == 0 {
			y--
			m = 12
		}
		p.timestampStart = time.Date(y, m, 1, 0, 0, 0, 0, now.Location())
		p.timestampEnd = time.Date(y, m, 31, 23, 59, 59, 0, now.Location())
	}
}

func startOfWeek(now time.Time) time.Time {
	// Monday-based week start (Go: Weekday() Sunday=0)
	days := int(now.Weekday())
	if days == 0 {
		days = 7
	}
	days--
	return time.Date(now.Year(), now.Month(), now.Day()-days, 0, 0, 0, 0, now.Location())
}
func endOfToday(now time.Time) time.Time {
	return time.Date(now.Year(), now.Month(), now.Day(), 23, 59, 59, 0, now.Location())
}

// consumeTime consumes a time expression (possibly multi-word like "4 hours ago")
func consumeTime(tokens []string, i int) (string, int) {
	if i >= len(tokens) {
		return "", i
	}
	// quoted string already a single token
	t := tokens[i]
	if t == "now" {
		return "now", i + 1
	}
	// "N units ago" / "N units from now" / "N units"
	re := regexp.MustCompile(`^[-+]?\d+(\.\d+)?(:\d+)?$`)
	if re.MatchString(t) {
		// "4 hours ago" pattern
		if i+2 < len(tokens) && (tokens[i+2] == "ago" || tokens[i+2] == "from") {
			expr := t + " " + tokens[i+1] + " " + tokens[i+2]
			if tokens[i+2] == "from" && i+3 < len(tokens) && tokens[i+3] == "now" {
				expr += " now"
				return expr, i + 4
			}
			return expr, i + 3
		}
		if i+1 < len(tokens) && isUnit(tokens[i+1]) {
			expr := t + " " + tokens[i+1]
			return expr, i + 2
		}
		return t, i + 1
	}
	// date or time
	if isTimeToken(t) {
		return t, i + 1
	}
	return t, i + 1
}

func isUnit(s string) bool {
	switch s {
	case "second", "seconds", "sec", "secs", "minute", "minutes", "min", "mins", "hour", "hours", "h", "day", "days", "d", "week", "weeks", "w", "month", "months", "m", "year", "years", "y":
		return true
	}
	return false
}

func isTimeToken(s string) bool {
	if s == "now" || s == "today" || s == "yesterday" {
		return true
	}
	if _, ok := parseTime(s); ok {
		return true
	}
	// "4 hours ago" detection
	re := regexp.MustCompile(`^[-+]?\d+(\.\d+)?(:\d+)?$`)
	if re.MatchString(s) {
		return true
	}
	return false
}

// ---------------- time parsing ----------------

func parseTime(s string) (time.Time, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return time.Time{}, false
	}
	now := time.Now()
	if s == "now" {
		return now, true
	}
	// "N units ago" / "N units from now"
	if t, ok := parseRelative(s, now); ok {
		return t, true
	}
	// relative clock: -0:15, +1.50
	if t, ok := parseClockRelative(s, now); ok {
		return t, true
	}
	// formats
	layouts := []string{
		"2006-01-02 15:04:05",
		"2006-01-02 15:04",
		"2006-01-02",
		"15:04:05",
		"15:04",
		"2006-01-02T15:04:05Z07:00",
		"2006-01-02T15:04:05",
		"2006-01-02T15:04:05Z",
	}
	for _, layout := range layouts {
		if t, err := time.Parse(layout, s); err == nil {
			// for time-only, combine with today
			if layout == "15:04:05" || layout == "15:04" {
				return time.Date(now.Year(), now.Month(), now.Day(), t.Hour(), t.Minute(), t.Second(), 0, now.Location()), true
			}
			if layout == "2006-01-02" {
				return t, true
			}
			return t, true
		}
	}
	// "yesterday HH:MM"
	if strings.HasPrefix(s, "yesterday") {
		rest := strings.TrimSpace(strings.TrimPrefix(s, "yesterday"))
		if rest == "" {
			return time.Date(now.Year(), now.Month(), now.Day()-1, 0, 0, 0, 0, now.Location()), true
		}
		for _, layout := range []string{"15:04:05", "15:04"} {
			if t, err := time.Parse(layout, rest); err == nil {
				return time.Date(now.Year(), now.Month(), now.Day()-1, t.Hour(), t.Minute(), t.Second(), 0, now.Location()), true
			}
		}
	}
	return time.Time{}, false
}

func parseRelative(s string, now time.Time) (time.Time, bool) {
	// "4 hours ago", "10 minutes ago", "5 min ago", "2 days ago", "N units from now"
	parts := strings.Fields(s)
	if len(parts) == 3 && parts[2] == "ago" {
		d, ok := unitDuration(parts[0], parts[1])
		if !ok {
			return time.Time{}, false
		}
		return now.Add(-d), true
	}
	if len(parts) == 4 && parts[2] == "from" && parts[3] == "now" {
		d, ok := unitDuration(parts[0], parts[1])
		if !ok {
			return time.Time{}, false
		}
		return now.Add(d), true
	}
	return time.Time{}, false
}

func unitDuration(numStr, unit string) (time.Duration, bool) {
	n, err := strconv.ParseFloat(numStr)
	if err != nil {
		return 0, false
	}
	switch unit {
	case "second", "seconds", "sec", "secs":
		return time.Duration(n * float64(time.Second)), true
	case "minute", "minutes", "min", "mins":
		return time.Duration(n * float64(time.Minute)), true
	case "hour", "hours", "h":
		return time.Duration(n * float64(time.Hour)), true
	case "day", "days", "d":
		return time.Duration(n * 24 * float64(time.Hour)), true
	case "week", "weeks", "w":
		return time.Duration(n * 7 * 24 * float64(time.Hour)), true
	case "month", "months", "m":
		return time.Duration(n * 30 * 24 * float64(time.Hour)), true
	case "year", "years", "y":
		return time.Duration(n * 365 * 24 * float64(time.Hour)), true
	}
	return 0, false
}

func parseClockRelative(s string, now time.Time) (time.Time, bool) {
	// "-0:15" => now - 15min, "+1.50" => now + 1h30m
	if len(s) < 2 {
		return time.Time{}, false
	}
	if s[0] != '-' && s[0] != '+' {
		return time.Time{}, false
	}
	sign := 1
	if s[0] == '-' {
		sign = -1
	}
	rest := s[1:]
	if strings.Contains(rest, ":") {
		// H:MM
		parts := strings.SplitN(rest, ":", 2)
		h, err1 := strconv.Atoi(parts[0])
		m, err2 := strconv.Atoi(parts[1])
		if err1 != nil || err2 != nil {
			return time.Time{}, false
		}
		return now.Add(time.Duration(sign) * (time.Duration(h)*time.Hour + time.Duration(m)*time.Minute)), true
	}
	if f, err := strconv.ParseFloat(rest); err == nil {
		hours := int(f)
		mins := int((f - float64(hours)) * 100)
		return now.Add(time.Duration(sign) * (time.Duration(hours)*time.Hour + time.Duration(mins)*time.Minute)), true
	}
	return time.Time{}, false
}

// parseTaskArgs parses "project/task" or "project task" into project and task SID.
func parseTaskArgs(args []string) (string, string) {
	if len(args) == 0 {
		return "", ""
	}
	first := args[0]
	if strings.Contains(first, "/") {
		parts := strings.SplitN(first, "/", 2)
		if parts[1] == "" {
			return parts[0], ""
		}
		return parts[0], parts[1]
	}
	if len(args) >= 2 {
		return first, args[1]
	}
	return first, ""
}
