			out = append(out, b)
		}
	}
	return out
}

func sumBlocks(blocks []*Block, projectSID, taskSID string) (int, time.Duration) {
	count := 0
	var dur time.Duration
	for _, b := range blocks {
		if projectSID != "" && b.ProjectSID != projectSID {
			continue
		}
		if taskSID != "" && b.TaskSID != taskSID {
			continue
		}
		count++
		dur += blockDurComputed(b)
	}
	return count, dur
}

func sumBlocksTask(blocks []*Block) (int, time.Duration) {
	count := 0
	var dur time.Duration
	for _, b := range blocks {
		count++
		dur += blockDurComputed(b)
	}
	return count, dur
}

func blockDurComputed(b *Block) time.Duration {
	if b.End.IsZero() {
		return 0
	}
	return b.End.Sub(b.Start)
}

