func doStat(x *ctx, pa *parsedArgs) {
	s := x.store
	blocks := s.allBlocks()
	type key struct{ p, t, d string }
	totals := map[key]time.Duration{}
	var grand time.Duration
	for _, b := range blocks {
		if pa.project != "" && b.ProjectSID != pa.project {
			continue
		}
		if pa.task != "" && b.TaskSID != pa.task {
			continue
		}
		if !blockInFilter(b, pa.timestampStart, pa.timestampEnd) {
			continue
		}
		dur := blockDurComputed(b)
		date := b.Start.Format("2006-01-02")
		totals[key{b.ProjectSID, b.TaskSID, date}] += dur
		grand += dur
	}
	if x.format == "json" {
		statJSON(pa, totals, grand)
