	// group by project, task, date
	projs := map[string]map[string]map[string]time.Duration{}
	for k, v := range totals {
		if projs[k.p] == nil {
			projs[k.p] = map[string]map[string]time.Duration{}
		}
		if projs[k.p][k.t] == nil {
			projs[k.p][k.t] = map[string]time.Duration{}
		}
		projs[k.p][k.t][k.d] += v
	}
	var pkeys []string
