	sort.Strings(pkeys)
	for _, p := range pkeys {
		fmt.Printf("%s %s\n", iconBlock, p)
		var tkeys []string
		for t := range projs[p] {
			tkeys = append(tkeys, t)
		}
		sort.Strings(tkeys)
		for _, t := range tkeys {
			fmt.Printf("    %s\n", t)
			var dkeys []string
			for d := range projs[p][t] {
				dkeys = append(dkeys, d)
			}
			sort.Strings(dkeys)
			for _, d := range dkeys {
				fmt.Printf("      %s: %s\n", d, fmtDuration(projs[p][t][d]))
			}
		}
	}
	fmt.Printf("%s Total: %s\n", iconBlock, fmtDuration(grand))
}

func statJSON(pa *parsedArgs, totals map[struct{ p, t, d string }]time.Duration, grand time.Duration) {
	// Build nested map
	byProj := map[string]map[string]map[string]int64{}
	for k, v := range totals {
		if byProj[k.p] == nil {
			byProj[k.p] = map[string]map[string]int64{}
		}
		if byProj[k.p][k.t] == nil {
			byProj[k.p][k.t] = map[string]int64{}
		}
		byProj[k.p][k.t][k.d] += int64(v)
	}
	out := map[string]interface{}{}
	out["*"] = map[string]interface{}{
		"*": map[string]interface{}{
			"*": int64(grand),
		},
	}
	for p, tasks := range byProj {
		tm := map[string]interface{}{}
		for t, dates := range tasks {
			dm := map[string]int64{}
			for d, v := range dates {
				dm[d] = v
			}
			tm[t] = dm
		}
		out[p] = tm
	}
	b, _ := json.MarshalIndent(out, "", "  ")
	fmt.Println(string(b))
}

