//go:embed comp/zsh.txt
var compZsh string

//go:embed comp/fish.txt
var compFish string

//go:embed comp/powershell.txt
var compPowershell string

func newCompletionCmd() *Command {
	c := &Command{
		Use:   "completion",
		Short: "Generate the autocompletion script for the specified shell",
		Long:  "Generate the autocompletion script for zeit for the specified shell.\nSee each sub-command's help for details on how to use the generated script.",
	}
	c.addHelpFlag()

	bash := &Command{
		Use:                   "bash",
		Short:                 "Generate the autocompletion script for bash",
		Long:                  compBashLong,
		disableFlagsInUseLine: true,
		Run: func(cmd *Command, args []string) {
			fmt.Print(compBash)
		},
	}
	bash.Flags().Bool("no-descriptions", "", false, "disable completion descriptions")
	bash.addHelpFlag()

	zsh := &Command{
		Use:   "zsh",
		Short: "Generate the autocompletion script for zsh",
		Long:  compZshLong,
		Run: func(cmd *Command, args []string) {
			fmt.Print(compZsh)
		},
	}
	zsh.Flags().Bool("no-descriptions", "", false, "disable completion descriptions")
	zsh.addHelpFlag()

	fish := &Command{
		Use:   "fish",
		Short: "Generate the autocompletion script for fish",
		Long:  compFishLong,
		Run: func(cmd *Command, args []string) {
			fmt.Print(compFish)
		},
	}
	fish.Flags().Bool("no-descriptions", "", false, "disable completion descriptions")
	fish.addHelpFlag()

	powershell := &Command{
		Use:   "powershell",
		Short: "Generate the autocompletion script for powershell",
		Long:  compPowershellLong,
		Run: func(cmd *Command, args []string) {
			fmt.Print(compPowershell)
		},
	}
	powershell.Flags().Bool("no-descriptions", "", false, "disable completion descriptions")
	powershell.addHelpFlag()

	c.AddCommand(bash, zsh, fish, powershell)
	return c
}

const compBashLong = "Generate the autocompletion script for the bash shell.\n\nThis script depends on the 'bash-completion' package.\nIf it is not installed already, you can install it via your OS's package manager.\n\nTo load completions in your current shell session:\n\n\tsource <(zeit completion bash)\n\nTo load completions for every new session, execute once:\n\n#### Linux:\n\n\tzeit completion bash > /etc/bash_completion.d/zeit\n\n#### macOS:\n\n\tzeit completion bash > $(brew --prefix)/etc/bash_completion.d/zeit\n\nYou will need to start a new shell for this setup to take effect."

