func newHelpCmd(root *Command) *Command {
	c := &Command{
		Use:   "help [command]",
		Short: "Help about any command",
		Long:  "Help provides help for any command in the application.\nSimply type zeit help [path to command] for full details.",
		Run: func(cmd *Command, args []string) {
			target := root
			ok := true
			for _, a := range args {
				next := target.findSub(a)
				if next == nil {
					ok = false
					break
				}
				target = next
			}
			if !ok {
				fmt.Fprintf(os.Stderr, "Unknown help topic %v\n", args)
				return
			}
			fmt.Fprint(os.Stdout, target.HelpString())
		},
	}
	c.addHelpFlag()
	return c
}
