cat > timeparse.go <<'EOF'
package main

import (
	"regexp"
	"strconv"
	"strings"
	"time"
)

var relPairRe = regexp.MustCompile(`(?i)(?P<n>\d+(?:\.\d+)?)\s*(?P<unit>seconds?|secs?|minutes?|mins?|hours?|hrs?|days?|weeks?|months?|mons?|years?|yrs?|h|m|s|d|y|mo)`)
var agoRe = regexp.MustCompile(`(?i)\bago\b`)

func parseTime(s string) (time.Time, bool) {
	s = strings.TrimSpace(s)
	if s == "" {
		return time.Time{}, false
	}
	now := time.Now()
	if strings.EqualFold(s, "now") {
		return now, true
	}
	// compound relative: "N unit [N unit ...] [ago]" possibly with leading sign
	if t, ok := parseCompoundRelative(s, now); ok {
		return t, true
	}
	// yesterday [time]
	if strings.HasPrefix(strings.ToLower(s), "yesterday") {
		rest := strings.TrimSpace(s[len("yesterday"):])
		if rest == "" {
			return time.Date(now.Year(), now.Month(), now.Day()-1, 0, 0, 0, 0, now.Location()), true
		}
		for _, layout := range []string{"15:04:05", "15:04"} {
			if t, err := time.Parse(layout, rest); err == nil {
				return time.Date(now.Year(), now.Month(), now.Day()-1, t.Hour(), t.Minute(), t.Second(), 0, now.Location()), true
			}
		}
	}
	// date/time layouts
	layouts := []string{
		"2006-01-02 15:04:05",
		"2006-01-02 15:04",
		"2006-01-02",
		"2006-01-02T15:04:05Z07:00",
		"2006-01-02T15:04:05",
		"2006-01-02T15:04:05Z",
	}
	for _, layout := range layouts {
		if t, err := time.Parse(layout, s); err == nil {
			return t, true
		}
	}
	// time-only
	for _, layout := range []string{"15:04:05", "15:04"} {
		if t, err := time.Parse(layout, s); err == nil {
			return time.Date(now.Year(), now.Month(), now.Day(), t.Hour(), t.Minute(), t.Second(), 0, now.Location()), true
		}
	}
	return time.Time{}, false
}

func parseCompoundRelative(s string, now time.Time) (time.Time, bool) {
	// Must consist of number+unit pairs and an optional "ago". Reject "from now".
	lower := strings.ToLower(s)
	if strings.Contains(lower, "from") || strings.Contains(lower, "until") {
		return time.Time{}, false
	}
	// strip leading sign
	trimmed := strings.TrimLeft(s, "+-")
	// Check that after removing pairs and "ago", nothing remains
	// Find all pairs
	matches := relPairRe.FindAllStringSubmatch(trimmed, -1)
	if len(matches) == 0 {
		return time.Time{}, false
	}
	// Reconstruct consumed text to ensure full match
	consumed := strings.TrimSpace(relPairRe.ReplaceAllString(trimmed, ""))
	consumed = strings.TrimSpace(strings.ReplaceAll(consumed, "ago", ""))
	consumed = strings.TrimSpace(strings.ReplaceAll(consumed, "AGO", ""))
	if consumed != "" {
		return time.Time{}, false
	}
	hasAgo := agoRe.MatchString(trimmed)
	_ = hasAgo
	// always past (ago) for this format
	var years, months, days int
	var dur time.Duration
	for _, m := range matches {
		nf, err := strconv.ParseFloat(m[1], 64)
		if err != nil {
			return time.Time{}, false
		}
		unit := strings.ToLower(m[2])
		switch unit {
		case "h", "hr", "hrs", "hour", "hours":
			dur += time.Duration(nf * float64(time.Hour))
		case "m", "min", "mins", "minute", "minutes":
			dur += time.Duration(nf * float64(time.Minute))
		case "s", "sec", "secs", "second", "seconds":
			dur += time.Duration(nf * float64(time.Second))
		case "d", "day", "days":
			dur += time.Duration(nf * 24 * float64(time.Hour))
		case "week", "weeks":
			dur += time.Duration(nf * 7 * 24 * float64(time.Hour))
		case "mo", "mon", "mons", "month", "months":
			months += int(nf)
		case "y", "yr", "yrs", "year", "years":
			years += int(nf)
		default:
			return time.Time{}, false
		}
	}
	result := now.AddDate(-years, -months, -days).Add(-dur)
	return result, true
}
EOF
