{"name": "bash", "arguments": {"command": "cd /workspace
cat > import.go <<'EOF'
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"time"
)

func doImport(x *ctx, path, format string) error {
	f, err := os.Open(path)
	if err != nil {
		fmt.Printf("%s %s\n", iconErr, err.Error())
		exitCode = 1
		return nil
	}
	defer f.Close()
	var raw map[string]json.RawMessage
	if err := json.NewDecoder(f).Decode(&raw); err != nil {
		fmt.Printf("%s %s\n", iconErr, err.Error())
		exitCode = 1
		return nil
	}
	s := x.store
	cfg := s.ensureConfig()
	if format == "v0" {
		// v0: map of block:UUID -> block
		for k, v := range raw {
			if !strings.HasPrefix(k, "block:") {
				continue
			}
			var b Block
			if json.Unmarshal(v, &b) == nil {
				b.OwnerKey = cfg.UserKey
				b._key = k
				s.set(k, b)
				s.ensureProjectAndTask(b.ProjectSID, b.TaskSID)
			}
		}
	} else {
		// v1: backup with all entities
		for k, v := range raw {
			switch {
			case k == "activeblock":
				var ab ActiveBlock
				if json.Unmarshal(v, &ab) == nil {
					s.set("activeblock", ab)
				}
			case k == "config":
				var c Config
				if json.Unmarshal(v, &c) == nil {
					s.set("config", c)
				}
			case strings.HasPrefix(k, "block:"):
				var b Block
				if json.Unmarshal(v, &b) == nil {
					b._key = k
					s.set(k, b)
				}
			case strings.HasPrefix(k, "project:"):
				var p Project
				if json.Unmarshal(v, &p) == nil {
					p._key = k
					s.set(k, p)
				}
			case strings.HasPrefix(k, "task:"):
				var t Task
				if json.Unmarshal(v, &t) == nil {
					t._key = k
					s.set(k, t)
				}
			}
		}
	}
	fmt.Println("● Import finished")
	_ = time.Now
	return nil
}
EOF
